-- 000088_pte_writing_bank_3.up.sql
-- Batch C: 150 original PTE Writing practice questions (50 SWT, 50 WE, 50 REQ).
-- Deterministic IDs pte-b3-<task>-<nnn>. Replay-safe INSERT ... ON CONFLICT DO NOTHING.

INSERT INTO questions (id, exam_version_id, exam, skill, type_id, type_name, title, prompt, context_passage, audio_transcript, image_url, figure_data, model_answer, prep_time_seconds, time_limit_seconds, points, difficulty, explanation, tags, supported_exams, is_published) VALUES
    ('pte-b3-swt-001', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Measuring Ocean Temperature with Sound Waves', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Measuring deep ocean temperature across vast oceanic basins has traditionally relied on point measurements taken by research vessels and autonomous floating probes. However, because sound travels through water at speeds directly influenced by temperature and salinity, oceanographers have developed acoustic thermometry to measure average water temperatures across entire ocean basins. In this method, specialized acoustic transmitters emit low-frequency sound pulses that travel through the natural oceanic acoustic channel for thousands of kilometers before being detected by receiving hydrophones. Because warmer water transmits acoustic waves more quickly than colder water, minute shifts in the arrival times of these pulses reveal precise variations in average oceanic thermal energy. Unlike point probes, which can only capture conditions in their immediate vicinity, acoustic pulses naturally integrate temperature measurements along their entire underwater trajectory. This broad integration provides climate researchers with valuable empirical data on large-scale oceanic warming trends, helping to calibrate global climate models and quantify the vast amounts of excess heat absorbed by marine environments.', NULL, NULL, NULL, 'By analyzing the travel times of low-frequency sound pulses across ocean basins, acoustic thermometry allows scientists to track broad ocean warming trends more comprehensively than isolated spot measurements.', 0, 600, 10, 'medium', 'Highlight how acoustic travel time relates to ocean water temperature, and why large-scale acoustic integration provides superior data compared to localized sampling points.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-002', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Preserving Rare Books from Environmental Damage', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Rare book archives and historical manuscript libraries house delicate paper volumes that are exceptionally vulnerable to environmental degradation. Historically, collection conservators relied on chemical fumigants and pesticides to protect valuable bindings from mold outbreaks and insect infestations. However, many of these chemical compounds left hazardous residues, accelerated paper brittleness, and posed health hazards to library staff. Modern archival institutions have consequently shifted toward passive environmental controls and non-toxic atmospheric modification. Archival storage vaults now maintain strict indoor climatic stability by regulating ambient relative humidity and temperature within narrow bands, depriving fungal spores of the moisture required for germination. When active insect infestations are detected in historic materials, conservators seal the affected volumes within sealed enclosures and replace the surrounding air with inert gases such as nitrogen or argon. Deprived of oxygen over several weeks, the pests are eradicated completely without exposing fragile rag paper, historic inks, or animal skin bindings to destructive chemical treatments or physical moisture.', NULL, NULL, NULL, 'Modern historical libraries preserve delicate paper manuscripts by regulating vault temperature and humidity and using inert gas enclosures rather than harmful chemical treatments to eliminate pests and mold.', 0, 600, 10, 'medium', 'Explain the shift away from toxic fumigants toward controlled indoor humidity and inert gas treatments for protecting rare archival volumes.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-003', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Generating Biogas from Household Organic Waste', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Organic kitchen scraps and discarded food waste comprise a major fraction of municipal household garbage, frequently ending up in landfills where decomposing organic matter generates methane and leaches contaminants into surrounding soils. To capture this lost energy, municipal waste authorities are deploying large-scale anaerobic digestion facilities that convert organic refuse into renewable biogas. Inside sealed bioreactors, diverse communities of specialized microorganisms break down carbohydrates, proteins, and fats in an oxygen-free environment. This multi-stage biological digestion generates a gaseous mixture primarily composed of methane and carbon dioxide. Once scrubbed of impurities and moisture, this biomethane can be injected directly into municipal natural gas grids to heat homes or fuel municipal bus fleets. Furthermore, the solid and liquid byproduct remaining after digestion, known as digestate, is rich in essential plant nutrients such as nitrogen and potassium. When processed properly, this nutrient-dense digestate serves as an organic agricultural fertilizer, replacing synthetic chemical fertilizers and completing a circular nutrient recovery cycle.', NULL, NULL, NULL, 'Anaerobic digestion of municipal food waste inside oxygen-free reactors produces renewable biomethane for heating and transport while generating nutrient-rich organic fertilizer for agricultural soils.', 0, 600, 10, 'medium', 'Summarize how anaerobic digestion transforms organic waste into both clean biomethane energy and valuable organic agricultural fertilizer.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-004', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Water Conservation with Precision Drip Irrigation', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Traditional surface irrigation methods, such as flooding furrows or operating overhead spray sprinklers, lose large volumes of water through atmospheric evaporation, wind dispersion, and deep percolation beyond crop root zones. In arid and semi-arid agricultural regions confronting water scarcity, precision drip irrigation offers a far more sustainable alternative. Drip systems deliver water through pressurized networks of flexible plastic tubing fitted with calibrated emitters placed directly beside plant root systems. By releasing small, continuous droplets at controlled rates, these emitters moisten only the immediate soil zone where active roots absorb moisture, leaving surrounding inter-row soil completely dry. This localized application prevents water loss to evaporation and drastically suppresses weed growth by denying moisture to unwanted seeds. Modern drip installations frequently incorporate electronic soil moisture sensors and automated valves, ensuring that water delivery matches the precise physiological transpiration demands of crops throughout different growing phases. As a result, farmers achieve higher crop yields while reducing overall water and energy consumption.', NULL, NULL, NULL, 'Precision drip irrigation conserves agricultural water and suppresses weed growth by delivering calibrated water droplets directly to plant root zones based on actual crop physiological needs.', 0, 600, 10, 'medium', 'State the operational principle of drip emitters delivering water exclusively to roots, contrasting it with evaporation losses in traditional spraying.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-005', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Monitoring Bridge Safety with Fiber-Optic Sensors', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Highway bridges and rail viaducts endure continuous mechanical stress from heavy vehicular loads, temperature fluctuations, and corrosive environmental exposure. Routine visual inspections conducted by maintenance engineers cannot always detect internal material fatigue or micro-cracks before structural damage occurs. To improve infrastructure safety, civil engineers now embed fiber-optic sensor arrays directly within bridge decks, support pillars, and suspension cables. These optical sensors utilize specialized microscopic light reflectors called fiber Bragg gratings etched along the core of thin glass fibers. When a bridge component experiences mechanical bending, stretching, or thermal expansion, the optical fiber stretches slightly, altering the wavelength of light reflected through the glass cable. Central monitoring computers continuously analyze these wavelength shifts in real time to calculate minute structural deformations with exceptional precision. Because fiber-optic cables are immune to electromagnetic interference from lightning strikes and high-voltage transmission lines, they provide reliable long-term safety data, alerting maintenance crews to structural deterioration long before catastrophic failure occurs.', NULL, NULL, NULL, 'Embedding fiber-optic sensors within bridge components enables continuous real-time monitoring of structural stress and deformation by measuring reflected light wavelength shifts caused by physical strain.', 0, 600, 10, 'medium', 'Explain how fiber Bragg gratings detect structural strain via light wavelength alterations, providing early warning of material fatigue without electromagnetic interference.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-006', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Earth Observation Using Satellite Radar Imagery', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Optical satellite photography has long been a primary tool for mapping Earth''s surface and tracking natural disasters. However, optical cameras are fundamentally limited by environmental conditions, as cloud cover, smoke plumes, and night prevent optical lenses from capturing clear surface imagery. Synthetic aperture radar satellites overcome these limitations by transmitting active microwave pulses toward Earth''s surface and recording the backscattered signals reflected back to the orbiting spacecraft. Because microwave radiation easily penetrates cloud layers, dense fog, and atmospheric aerosols, radar satellites can image planetary landscapes reliably day and night under all meteorological conditions. Furthermore, by comparing the precise phase differences between radar images captured over the same geographical coordinates at different times, scientists can measure subtle ground movements of only a few millimeters. This interferometric technique allows geologists to track tectonic fault slip, monitor volcanic magma swelling, and detect land subsidence caused by excessive groundwater pumping with extraordinary geographic precision.', NULL, NULL, NULL, 'Synthetic aperture radar satellites provide reliable day-and-night surface imagery through cloud cover and track minute millimeter-scale ground movements by analyzing reflected microwave signals.', 0, 600, 10, 'medium', 'Summarize how active microwave radar penetrates clouds in all weather conditions and allows interferometric measurement of subtle ground deformations.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-007', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Fossil Shells as Records of Ancient Oceans', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Reconstructing historical climatic changes requires reliable geological archives that record oceanic conditions long before human instruments existed. Microscopic single-celled organisms called foraminifera dwell abundantly in ocean waters, constructing tiny calcium carbonate shells from dissolved chemical elements. As these organisms grow, they incorporate isotopes of oxygen and trace elements like magnesium into their shells in direct proportion to the surrounding water''s temperature and chemical composition. When the organisms die, their mineralized shells sink to the ocean floor, accumulating in undisturbed sedimentary layers over millions of years. Paleoclimatologists extract deep sediment cores from the seafloor and examine these fossilized shells under electron microscopes. By measuring the ratio of oxygen isotopes preserved within the fossilized carbonate, researchers can determine whether past eras experienced warm global climates or expanded continental ice sheets. These marine fossil archives provide an essential baseline for understanding how Earth''s climate system has naturally responded to past fluctuations in atmospheric carbon dioxide and solar radiation.', NULL, NULL, NULL, 'Chemical and isotopic ratios preserved within fossilized microscopic marine shells provide scientists with an essential geological archive for reconstructing past ocean temperatures and global ice volumes.', 0, 600, 10, 'medium', 'Describe how microscopic marine shells incorporate environmental chemical signals, creating seafloor sedimentary records of historical ocean temperatures.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-008', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Urban Heating from Geothermal Water Networks', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Heating residential and commercial buildings during cold winter months consumes enormous amounts of fossil energy, generating substantial carbon emissions in urban areas. In regions with accessible subsurface thermal resources, municipal districts are replacing individual fossil boilers with centralized geothermal heating networks. Production wells drill deep into permeable subterranean rock formations to extract warm geothermal water that has absorbed heat from Earth''s interior. At centralized heat exchange stations, this thermal fluid transfers its energy to a secondary closed network of insulated pipes that circulates warm water to radiators and floor heating systems across entire city neighborhoods. Because the extracted geothermal brine never enters domestic plumbing and is reinjected back into deep underground aquifers through dedicated injection wells, the subsurface thermal reservoir is preserved without depleting regional water tables. District geothermal networks provide steady, baseload heating that is unaffected by outdoor weather extremes, offering cities a reliable, low-carbon heating infrastructure with minimal operating fuel expenses.', NULL, NULL, NULL, 'Centralized geothermal district networks provide reliable, low-carbon urban heating by extracting naturally warm subsurface water to heat neighborhoods through closed heat exchangers before reinjecting the fluid underground.', 0, 600, 10, 'medium', 'Explain how geothermal district heating extracts underground warm water, transfers thermal energy via closed pipe networks, and reinjects the fluid to maintain the reservoir.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-009', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'How Seed Dormancy Protects Crops Against Drought', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'In wild ecosystems, plant species rely on seed dormancy to ensure that seeds germinate only when environmental conditions are favorable for seedling survival. Seed dormancy is regulated by a delicate biochemical balance between plant hormones, principally abscisic acid, which inhibits germination, and gibberellins, which promote growth. During historical crop domestication, early agriculturalists deliberately selected crop varieties with low seed dormancy so that sown fields would germinate rapidly and uniformly. However, in modern agricultural systems exposed to erratic rainfall and severe seasonal droughts, seeds that sprout too rapidly risk complete mortality if initial rains are followed by prolonged dry periods. Plant geneticists are therefore studying wild crop relatives to reintroduce controlled levels of adaptive dormancy into commercial cereal varieties. Crops engineered with calibrated dormancy mechanisms pause development when soil moisture drops below critical thresholds, resuming growth only when soil water reserves are sufficient. This genetic adaptation prevents premature field sprouting, enhancing crop resilience against unpredictable climate shocks.', NULL, NULL, NULL, 'Reintroducing controlled seed dormancy mechanisms into modern crops prevents premature germination during temporary rains, allowing seedlings to survive unpredictable dry spells and climatic volatility.', 0, 600, 10, 'medium', 'Summarize the role of seed dormancy in preventing early sprouting during irregular rainfall, protecting crops against post-germination drought failure.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-010', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'River Moisture Corridors in Global Weather Patterns', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Atmospheric rivers are long, narrow filaments of concentrated water vapor that transport immense volumes of moisture from warm tropical oceans to mid-latitude continental landmasses. Spanning thousands of kilometers in length while remaining only a few hundred kilometers wide, a single atmospheric river can carry a water vapor flux greater than the combined discharge of the world''s largest terrestrial rivers. When these moisture-laden corridors encounter coastal mountain ranges, the air is forced upward, cooling rapidly and condensing into intense rainfall and heavy mountain snowpacks. In many arid and semi-arid coastal regions, atmospheric rivers provide the vast majority of annual freshwater replenishment, filling municipal reservoirs and sustaining agricultural irrigation systems for the year ahead. However, exceptionally strong atmospheric rivers can also trigger catastrophic flooding and landslides when continuous heavy precipitation overwhelms drainage systems. Consequently, meteorological agencies employ advanced satellite tracking and ocean radar to forecast atmospheric river trajectories, allowing water managers to balance flood safety with reservoir storage.', NULL, NULL, NULL, 'Atmospheric moisture corridors transport vast amounts of tropical water vapor to continental coasts, providing vital annual water reserves while requiring careful meteorological tracking to manage severe flood risks.', 0, 600, 10, 'medium', 'Define atmospheric rivers as narrow moisture corridors, explaining their essential contribution to annual water supplies and their potential to cause severe flooding.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-011', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Acoustic Insulation from Recycled Cotton Fibers', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Modern building construction requires effective acoustic insulation to reduce noise transmission between adjacent apartments and offices. Historically, architectural soundproofing has relied on synthetic mineral wool or fiberglass panels, which require energy-intensive manufacturing processes and release airborne irritant fibers during handling and installation. In response, sustainable materials scientists have developed high-performance acoustic insulation panels made from discarded textile waste, particularly recycled denim and cotton clothing. Discarded garments are mechanically shredded into fine fibers, treated with non-toxic borate mineral salts to impart flame resistance and fungal protection, and thermally bonded into dense, porous batting. The chaotic, intertwined structure of natural cotton fibers creates countless microscopic air pockets that effectively trap and dissipate sound energy through viscous thermal friction. These porous textile battings fit snugly between standard interior wall studs, dampening both airborne vocal frequencies and structural impact vibrations. By achieving sound absorption ratings comparable to conventional fiberglass while diverting discarded clothing from municipal landfills, recycled cotton panels provide a safe, environmentally friendly insulation alternative for modern interior architecture.', NULL, NULL, NULL, 'Acoustic insulation panels made from shredded recycled cotton textiles dissipate sound effectively through natural fiber air pockets while reducing landfill textile waste and eliminating hazardous synthetic fibers.', 0, 600, 10, 'medium', 'Explain how recycled cotton insulation panels achieve soundproofing through microscopic air pockets, avoiding the airborne irritants and environmental costs of fiberglass.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-012', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Constructed Wetlands for Treating Wastewater', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Treating municipal and agricultural wastewater conventionally requires mechanized treatment facilities that consume large quantities of electrical power and expensive chemical flocculants. In rural and peri-urban communities, constructed treatment wetlands offer an effective, low-energy ecological alternative. These engineered ecosystems consist of shallow, gravel-lined basins planted with wetland vegetation such as cattails, reeds, and bulrushes. As wastewater flows slowly through the gravel bed and plant root zones, physical, chemical, and biological purification mechanisms operate simultaneously. Suspended solid particles settle naturally between the plant stems, while dense biofilms of beneficial bacteria adhering to the gravel and roots break down organic pollutants. Wetland plants absorb dissolved nitrogen and phosphorus through their root systems, preventing these nutrients from triggering toxic algal blooms in downstream rivers. Constructed wetlands require minimal mechanical maintenance, generate no hazardous chemical sludge, and provide valuable secondary habitats for local wildlife while purifying effluent to safe discharge standards. In addition to removing harmful contaminants, these systems create microclimates that buffer regional hydrology against sudden stormwater surges.', NULL, NULL, NULL, 'Constructed treatment wetlands purify wastewater naturally through gravel filtration, bacterial decomposition, and plant nutrient uptake without requiring heavy electrical power or industrial chemicals.', 0, 600, 10, 'medium', 'Describe how gravel basins and wetland plants combine to filter solids, consume nutrients, and support bacterial decomposition of wastewater pollutants naturally.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-013', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Separating Industrial Nitrogen from Atmospheric Air', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Pure nitrogen gas is indispensable across modern industries, serving as an inert protective atmosphere for semiconductor fabrication, food packaging, and chemical manufacturing. Producing commercial quantities of high-purity nitrogen relies on cryogenic air separation, a thermodynamic process that exploits the differing boiling points of atmospheric gases. Ambient air is first filtered to eliminate airborne dust, compressed to high pressure, and thoroughly purified to remove moisture and carbon dioxide, which would otherwise freeze solid at cryogenic temperatures. The dried air is then passed through a series of counter-current heat exchangers and expansion turbines, cooling the gas mixture until it liquefies. Inside insulated distillation columns, the liquid air is warmed incrementally. Because nitrogen boils at a lower temperature than oxygen and argon, it vaporizes first and rises toward the top of the column, where it is collected as pure gas. This industrial separation delivers continuous supplies of pure nitrogen with remarkable efficiency. The isolated nitrogen gas is then compressed into high-pressure storage cylinders or transferred via insulated pipelines directly to nearby industrial consumers.', NULL, NULL, NULL, 'Cryogenic air separation produces high-purity industrial nitrogen by compressing, cooling, and liquefying ambient air, then separating its components based on their distinct boiling points in distillation columns.', 0, 600, 10, 'medium', 'Explain how air is compressed, cooled to a liquid, and fractionally distilled based on the boiling point differences of nitrogen and oxygen.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-014', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Soil Conservation with Seasonal Cover Crops', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Leaving agricultural fields bare between main harvesting and spring planting exposes topsoil to severe degradation from wind erosion and torrential seasonal rains. When heavy raindrops strike unprotected soil, they dislodge fine silt particles, compacting the ground surface and washing nutrient-rich organic matter into nearby waterways. Planting seasonal cover crops, such as rye, clover, or winter peas, protects vulnerable farmland during fallow periods. The dense canopy of cover crops intercepts falling rain, dissipating its kinetic energy and preventing surface crusting. Below ground, extensive living root networks bind soil particles together, improving soil porosity and accelerating water infiltration. When legumes are included in the cover crop mix, symbiotic root bacteria capture atmospheric nitrogen, naturally enriching the soil with essential plant nutrients. Before spring planting, the cover crops are terminated and incorporated into the ground, where decaying biomass builds soil organic carbon, enhances water retention, and reduces reliance on chemical fertilizers. Furthermore, diverse mixed cover crops suppress persistent agricultural weeds naturally by blocking sunlight and releasing biochemical growth inhibitors into the soil.', NULL, NULL, NULL, 'Planting seasonal cover crops during fallow periods shields topsoil from erosion, improves water infiltration with dense root networks, and naturally enriches the earth with organic nutrients.', 0, 600, 10, 'medium', 'Highlight how cover crop canopies and root systems prevent soil erosion and crusting while adding natural nitrogen and organic matter to fields.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-015', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Biological Control of Algal Blooms in Reservoirs', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Drinking water reservoirs and agricultural lakes frequently experience excessive blooms of cyanobacteria, commonly known as blue-green algae, when agricultural runoff introduces elevated levels of phosphorus and nitrogen. These algal blooms deplete dissolved oxygen, kill aquatic organisms, and produce harmful toxins that endanger human and animal health. Treating algal outbreaks with chemical copper sulfate algaecides can eliminate blooms temporarily, but toxic copper accumulates in bottom sediments and harms non-target aquatic organisms. To manage reservoirs safely, aquatic managers are turning to biological and ecological control techniques. Deploying bundles of decomposing barley straw into lake margins releases natural phenolic compounds that inhibit algal cell division without harming fish or insect populations. Additionally, introducing submerged native aquatic plants competes directly with cyanobacteria for dissolved nutrients and sunlight, while stocking native herbivorous zooplankton provides continuous grazing pressure on algal cells, restoring natural ecological balance. By combining multiple biological interventions rather than relying on a single chemical treatment, reservoir operators maintain clear, high-quality drinking water while preserving complex freshwater food webs.', NULL, NULL, NULL, 'Aquatic managers control reservoir algal blooms safely by using barley straw compounds, submerged native plants, and grazing zooplankton rather than applying toxic chemical copper algaecides.', 0, 600, 10, 'medium', 'Explain the ecological disadvantages of copper algaecides and how natural barley compounds, plant competition, and zooplankton grazing suppress algal blooms safely.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-016', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Conservation of Waterlogged Wood from Ancient Shipwrecks', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'When historic wooden ships sink and become buried in deep, oxygen-depleted ocean mud, anaerobic conditions can preserve their timber structures for centuries. However, microscopic bacteria slowly degrade the wood''s structural cellulose, leaving the cellular cavities filled entirely with water. If such waterlogged timbers are excavated and allowed to dry naturally in open air, surface tension from evaporating water causes the hollowed wood cells to collapse, leading to catastrophic warping, shrinkage, and structural disintegration. To preserve excavated maritime artifacts, archaeological conservators immerse the waterlogged timber in large treatment tanks filled with solutions of polyethylene glycol, a water-soluble synthetic wax. Over several months or years, the wax gradually penetrates the porous wood, displacing the internal water and supporting the cell walls. Once the timber is thoroughly saturated with the wax, it can be dried slowly under controlled temperature and humidity conditions, allowing historic ships to be exhibited permanently in museums without dimensional distortion.', NULL, NULL, NULL, 'Preserving waterlogged wooden shipwrecks requires slowly replacing the internal cellular water with synthetic polyethylene glycol wax to prevent wood collapse and severe warping during museum drying.', 0, 600, 10, 'medium', 'Detail how degraded waterlogged wood cells collapse if air-dried, and how polyethylene glycol wax substitution stabilizes the timbers for long-term exhibition.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-017', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Marine Microorganisms and Oceanic Carbon Storage', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'The world''s oceans function as Earth''s largest active carbon reservoir, absorbing substantial fractions of human-generated carbon dioxide emissions from the atmosphere. A central mechanism driving this marine carbon storage is the biological carbon pump, powered by microscopic phytoplankton inhabiting sunlit surface waters. Through photosynthesis, these microscopic plants convert dissolved carbon dioxide into organic tissue. When phytoplankton are consumed by zooplankton or die naturally, a fraction of this organic matter aggregates into sinking particles commonly referred to as marine snow. As this organic debris drifts downward into the dark, cold depths of the ocean, it travels beyond the reach of ocean-atmosphere circulation. Much of the carbon is consumed by deep-sea organisms and converted into dissolved inorganic carbon, where it remains isolated from the atmosphere for hundreds of years. A small portion reaches the seabed, becoming permanently buried in marine sediments and locking carbon away over geological timescales. Over extended geological periods, this continuous gravitational settling of biological particles forms thick oceanic sediment layers that regulate global atmospheric chemistry.', NULL, NULL, NULL, 'The oceanic biological carbon pump sequesters atmospheric carbon dioxide as surface phytoplankton produce organic matter that sinks into the deep sea, isolating carbon for centuries or burying it in sediments.', 0, 600, 10, 'medium', 'Summarize how microscopic phytoplankton convert atmospheric carbon into organic debris that sinks into the deep ocean, isolating carbon from the atmosphere.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-018', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Street Orientation and Daylight in Urban Design', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Urban neighborhood layouts and street alignments exert a profound influence on building energy efficiency, pedestrian comfort, and indoor natural illumination. When planning municipal developments, urban designers evaluate how street geometry interacts with local solar trajectories throughout the changing seasons. Aligning primary residential streets along east-west axes maximizes southern solar exposure for building facades in the northern hemisphere. During cold winter months, when the sun travels low across the horizon, this orientation allows natural sunlight to penetrate deeply into living spaces, reducing artificial heating and lighting requirements. Conversely, carefully calculated street widths and building height ratios prevent tall structures from casting continuous, dark shadows over pedestrian sidewalks and opposing windows. In hot summer months, incorporating exterior shading louvers and deciduous roadside trees blocks intense midday solar glare, keeping interior spaces comfortable without excessive air conditioning. Thoughtful solar-oriented urban design creates vibrant, naturally illuminated public streets while lowering overall municipal energy consumption.', NULL, NULL, NULL, 'Carefully orienting urban street grids and balancing building heights with solar angles maximizes winter daylight, reduces indoor heating needs, and enhances outdoor pedestrian comfort throughout the year.', 0, 600, 10, 'medium', 'Explain how east-west street orientations and proportional building heights balance seasonal sunlight access, reducing energy consumption and improving urban livability.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-019', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Measuring Historical Lake Levels from Ancient Shorelines', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Understanding how regional rainfall patterns and continental moisture availability varied over past millennia requires examining natural geological records preserved across arid landscapes. In enclosed inland basins lacking ocean outlets, lakes expand and contract in direct response to regional precipitation and evaporation rates. During prolonged wet climatic intervals, expanding lake waters erode distinct wave-cut terraces and deposit linear gravel ridges along their shorelines. When regional climate shifts toward arid conditions, the water level drops, leaving these former shoreline terraces perched high above the modern lake basin as abandoned geological benches. Geomorphologists survey the elevation and geographic extent of these ancient strandlines using high-resolution aerial mapping and satellite elevation models. By determining the ages of beach gravels and fossil freshwater shells found on these elevated terraces, scientists can reconstruct the timing and magnitude of prehistoric moisture fluctuations, helping climate researchers evaluate future drought risks. By correlating ancient shorelines across multiple lake basins, geoscientists can separate localized tectonic shifts from continental-scale precipitation trends.', NULL, NULL, NULL, 'By mapping and dating elevated wave-cut shoreline terraces in enclosed lake basins, geomorphologists reconstruct historical regional precipitation shifts and evaluate long-term drought patterns.', 0, 600, 10, 'medium', 'Describe how perched wave-cut terraces and strandlines record former lake depths, providing evidence of historical wet and dry climatic periods.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-020', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Mechanical Flywheels for Grid Energy Storage', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Modern electrical grids increasingly depend on intermittent renewable energy sources such as wind turbines and solar photovoltaic farms, creating an urgent need for rapid-response energy storage systems to maintain grid frequency stability. While chemical lithium-ion batteries are widely deployed, mechanical flywheels offer a durable, high-power alternative for short-duration grid support. A modern flywheel energy storage system consists of a heavy, balanced composite rotor spinning inside an evacuated vacuum chamber on magnetic levitation bearings. When the electrical grid experiences surplus power, an integrated motor accelerates the rotor to extreme rotational speeds, storing electrical energy as kinetic energy. When sudden power demand creates an electrical deficit, the motor functions as a generator, slowing the rotor to inject electricity back into the grid within milliseconds. Because flywheels operate without chemical degradation, they endure hundreds of thousands of full charging cycles over decades of operation with negligible performance loss and zero toxic chemical waste.', NULL, NULL, NULL, 'Mechanical flywheel storage systems provide rapid grid stability by converting surplus electricity into kinetic energy with magnetically levitated rotors, offering durable performance without chemical degradation.', 0, 600, 10, 'medium', 'Explain how vacuum-sealed flywheels store and discharge electricity mechanically within milliseconds, avoiding chemical battery degradation.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-021', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Using Beneficial Insects in Greenhouse Crop Protection', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Commercial greenhouse vegetable production provides optimal warm, humid conditions that encourage rapid crop growth, but these enclosed environments also facilitate explosive outbreaks of herbivorous pests such as aphids, whiteflies, and spider mites. Repeatedly spraying chemical synthetic insecticides within enclosed greenhouses leads to rapid pesticide resistance and leaves undesirable chemical residues on fresh produce. Consequently, commercial horticulturalists have widely adopted biological pest control strategies that deploy natural insect predators. Specially bred predatory mites, parasitic wasps, and ladybird beetles are released into greenhouse canopies to hunt and parasitize specific agricultural pests. Because these beneficial insects reproduce within the crop canopy, they provide continuous, dynamic pest suppression that targets pests even on the undersides of leaves where chemical sprays fail to penetrate. Biological control safeguards greenhouse worker health, prevents chemical runoff, and ensures residue-free vegetables for consumer markets. Because these biological control agents adapt dynamically to changing pest numbers, greenhouse growers maintain stable ecological balances with minimal human intervention.', NULL, NULL, NULL, 'Commercial greenhouses employ beneficial predatory insects and parasitic wasps to suppress agricultural pests continuously, eliminating synthetic pesticide resistance and chemical residues on fresh vegetables.', 0, 600, 10, 'medium', 'Describe how predatory mites and wasps provide targeted biological pest control in greenhouses without chemical sprays or insecticidal resistance.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-022', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Underground Electrical Cables in Modern Cities', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Overhead electrical distribution lines supported by wooden or concrete poles are highly vulnerable to storm damage, falling tree limbs, and vehicle collisions, frequently resulting in widespread power outages during severe weather events. To enhance municipal infrastructure resilience and eliminate visual clutter, metropolitan utilities are transitioning power distribution lines to subterranean cable networks. High-voltage underground cables are encased within durable cross-linked polyethylene insulation, surrounded by protective metallic sheathing, and installed inside concrete utility conduits beneath city streets. Placed safely underground, these power lines are shielded from windstorms, ice accumulation, and accidental tree strikes, drastically reducing storm-related power interruptions. However, underground systems require substantial upfront capital expenditure for street excavation and require specialized diagnostic equipment to locate subterranean faults. Despite these initial engineering hurdles, the long-term operational reliability and disaster resilience of underground power networks make them an essential investment for modern climate-resilient cities. In rapidly growing urban centers, utility providers coordinate subterranean power line installation with municipal water and fiber-optic work to reduce road disruption.', NULL, NULL, NULL, 'Burying urban electrical cables in subterranean conduits shields municipal power distribution from storm damage and physical hazards, providing enhanced grid reliability despite higher initial installation expenses.', 0, 600, 10, 'medium', 'Summarize the durability advantages of underground power cables against severe storms and tree strikes despite higher initial excavation costs.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-023', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Audio Recorders for Monitoring Forest Wildlife', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Monitoring animal biodiversity in dense tropical rainforests is notoriously difficult because many wildlife species are secretive, nocturnal, or inhabit high forest canopies where human observers and camera traps rarely detect them. To survey these complex ecosystems without disturbing wildlife, conservation biologists are deploying passive acoustic monitoring networks. Small, weather-sealed digital audio recorders equipped with sensitive omnidirectional microphones are mounted on tree trunks across forested landscapes. These autonomous devices record ambient environmental soundscapes continuously or on programmed schedules over several months. Using automated pattern-recognition software, bioacoustic researchers analyze hundreds of hours of audio recordings to identify the unique vocalizations of endangered birds, primates, amphibians, and bats. In addition to cataloging species presence, acoustic data reveal vocalization rhythms, seasonal breeding cycles, and even illegal activities such as chainsaw logging and poaching gunshots, providing conservationists with a powerful, non-invasive tool for habitat management. By comparing sound recordings collected across different seasons, conservationists can track how habitat fragmentation and human encroachment alter animal vocal behaviors over time.', NULL, NULL, NULL, 'Autonomous digital audio recorders placed throughout dense forests enable biologists to monitor biodiversity and detect illegal logging non-invasively by analyzing animal vocalizations and environmental soundscapes.', 0, 600, 10, 'medium', 'Highlight how passive acoustic recorders capture wildlife vocalizations and soundscapes non-invasively in dense forests, aiding conservation and threat detection.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-024', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Heat Exchangers for Reclaiming Energy from Ceramic Kilns', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Industrial ceramic and tile manufacturing requires high-temperature kilns that burn large quantities of natural gas to fire clay products at temperatures exceeding one thousand degrees Celsius. Historically, immense quantities of high-grade thermal energy were vented directly into the atmosphere through factory exhaust stacks as hot flue gas. To reduce fuel consumption and cut industrial greenhouse gas emissions, modern ceramic plants install high-efficiency ceramic heat exchangers within kiln exhaust channels. These durable heat exchangers absorb thermal energy from the exiting flue gases without mixing the dirty exhaust air with incoming fresh air. The captured heat is redirected to preheat incoming combustion air entering the kiln burners, significantly reducing the fuel needed to reach operating temperatures. Surplus recovered thermal energy is channeled to adjacent clay drying chambers, where gentle warm air dries raw ceramic pieces prior to firing. Heat recovery substantially lowers industrial operational fuel expenses and improves environmental sustainability. Recovering and reusing this industrial thermal energy reduces both factory utility expenses and municipal greenhouse gas emissions without compromising manufacturing throughput.', NULL, NULL, NULL, 'Industrial heat exchangers capture high-temperature exhaust gas from ceramic kilns to preheat combustion air and dry raw materials, significantly reducing manufacturing fuel consumption and carbon emissions.', 0, 600, 10, 'medium', 'Explain how heat exchangers recover energy from kiln exhaust gases to preheat combustion air and dry raw clay, reducing fuel waste.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-025', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Generating Electricity with Bacteria from Wastewater', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Municipal wastewater treatment facilities are traditionally among the largest consumers of electrical energy in local government budgets, primarily due to the energy required to pump air into aeration basins. However, municipal sewage contains substantial chemical energy stored within dissolved organic compounds. Microbial fuel cells represent an emerging biotechnology that harnesses this energy directly by converting organic waste into electricity. In a microbial fuel cell, specialized bacteria colonize an anode electrode immersed in wastewater. As these electroactive microorganisms consume organic pollutants, their metabolic digestive processes strip electrons from the organic molecules. Instead of transferring these electrons to oxygen, the bacteria transfer them directly to the anode surface. The electrons flow through an external electrical circuit to a cathode chamber, producing a continuous direct electrical current while purifying the surrounding water. This innovative bioelectrochemical process transforms wastewater treatment from an energy-consuming burden into a net energy-producing resource. Ongoing biological research aims to optimize electrode materials and identify more resilient bacterial cultures to increase electrical generation rates for municipal facilities.', NULL, NULL, NULL, 'Microbial fuel cells convert the chemical energy in municipal wastewater directly into electrical current as electroactive bacteria break down organic waste and transfer electrons to electrodes.', 0, 600, 10, 'medium', 'Describe how bacteria in microbial fuel cells digest wastewater organics and transfer electrons to an electrical circuit, generating power while cleaning water.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-026', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Reconstructing Past Floods from River Gravel Deposits', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Gauging stations and historical flood records rarely span more than a century, leaving hydrologists with insufficient data to predict extreme, rare flood events. To reconstruct flood magnitudes over thousands of years, fluvial geomorphologists investigate sedimentary gravel deposits preserved in river valleys. During extreme high-water episodes, powerful floodwaters transport and deposit coarse gravel, cobbles, and boulders in protected channel backwaters and river terraces. Because the maximum physical grain size a river can transport is directly governed by water depth and hydraulic stream power, measuring the dimensions of the largest boulders in a flood layer allows researchers to calculate peak flood discharge rates. Sedimentologists dig stratigraphical trenches into riverbanks to identify distinct layers of flood gravel separated by fine silt deposited during normal low-flow periods. By dating organic material trapped within these gravel horizons using radiocarbon methods, scientists establish the frequency and magnitude of ancient flood catastrophes, providing civil planners with empirical baselines for designing flood defenses and reservoir spillways.', NULL, NULL, NULL, 'By analyzing the size and age of boulder and gravel layers deposited along river terraces, geomorphologists can reconstruct the magnitude and frequency of ancient flood events over historical millennia.', 0, 600, 10, 'medium', 'Explain how the physical grain size of deposited river gravel allows scientists to calculate ancient peak flood discharges and improve long-term flood planning.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-027', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Satellite Signal Refraction in Atmospheric Weather Tracking', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Accurate numerical weather forecasting depends on continuous global measurements of atmospheric temperature, pressure, and humidity. Gathering data over vast oceanic expanses and polar wilderness has traditionally been hindered by the scarcity of terrestrial meteorological stations. Atmospheric radio occultation provides an elegant global solution using existing constellations of navigation satellites. When a navigation satellite sets below Earth''s horizon relative to a low-orbiting receiver satellite, its radio signals must pass horizontally through Earth''s atmosphere. Because atmospheric density changes with altitude, the incoming radio waves refract and bend slightly, altering their arrival times at the receiving satellite. By measuring these minute nanosecond signal delays, meteorologists can derive vertical profiles of atmospheric refractivity, which directly correlate with temperature, pressure, and water vapor content. This satellite technique operates continuously across all geographic regions, requires no calibration instruments on the ground, and provides critical real-time atmospheric soundings that significantly enhance modern global weather forecasts. Incorporating these vertical refractivity profiles into predictive computer simulations has substantially improved five-day weather forecasting accuracy worldwide.', NULL, NULL, NULL, 'Atmospheric radio occultation measures the bending of satellite navigation signals passing through the air to derive accurate global profiles of temperature and humidity across remote oceans and polar regions.', 0, 600, 10, 'medium', 'Summarize how measuring the refraction of satellite radio signals through the atmosphere generates vertical temperature and humidity profiles without ground stations.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-028', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Cultivating Microscopic Algae for Liquid Biofuels', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Conventional first-generation biofuels derived from food crops like corn and soybeans compete directly for agricultural arable land and fresh irrigation water, raising ethical concerns about food security. Cultivating photosynthetic microalgae presents a promising sustainable alternative for renewable liquid fuel production. Microscopic algae produce high concentrations of natural lipids and oils through photosynthesis, accumulating these energy-rich compounds much faster than terrestrial plants. Furthermore, algae can be cultivated inside enclosed photobioreactors or shallow open raceway ponds built on marginal, non-arable desert land, eliminating competition with food agriculture. Algae can thrive in brackish water, saline groundwater, or nutrient-rich municipal wastewater, recycling industrial carbon dioxide emissions channeled directly into the growing basins. Once harvested, the extracted algal oils can be refined into drop-in renewable diesel and aviation kerosene that integrate seamlessly into existing engines and fuel pipelines. Although harvesting and drying microscopic cells remains energy-intensive, technological advancements in membrane filtration are steadily improving commercial viability.', NULL, NULL, NULL, 'Cultivating microscopic algae on non-arable land produces renewable liquid biofuels rapidly using saline water and recycled carbon dioxide without competing with agricultural food production.', 0, 600, 10, 'medium', 'Describe the advantages of microalgae for biofuels, emphasizing high lipid production on non-arable land without competing for freshwater or food crops.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-029', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Early Warning Vibration Sensors on Large Dams', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Large hydroelectric and reservoir dams retain billions of cubic meters of water, making structural dam integrity a critical public safety imperative. While concrete dams are engineered for immense strength, subterranean seismic tremors, foundation settling, and prolonged hydrostatic water pressure can induce microscopic internal fissures. To continuously evaluate dam health, structural engineers install dense networks of triaxial accelerometers and fiber-optic strain sensors across dam crests, internal inspection galleries, and abutments. These sensitive vibration instruments monitor the dam''s natural resonant vibration frequencies caused by ambient wind, water turbulence, and micro-earthquakes. If an internal crack develops or the foundation bedrock shifts, the structural stiffness of the concrete barrier decreases, causing a measurable drop in its natural resonant frequency. Telemetry systems transmit these vibrational metrics instantaneously to central engineering stations. By detecting subtle shifts in structural vibration signatures, dam operators receive early automated warnings of structural distress, allowing timely maintenance interventions before visible cracks emerge on concrete surfaces.', NULL, NULL, NULL, 'Installing networks of sensitive vibration sensors across large dams allows engineers to detect internal structural damage early by tracking subtle changes in the barrier''s natural resonant frequencies.', 0, 600, 10, 'medium', 'Highlight how accelerometer arrays monitor shifts in a dam natural vibration frequencies, providing early detection of internal cracks before physical failure occurs.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-030', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Using Living Tree Roots to Stabilize Hillside Slopes', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Mountain roads and steep river valleys are frequently plagued by shallow landslides and soil slumping, especially following prolonged monsoon downpours or seismic disturbances. Building conventional concrete retaining walls and steel rockfall fences is financially prohibitive across extensive highway networks and disrupts local ecology. Soil bioengineering offers an effective, environmentally harmonious alternative by using living plant materials to stabilize unstable slopes. Deep-rooted native trees, shrubs, and woody cuttings are planted in terraced trenches or woven into wooden brush mattresses along vulnerable slopes. As the plants mature, their thick taproots penetrate deep into stable subsoil layers, acting as natural soil anchors that bind fractured ground together. Concurrently, dense networks of fine lateral roots interweave with topsoil particles, forming a living composite reinforced matrix that resists shear failure. Furthermore, the active root systems draw large volumes of water from the soil through transpiration, reducing internal pore water pressure and preventing slope saturation. Over time, decaying roots add organic material to the subsoil, creating porous soil channels that further improve natural drainage and long-term slope stability.', NULL, NULL, NULL, 'Soil bioengineering stabilizes vulnerable hillside slopes naturally by planting deep-rooted native vegetation that anchors soil layers, forms reinforcing root networks, and extracts excess groundwater through transpiration.', 0, 600, 10, 'medium', 'Explain how tree roots act as physical anchors and moisture pumps to stabilize steep slopes naturally without expensive concrete walls.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-031', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Underwater Robotic Gliders for Marine Research', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Surveying the physical and biological dynamics of open oceans has historically been constrained by the high operational costs of crewed oceanographic research ships. Autonomous underwater gliders have revolutionized ocean data collection by providing persistent, low-cost observations across vast marine provinces. Unlike motorized underwater vehicles that consume large amounts of battery power for propeller propulsion, underwater gliders propel themselves forward by cyclically altering their buoyancy. An internal hydraulic pump shifts a small volume of oil into an external rubber bladder, causing the glider to expand slightly and rise through the water column. When the oil is pumped back inside, the glider sinks. Small fixed wings convert this vertical up-and-down motion into steady horizontal forward gliding at very low energy expense. Carrying sensors that measure temperature, salinity, dissolved oxygen, and chlorophyll, gliders travel thousands of kilometers over several months, surfacing periodically to transmit accumulated ocean data to scientists via satellite communications. Modern glider fleets operate autonomously in coordinated groups, providing synoptic three-dimensional snapshots of ocean currents, storm tracks, and marine ecosystems.', NULL, NULL, NULL, 'Autonomous underwater gliders traverse vast ocean distances for months by converting buoyancy adjustments into horizontal forward motion, collecting extensive marine data while consuming minimal battery power.', 0, 600, 10, 'medium', 'Detail how underwater gliders propel themselves using internal buoyancy changes rather than propellers, enabling long-duration ocean data collection at low energy expense.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-032', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Manufacturing Low-Carbon Cement from Industrial Ash', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Standard Portland cement production is one of the world''s most carbon-intensive manufacturing processes, accounting for substantial global greenhouse gas emissions through high-temperature limestone calcination. To decarbonize construction materials, civil engineers are producing low-carbon geopolymer cements that replace traditional Portland clinker with industrial byproducts, predominantly coal fly ash and blast furnace slag. Fly ash is rich in reactive aluminosilicate minerals. When mixed with an alkaline activator solution, such as sodium hydroxide and liquid silicate, a chemical geopolymerization reaction occurs at ambient or moderate temperatures. The mineral precursors dissolve and reassemble into a three-dimensional inorganic polymeric matrix that cures into dense, rock-like concrete. Geopolymer concretes exhibit exceptional compressive strength, superior resistance to acid corrosion, and high thermal stability compared to conventional cement. By eliminating limestone quarrying and high-temperature fossil-fired kilns, geopolymer manufacturing dramatically lowers embodied carbon emissions while repurposing millions of tons of industrial solid waste. Rigorous material testing confirms that geopolymer concrete withstands harsh freeze-thaw cycles and chemical exposure better than conventional Portland mixtures.', NULL, NULL, NULL, 'Low-carbon geopolymer cements substitute industrial fly ash for limestone clinker, using alkaline activation to produce strong, corrosion-resistant concrete while drastically cutting manufacturing carbon emissions.', 0, 600, 10, 'medium', 'Explain how activating industrial fly ash with alkaline solutions creates durable concrete without the high carbon footprint of limestone calcination.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-033', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Wildflower Corridors for Farmland Pollinators', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'The expansion of modern intensive agriculture and large monoculture crop fields has led to severe habitat fragmentation, depriving wild bees, hoverflies, and butterflies of the nesting sites and diverse floral resources necessary for survival. Because insect pollination is essential for high yields in fruit, vegetable, and oilseed crops, agricultural ecologists are establishing linear wildflower corridors across agricultural landscapes. Farmers sow multi-species mixes of native flowering annuals and perennials along field margins, ditch banks, and underutilized fence lines. These flowering strips provide a continuous sequence of pollen and nectar from early spring through late autumn, bridging seasonal forage gaps when main crops are not in bloom. Furthermore, permanent uncultivated strips offer undisturbed nesting burrows for solitary ground-nesting bees. By linking isolated patches of natural woodland and hedgerows, pollinator corridors facilitate genetic exchange among insect populations and boost natural pollination services throughout surrounding crop fields. Monitoring surveys confirm that fields flanked by mature wildflower strips experience significantly higher insect biodiversity and increased crop seed set.', NULL, NULL, NULL, 'Establishing native wildflower corridors along agricultural field boundaries provides continuous pollen, nectar, and nesting habitat, supporting healthy pollinator populations that enhance crop yields.', 0, 600, 10, 'medium', 'Summarize how planting native wildflower corridors along field borders sustains pollinator biodiversity and improves natural crop pollination services across farmlands.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-034', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Porous Mineral Catalysts in Chemical Manufacturing', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Modern chemical refining and manufacturing rely heavily on solid mineral catalysts to accelerate chemical reactions while minimizing energy consumption and unwanted byproducts. Synthetic zeolites, which are crystalline aluminosilicate minerals engineered with precise microscopic pores, serve as premier industrial catalysts. The crystal lattice of a zeolite contains an orderly network of uniform microscopic channels and cavities whose dimensions precisely match the size of individual organic molecules. Because of this uniform pore structure, zeolites function as molecular sieves, allowing only molecules of specific geometric shapes and sizes to enter the internal cavities where catalytic acid sites reside. Molecules that are too bulky to fit through the channel openings cannot access the active sites and remain unreacted. This molecular shape selectivity enables chemical plants to produce desired chemical products, such as cleaner transportation fuels and pharmaceutical intermediates, with exceptional chemical purity and minimal industrial chemical waste. Developing new synthetic zeolites with customized crystal architectures remains a central focus of industrial chemistry seeking cleaner, energy-efficient manufacturing.', NULL, NULL, NULL, 'Synthetic porous mineral catalysts use microscopic channels of uniform molecular dimensions to accelerate chemical reactions selectively, allowing only specific molecules to react and minimizing unwanted byproducts.', 0, 600, 10, 'medium', 'Describe how uniform microscopic pores in synthetic mineral catalysts act as molecular sieves, ensuring selective chemical reactions and reducing industrial waste.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-035', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Reflective Rooftop Coatings That Cool Without Energy', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Cooling indoor environments during hot summer months consumes vast amounts of electrical power through conventional air conditioning systems, straining municipal electrical grids and releasing heat into city streets. Passive daytime radiative cooling offers an innovative approach that cools architectural surfaces below ambient outdoor air temperatures without consuming electricity. Materials scientists formulate specialized reflective rooftop coatings incorporating dielectric nanoparticles and deliberately structured polymers. These coatings possess two critical optical properties: they reflect nearly all incoming solar radiation across ultraviolet and visible wavelengths, and they emit thermal energy strongly within the mid-infrared atmospheric transparency window. Because Earth''s atmosphere is transparent to infrared wavelengths between eight and thirteen micrometers, heat radiated at these specific wavelengths passes unobstructed through the atmosphere and radiates directly into outer space. By shedding more thermal energy into space than they absorb from sunlight, these coated rooftops stay significantly cooler than surrounding air, lowering building cooling demands. Extensive architectural trials indicate that applying these advanced radiative coatings to commercial rooftops substantially lowers building electricity consumption during peak summer periods.', NULL, NULL, NULL, 'Passive radiative roof coatings cool buildings without electricity by reflecting incoming solar sunlight while radiating thermal infrared heat directly into outer space through the atmospheric transparency window.', 0, 600, 10, 'medium', 'Explain how passive cooling coatings reflect solar radiation and radiate heat directly into space through the mid-infrared atmospheric window without power.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-036', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Deep Lakes with Permanently Separated Water Layers', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Most freshwater temperate lakes experience seasonal thermal overturning, in which changing surface temperatures and wind mixing circulate water completely from surface to bottom twice a year, replenishing deep dissolved oxygen reserves. However, certain deep, sheltered lakes exhibit meromictic conditions, where water layers remain permanently unmixed for decades or centuries. In these stratified water bodies, dissolved minerals, geothermal saline springs, or biological decomposition produce a dense, salty bottom water layer called the monimolimnion. Above it rests a lighter, freshwater surface layer. Because the density difference between these two layers is exceptionally large, seasonal wind-driven turbulence cannot overcome the density barrier. Consequently, the deep bottom water remains completely isolated from the atmosphere, becoming entirely devoid of dissolved oxygen. This permanent anoxia creates unique scientific archives, as organic debris, volcanic ash, and seasonal pollen settle undisturbed onto the lake bed without being scavenged by bottom-dwelling animals, preserving exceptionally detailed paleoenvironmental records. Examining undisturbed chemical varves from these unique lake beds allows paleoclimatologists to reconstruct annual temperature and precipitation shifts with remarkable fidelity.', NULL, NULL, NULL, 'In permanently stratified deep lakes, dense mineral-rich bottom water remains isolated from wind mixing, creating oxygen-free depths that preserve undisturbed historical environmental records in seafloor sediments.', 0, 600, 10, 'medium', 'Summarize how extreme density differences prevent lake water layers from mixing, creating anoxic bottom sediments that preserve pristine paleoenvironmental records.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-037', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Recyclable Composite Materials for Wind Turbines', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Wind energy is an indispensable pillar of the global transition to renewable electricity, but disposing of decommissioned wind turbine blades presents a significant ecological dilemma. Most existing turbine blades are manufactured from thermoset epoxy resins reinforced with fiberglass or carbon fibers. Thermoset resins form irreversible chemical cross-links during curing, meaning they cannot be melted, remolded, or economically recycled, leading thousands of retired blades to end up in landfills. To solve this disposal bottleneck, materials engineers are developing fully recyclable turbine blades utilizing advanced thermoplastic liquid resin systems. Unlike thermoset polymers, thermoplastic resins can be dissolved and depolymerized chemically at the end of a blade''s service life. When immersed in a mild chemical solvent at moderate temperatures, the thermoplastic resin dissolves cleanly, allowing intact, undamaged fiberglass and carbon fibers to be reclaimed. The recovered fibers and resin can then be reused to manufacture new composite structures, closing the material loop in clean energy infrastructure.', NULL, NULL, NULL, 'Developing recyclable thermoplastic composite materials for wind turbine blades allows polymers to be dissolved and fibers to be reclaimed at the end of service life, preventing massive landfill blade waste.', 0, 600, 10, 'medium', 'Contrast thermoset resin blades with recyclable thermoplastic composites, explaining how the latter can be chemically dissolved to recover fibers for reuse.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-038', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Vegetated Stream Buffers for Farmland Runoff', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Surface runoff from agricultural crop fields frequently carries elevated concentrations of synthetic fertilizers, soil sediment, and agricultural pesticide residues into adjacent freshwater streams and rivers. This nutrient pollution leads to severe eutrophication, toxic algal blooms, and fish kills. Establishing vegetated riparian buffers along agricultural watercourses provides a simple, highly effective biological filter. Riparian buffer zones are strips of permanent vegetation consisting of native grasses, deep-rooted shrubs, and streamside trees planted between tilled fields and the water''s edge. As agricultural runoff sheets across the buffer strip, dense surface vegetation slows water velocity, causing suspended sediment particles to drop out before reaching the stream channel. Beneath the soil surface, tree and shrub roots absorb dissolved nitrates and phosphorus, incorporating these agricultural nutrients into plant biomass. Furthermore, riparian tree canopies shade the water, keeping stream temperatures cool and preserving dissolved oxygen levels for trout and other sensitive aquatic organisms. Over time, mature streamside tree roots stabilize crumbling banks, preventing channel widening and preserving deep swimming pools essential for migratory fish.', NULL, NULL, NULL, 'Vegetated riparian buffer strips planted along streams slow agricultural runoff, trap suspended sediment particles, and absorb excess dissolved fertilizer nutrients before they can contaminate freshwater ecosystems.', 0, 600, 10, 'medium', 'Explain how vegetated stream buffers trap sediment, absorb dissolved agricultural nutrients, and shade watercourses to protect aquatic habitats.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-039', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Automated Acoustic Monitoring for Livestock Welfare', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Ensuring animal health and welfare in commercial livestock farming requires continuous monitoring, but human visual inspections in large barns are labor-intensive and may miss early signs of illness until symptoms become severe. Veterinary scientists and engineers have developed automated acoustic bio-monitoring systems that continuously assess animal welfare through sound analysis. Sensitive directional microphones installed in livestock housing record the vocalizations, coughing, and breathing patterns of animals round the clock. Machine-learning algorithms process the recorded audio streams, filtering out background mechanical noise from ventilation fans and feed augers to detect distinct acoustic patterns associated with respiratory distress, pain, or social stress. For instance, detecting an increase in pig or cattle cough frequency allows veterinarians to diagnose contagious respiratory infections several days before clinical signs become visibly apparent. Early identification enables targeted treatment of individual sick animals rather than administering mass preventative antibiotics, improving animal welfare while curbing the development of antimicrobial resistance.', NULL, NULL, NULL, 'Automated bioacoustic monitoring in livestock facilities identifies respiratory distress and social stress early through continuous sound analysis, enabling prompt veterinary care and reducing widespread antibiotic use.', 0, 600, 10, 'medium', 'Summarize how automated acoustic analysis of animal vocalizations and coughing detects livestock illnesses early, improving welfare and reducing mass antibiotic administration.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-040', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Restoring Degraded River Channels with Willow Cuttings', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Centuries of agricultural land clearing and channel straightening have severely destabilized natural riverbanks, causing chronic riverbank erosion, siltation of aquatic habitats, and loss of streamside biodiversity. Rather than armor river channels with rigid concrete slabs or heavy stone riprap, river restoration practitioners are increasingly employing bioengineering techniques using live willow cuttings. Freshly harvested dormant willow branches are laid horizontally in layered soil trenches or woven into flexible wooden fascines along eroded riverbanks. Willow possesses an extraordinary biological capacity to sprout adventitious roots and leafy shoots rapidly when buried in moist soils. Within weeks of installation, the dense root system penetrates the bank sediment, binding loose silt and gravel into a cohesive, erosion-resistant mass. Concurrently, the flexible willow branches bend during flood flows, dissipating hydraulic energy and trapping sediment to rebuild natural river margins. Unlike sterile stone riprap, living willow revetments establish vibrant riparian shade and provide essential insect habitat for river ecosystems.', NULL, NULL, NULL, 'Restoring degraded riverbanks with live willow cuttings stabilizes bank sediments through rapid root growth and flexible branches that dissipate flood energy while enhancing streamside ecological habitat.', 0, 600, 10, 'medium', 'Describe how planting live willow branches stabilizes riverbank soil via rapid root growth, dissipates flood energy, and restores natural streamside habitat.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-041', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Bacterial Mineralization for Repairing Marine Concrete', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Reinforced concrete structures deployed in marine environments, such as harbor seawalls, shipping piers, and offshore wind foundations, are continuously attacked by saltwater. Seawater penetrates hairline surface cracks, exposing internal steel reinforcing bars to chloride-induced corrosion, which causes internal expansion, concrete spalling, and catastrophic structural degradation. To extend the service life of coastal infrastructure, materials scientists are developing self-healing concrete utilizing bacterial mineralization. Harmless, alkali-resistant bacterial spores belonging to the genus Bacillus are mixed directly into the concrete together with encapsulated organic nutrients like calcium lactate. The bacteria remain dormant inside dry concrete for decades. However, when saltwater penetrates an emerging structural crack, moisture and oxygen awaken the dormant spores. The metabolically active bacteria consume the calcium lactate, producing carbonate ions that react with calcium to precipitate insoluble limestone crystals inside the crack. Over several weeks, the precipitated mineral crystals seal the crack completely, preventing saltwater from reaching the internal steel reinforcement.', NULL, NULL, NULL, 'Self-healing concrete incorporates dormant bacterial spores that activate upon exposure to saltwater moisture, precipitating limestone crystals that seal emerging structural cracks and protect steel reinforcement from corrosion.', 0, 600, 10, 'medium', 'Explain how dormant bacteria inside concrete awaken when water penetrates cracks, producing limestone crystals that seal the damage and protect internal steel from corrosion.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-042', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Harvesting Electrical Energy from Highway Traffic Pressure', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Heavy automotive traffic on national highways and motorway toll plazas exerts enormous mechanical pressure onto roadway pavements, energy that is traditionally lost as heat and pavement wear. Piezoelectric energy harvesting offers an innovative technology to capture this kinetic energy and convert it directly into usable electricity. Piezoelectric ceramic crystals, such as lead zirconate titanate, generate an internal electric charge whenever they experience external mechanical strain or compression. Civil engineers encapsulate arrays of these robust piezoelectric transducers inside waterproof, road-grade steel cassettes embedded beneath the upper asphalt layer of heavily trafficked road lanes. Each time a heavy truck or car drives over the cassette, the compressive weight deforms the piezoelectric elements, generating pulses of electrical voltage. Power conditioning electronics rectify these electrical pulses and store the energy in roadside battery banks or feed it directly into roadway infrastructure. The generated electricity powers LED highway lighting, electronic warning signs, and traffic monitoring cameras entirely off-grid.', NULL, NULL, NULL, 'Piezoelectric transducers embedded beneath highway asphalt convert the compressive pressure of moving vehicles directly into electricity, providing renewable off-grid power for roadside lighting and safety systems.', 0, 600, 10, 'medium', 'Highlight how piezoelectric ceramic elements embedded under roadway asphalt generate electrical voltage from vehicle compression, powering local highway infrastructure off-grid.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-043', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Airborne Multispectral Cameras for Forest Health Monitoring', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Monitoring the physiological health of extensive forest ecosystems is essential for detecting early signs of insect infestations, drought stress, and fungal pathogens before massive tree die-offs occur. Ground surveys are slow and restricted by difficult terrain, while conventional satellite photography lacks sufficient spatial resolution to assess individual tree crowns. Forest researchers are increasingly employing aerial multispectral imaging cameras mounted on survey aircraft and drones. Healthy tree leaves contain high concentrations of chlorophyll, which absorbs blue and red visible light for photosynthesis while strongly reflecting near-infrared radiation from their cellular leaf structures. When trees experience water stress or pathogen attacks, cellular damage causes near-infrared reflectance to drop sharply even before foliage exhibits visible yellowing. By calculating normalized difference vegetation indices across calibrated spectral bands, multispectral imaging systems map subtle physiological decline across thousands of hectares of forest. Forestry managers can pinpoint stressed forest stands and deploy targeted interventions before widespread tree mortality spreads.', NULL, NULL, NULL, 'Airborne multispectral imaging detects early forest drought stress and disease by measuring reductions in near-infrared leaf reflectance before visible canopy discoloration becomes apparent to human observers.', 0, 600, 10, 'medium', 'Describe how multispectral cameras detect subtle shifts in near-infrared reflectance caused by cellular leaf stress, providing early warning of forest decline across vast landscapes.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-044', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Nutrient Cycling by Microorganisms in Coastal Mudflats', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Intertidal coastal mudflats and estuarine salt marshes are often perceived as barren, muddy wastelands, but they are among the most biochemically productive ecosystems on Earth. These sediment basins serve as critical natural biogeochemical filters that process vast quantities of organic matter and agricultural nutrients carried by rivers before water reaches the open sea. Because fine estuarine muds are densely packed and waterlogged, atmospheric oxygen penetrates only the uppermost few millimeters of the sediment surface. Beneath this thin oxic boundary, diverse communities of specialized anaerobic microorganisms mediate essential nutrient cycling through distinct redox zones. Denitrifying bacteria consume agricultural nitrate runoff and convert it into harmless nitrogen gas, preventing dangerous coastal algal blooms. Deeper in the sediment, sulfate-reducing bacteria decompose organic detritus, recycling sulfur and locking heavy metals into stable, insoluble sulfide minerals. These microbial communities purify coastal waters, maintain marine food webs, and prevent coastal ecological degradation. Preserving intact intertidal flats is therefore essential for coastal water purification and protecting vulnerable marine fisheries from excess land-based pollution.', NULL, NULL, NULL, 'Coastal mudflats function as vital biogeochemical filters where diverse microbial communities decompose organic matter, convert agricultural nitrates into harmless nitrogen gas, and trap toxic metals in sediments.', 0, 600, 10, 'medium', 'Summarize how specialized microbial layers in intertidal mudflats break down organic debris and convert excess agricultural nitrates into inert nitrogen gas naturally.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-045', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Permeable Concrete Pavement for Stormwater Infiltration', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'In modern urban environments, extensive impervious surfaces like asphalt roads, concrete sidewalks, and commercial roofs prevent rainwater from infiltrating naturally into the ground. During intense precipitation events, massive volumes of surface runoff overwhelm municipal stormwater sewers, causing destructive flash flooding and carrying urban contaminants into rivers. Permeable concrete pavement offers an effective green infrastructure solution to manage urban hydrology. Unlike traditional concrete, which is formulated with fine sand to create a solid, impermeable mass, permeable concrete deliberately omits fine aggregates, bonding coarse gravel stones with a thin cement paste. This unique composition creates an interconnected network of large open voids that allows rainwater to drain directly through the pavement surface at extraordinary infiltration rates. Below the pavement, an open-graded crushed stone reservoir temporarily detains the infiltrated water, allowing it to percolate slowly into the underlying soil. Permeable pavements eliminate surface puddles, recharge local groundwater reserves, and filter hydrocarbons naturally as water passes through stone layers.', NULL, NULL, NULL, 'Permeable concrete pavement eliminates urban surface runoff and flash flooding by using aggregate voids that allow rainwater to drain directly into underground stone reservoirs and replenish groundwater.', 0, 600, 10, 'medium', 'Explain how omitting fine sand in permeable concrete creates internal voids that drain rainwater directly into subsurface stone reservoirs, preventing urban runoff.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-046', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Mapping Subsurface Water Tables with Electrical Resistivity', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Locating accessible groundwater reserves and mapping the boundaries of subterranean aquifers in arid regions has traditionally required drilling exploratory boreholes, which is expensive, labor-intensive, and provides data from only single geographic points. Surface electrical resistivity tomography offers a non-invasive geophysical surveying method that images subsurface hydrogeology over extensive areas. Geoscientists deploy a linear array of steel electrode stakes driven into the ground along a survey line. An automated console injects controlled direct electric currents into the ground through pairs of electrodes while measuring resulting electrical potential differences across adjacent electrode pairs. Because dry porous rock, dense clays, and water-saturated gravels have dramatically different electrical resistivities, specialized inversion algorithms process the recorded electrical voltages to generate a detailed two-dimensional cross-section of subsurface resistivity. Hydrogeologists can clearly delineate freshwater aquifers, identify impermeable clay confining layers, and detect saline groundwater intrusion without drilling exploratory wells, guiding sustainable groundwater extraction. Combining electrical resistivity surveys with hydrological monitoring wells allows water authorities to manage groundwater extraction sustainably and avoid aquifer depletion.', NULL, NULL, NULL, 'Surface electrical resistivity tomography maps underground aquifers non-invasively by injecting electrical currents into the ground and measuring voltage differences that reveal the moisture and composition of geological layers.', 0, 600, 10, 'medium', 'Describe how electrical resistivity tomography measures subsurface voltage differences through electrode arrays to map groundwater aquifers without exploratory drilling.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-047', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Water-Repellent Coatings Inspired by Lotus Leaves', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'In nature, the leaves of the sacred lotus plant remain impeccably clean and dry even in muddy wetland environments, a phenomenon known as the lotus effect. Materials scientists have analyzed this biological mechanism to develop synthetic superhydrophobic coatings for industrial and architectural applications. Electron microscope analysis reveals that the lotus leaf surface possesses a dual-scale microscopic roughness, consisting of microscopic epidermal mounds covered with even smaller waxy hydrophobic crystals. When water droplets strike this textured surface, they cannot wet the microscopic valleys; instead, pockets of air become trapped beneath the droplet, causing water to sit on top of the microscopic peaks as a nearly spherical bead. When the surface tilts slightly, the water droplets roll off effortlessly, picking up dust, soot, and chemical contaminants along the way. Engineered coatings mimicking this hierarchical texturing are applied to solar photovoltaic panels, architectural glass, and high-voltage electrical insulators, enabling surfaces to self-clean automatically during rainstorms.', NULL, NULL, NULL, 'Biomimetic superhydrophobic coatings mimic the dual-scale surface roughness of lotus leaves, causing water to form spherical droplets that roll off effortlessly and wash away accumulated surface contaminants.', 0, 600, 10, 'medium', 'Explain how microscopic surface roughness creates superhydrophobicity, causing water droplets to roll off surfaces and clean away dirt automatically.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-048', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Replenishing Underground Aquifers with Seasonal Runoff', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Decades of intensive agricultural pumping have severely depleted subterranean aquifers across arid and semi-arid valleys worldwide, causing ground subsidence, drying agricultural wells, and degrading groundwater quality. Managed aquifer recharge has emerged as an essential water security technique that stores surplus surface water underground for future recovery. During wet winter months or high-flow river runoff periods, excess river discharge that would otherwise flow unused into the sea is diverted into engineered infiltration basins or dedicated recharge wells. In shallow infiltration basins, the surface water percolates through native permeable soils, which naturally filter out suspended sediments, pathogenic bacteria, and trace chemicals through biological and physical soil interactions. The purified water gradually enters the underlying aquifer, raising regional water table levels. Storing water in subterranean aquifers avoids the immense evaporative losses and ecological destruction associated with building massive surface dams, providing a resilient underground water reserve for drought years. Establishing extensive recharge programs requires ongoing water quality testing to verify that diverted runoff remains free of industrial contaminants before entering drinking aquifers.', NULL, NULL, NULL, 'Managed aquifer recharge restores depleted subterranean groundwater reserves by diverting surplus seasonal river runoff into infiltration basins that filter the water naturally through soil before it reaches the aquifer.', 0, 600, 10, 'medium', 'Highlight how diverting surplus seasonal runoff into soil infiltration basins replenishes underground aquifers naturally without the evaporative losses of surface reservoirs.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-049', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Protecting Underground Pipelines from Soil Corrosion', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'Extensive subterranean steel pipelines transport municipal drinking water, natural gas, and liquid fuels across thousands of kilometers of varying soil conditions. Because moist soils contain dissolved mineral salts and moisture, steel pipes experience continuous electrochemical corrosion, where iron atoms lose electrons and oxidize into brittle rust, threatening hazardous pipeline ruptures. While protective epoxy coatings provide an initial moisture barrier, microscopic pinholes and installation scratches inevitably expose bare metal to the soil. To prevent corrosion at these coating defects, pipeline operators employ cathodic protection systems. In an impressed current cathodic protection setup, an external direct-current power source is connected between the pipeline and an array of sacrificial anode materials buried nearby in conductive ground. The power supply forces electrical electrons into the pipeline, making the entire steel pipe the cathode in an electrochemical cell. By maintaining a continuous negative electrical potential along the pipe surface, oxidation reactions are completely suppressed, ensuring decades of safe, leak-free pipeline operation.', NULL, NULL, NULL, 'Cathodic protection prevents electrochemical corrosion in underground steel pipelines by supplying a continuous electrical current that makes the metal a cathode, suppressing oxidation and preventing hazardous leaks.', 0, 600, 10, 'medium', 'Explain how cathodic protection supplies an electric current to make subterranean steel pipes the cathode, suppressing metal oxidation and protecting against corrosion leaks.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-swt-050', 'pte-2026-01', 'PTE', 'writing', 'summarize-written-text', 'Summarize Written Text', 'Acoustic Barriers Along High-Speed Railway Corridors', 'Read the passage below and summarise it in ONE single sentence of between 5 and 75 words.', 'High-speed passenger trains traveling at speeds exceeding two hundred kilometers per hour produce substantial acoustic disturbances in nearby residential communities. Railway noise consists of a complex combination of mechanical wheel-rail rolling friction, electric traction motors, and aerodynamic turbulence generated by pantographs and train noses. To protect adjacent neighborhoods from excessive noise exposure, civil acoustic engineers install specialized sound barriers along high-speed railway corridors. Modern acoustic barriers are constructed using porous sound-absorptive panels, typically manufactured from recycled wood-concrete composites or porous aluminum foams, mounted on sturdy steel posts engineered to withstand powerful aerodynamic pressure waves generated as trains pass. Unlike rigid, reflective walls that bounce sound waves back across opposite neighborhoods, porous absorptive panels trap acoustic energy within their microscopic internal voids, converting sound vibrations into harmless thermal dissipation. Curved barrier tops and acoustic diffusers further bend and scatter sound waves away from nearby homes, significantly reducing residential noise impact. Installing these advanced absorptive acoustic barriers preserves quiet residential environments while allowing high-speed rail networks to operate at maximum commercial speeds.', NULL, NULL, NULL, 'Porous acoustic barriers installed along high-speed railway corridors absorb sound vibrations within internal microscopic voids, effectively dampening train rolling and aerodynamic noise to protect adjacent residential communities.', 0, 600, 10, 'medium', 'Summarize how porous sound-absorptive railway barriers dissipate acoustic energy from train wheels and aerodynamic turbulence, protecting neighboring communities from noise pollution.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarize Written Text'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-001', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Right to Disconnect Legislation', 'Governments should introduce legislation giving employees the legal right to ignore work emails and phone calls outside contracted working hours.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'In an era dominated by smartphones and remote connectivity, the boundary between professional obligations and personal life has become increasingly blurred. I firmly agree that governments should enact legislation granting workers the legal right to disconnect from work-related communications outside their scheduled hours.

The primary justification for this policy is the preservation of mental health and well-being. When employees are expected to respond to urgent messages during evenings and weekends, they experience continuous cognitive stress and sleep disruption. Over time, this constant availability leads to occupational burnout and diminished job performance. For example, several European nations that introduced statutory disconnection rights observed significant reductions in stress-related sick leave and improved worker retention rates. Establishing clear legal limits ensures that personal downtime is respected by employers across all industries.

Critics often argue that strict disconnection laws could impair commercial competitiveness, particularly for international firms operating across different time zones. They contend that emergency client demands require immediate flexibility. However, operational urgencies can easily be accommodated through structured on-call remuneration systems rather than informal, unpaid round-the-clock expectations. When organizations organize staffing effectively, standard operations rarely depend on encroaching upon off-duty hours.

In conclusion, legally protecting an employee''s right to disconnect is vital for safeguarding public health in modern knowledge economies. Far from harming productivity, well-rested professionals are demonstrably more focused, creative, and efficient during their working day.', 0, 1200, 15, 'medium', 'State a clear position on right-to-disconnect laws. Provide reasoning on mental health and burnout, address counter-arguments regarding global business responsiveness, and conclude with overall benefits.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-002', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Algorithmic News Selection', 'Online news platforms should be prohibited from using automated algorithms to personalize the news articles shown to individual users.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Digital platforms increasingly rely on complex recommendation algorithms to curate news feeds based on users'' browsing histories and behavioral patterns. I agree with the view that algorithmic personalization of journalistic content should be restricted or prohibited by regulatory bodies.

The main argument against automated personalization is the emergence of ideological filter bubbles. When software repeatedly serves content that aligns with a user''s preexisting biases, it distorts their perception of public reality and narrows their worldview. Over time, citizens lose exposure to opposing perspectives, which fuels political polarization and undermines democratic discourse. In practical experience, social media feeds tend to amplify sensationalist viewpoints, leading communities to divide into hostile ideological factions incapable of reaching consensus on critical civic issues.

On the other hand, proponents of algorithmic curation maintain that the sheer volume of global news makes personal filtering necessary for consumer convenience. They argue that readers benefit from receiving updates tailored to their professional or geographic interests. While thematic categorization is undeniably helpful, it can easily be achieved through transparent user-selected topics rather than opaque predictive algorithms designed to maximize engagement and advertising revenue.

To conclude, personalizing news feeds through opaque algorithms poses a profound risk to civic cohesion and informed citizenship. Regulating news distribution to guarantee diverse, balanced exposure is essential for maintaining a healthy and well-informed public sphere.', 0, 1200, 15, 'medium', 'Take a stance on algorithmic personalization of news. Discuss echo chambers and political polarization in body 1, address user convenience in body 2, and summarize in conclusion.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-003', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Citizen Juries in Urban Planning', 'Major urban infrastructure projects should be approved by randomly selected citizen juries rather than elected municipal politicians alone.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Urban infrastructure projects such as highway extensions, transit networks, and commercial developments shape communities for generations. I agree that incorporating randomly selected citizen juries into the formal approval process represents a substantial improvement over leaving these monumental decisions solely to elected politicians.

The foremost advantage of citizen juries is their independence from political pressure and commercial lobbying. Elected municipal representatives frequently face conflicts of interest, often prioritizing short-term electoral cycles or catering to wealthy real estate developers who fund political campaigns. In contrast, randomly chosen citizens, supported by independent technical experts, can deliberate impartially on the genuine long-term merits of a proposal. For example, municipal assemblies in several democratic nations have successfully utilized citizen panels to resolve contentious zoning disputes, resulting in public transit investments that truly reflect neighbourhood needs.

Nevertheless, detractors argue that ordinary citizens lack the specialized technical expertise in engineering and municipal finance required to evaluate multi-million-dollar developments. They suggest that laypersons might reject essential but disruptive infrastructure. However, the deliberative jury model addresses this concern by providing jurors with balanced expert testimony, cross-examination opportunities, and sufficient time to evaluate complex trade-offs before voting.

In summary, while elected officials retain an important administrative role, empowering citizen juries democratizes urban development and prevents regulatory capture. Combining popular deliberation with technical evidence produces urban infrastructure that genuinely serves community welfare.', 0, 1200, 15, 'medium', 'Clearly argue for or against citizen juries in urban infrastructure planning. Weigh democratic representation against technical expertise and conclude with a synthesized viewpoint.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-004', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Universal Basic Income', 'Governments should provide a universal basic income to all adult citizens regardless of their employment status or financial wealth.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'As automation and technological advancements reshape the global labor market, the concept of an unconditional universal basic income has gained widespread prominence. I support the implementation of a basic income guarantee, as it provides an indispensable financial safety net for modern societies.

The primary benefit of a universal basic income is the eradication of extreme poverty and the mitigation of technological unemployment. Rapid adoption of artificial intelligence and robotics threatens to displace millions of routine cognitive and manual jobs. An unconditional monthly stipend ensures that every citizen can afford basic necessities such as nutrition, housing, and healthcare, regardless of economic disruptions. Furthermore, evidence from regional pilot programs shows that basic income recipients frequently use their security to pursue higher education, care for dependent relatives, or launch entrepreneurial ventures, thereby generating positive social returns.

Conversely, critics argue that guaranteed unconditional income would discourage work effort and place an unsustainable fiscal burden on national budgets. They contend that many recipients would choose leisure over employment, reducing economic productivity. However, empirical findings from trial schemes in diverse countries indicate that employment rates remained largely stable, with most participants continuing to work or seeking better-matched careers. Funding such initiatives is achievable by consolidating bureaucratic welfare agencies and enacting progressive taxation on corporate profits and automated wealth.

In conclusion, universal basic income offers a forward-looking solution to structural economic instability. By eliminating poverty traps and empowering individual agency, it creates a resilient foundation for societies navigating technological transformation.', 0, 1200, 15, 'medium', 'Present a clear stance on Universal Basic Income. Discuss poverty alleviation and technological disruption in body 1, address work disincentives and fiscal costs in body 2, and conclude effectively.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-005', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Digital Nomad Visas and Housing', 'Cities experiencing housing shortages should restrict the issuance of digital nomad visas to protect local residents from rising rents.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'The rise of remote work has prompted numerous municipal authorities to introduce digital nomad visas to attract foreign professionals with high disposable incomes. However, I believe that cities confronting severe housing shortages should impose strict caps or restrictions on these schemes to protect local residents from rent hyperinflation.

The most pressing concern is that affluent remote workers earning salaries from wealthier foreign economies can afford disproportionately high rents, driving rapid gentrification. Landlords frequently convert long-term residential housing into lucrative short-term rentals, depleting the available rental stock for local inhabitants. As a consequence, domestic workers, nurses, and teachers earning local wages are displaced from central neighborhoods, exacerbating socioeconomic inequality. For instance, several popular coastal cities that welcomed large influxes of foreign remote workers experienced massive surges in residential rents within two years, triggering widespread housing crises among the indigenous population.

On the other hand, proponents argue that digital nomads stimulate the local economy by patronizing cafes, retail shops, and hospitality venues throughout the calendar year. While their consumer expenditure does support service industries, this financial benefit is often heavily concentrated among business owners, whereas the burden of inflated shelter costs falls squarely on ordinary tenants. An economic model that enriches commercial landlords while rendering homes unaffordable for essential local workers is ultimately unsustainable.

To conclude, while international mobility offers cultural and economic advantages, local housing security must remain the paramount priority. Municipalities must carefully regulate foreign remote worker quotas until adequate affordable housing supply is secured for their own citizens.', 0, 1200, 15, 'medium', 'Evaluate the impact of digital nomad visas on local housing markets. Contrast economic spending benefits with rental hyperinflation and tenant displacement, concluding with a balanced policy recommendation.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-006', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Ocean Exploration Funding', 'Governments should allocate more financial resources to exploring the Earth''s deep oceans than to exploring outer space.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'While space exploration captures public imagination, humanity''s understanding of our own planet remains strikingly incomplete. I strongly agree that governments should allocate greater funding to deep-sea exploration, as the terrestrial oceans hold immediate relevance for human survival and scientific advancement.

The fundamental reason to prioritize oceanographic research is its direct connection to global climate regulation and marine ecosystems. The deep sea absorbs vast quantities of atmospheric heat and carbon dioxide, driving global ocean currents and weather systems. Investigating abyssal environments provides essential empirical data for predicting sea-level rise and climatic shifts. Furthermore, marine organisms dwelling near hydrothermal vents produce novel biochemical compounds that hold tremendous promise for medicine, including new antibiotics and cancer therapies. Understanding these biological systems delivers practical, tangible benefits that directly improve terrestrial human life today.

Conversely, proponents of space missions argue that extraterrestrial exploration inspires technological innovation and prepares humanity for long-term survival beyond Earth. While astronomy and aerospace research certainly yield valuable engineering spin-offs, sending probes to distant planets requires exorbitant expenditure with minimal immediate return. Given pressing planetary crises such as oceanic biodiversity loss and resource depletion, spending billions on interstellar journeys while ignoring the vast majority of our unexplored seafloor represents an illogical allocation of public funds.

In conclusion, while space exploration has its merits, unraveling the mysteries of Earth''s oceans is far more urgent. Prioritizing marine exploration ensures that we protect the delicate life-support systems upon which our immediate future depends.', 0, 1200, 15, 'medium', 'Compare the merits of ocean exploration and space exploration. Emphasize climate relevance and medical discoveries in body 1, address space technology benefits in body 2, and summarize in conclusion.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-007', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Mandatory Ethics in Engineering', 'All undergraduate engineering and computer science students should be required to complete mandatory coursework in professional ethics.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'In recent decades, engineering and software innovations have achieved unprecedented influence over human society, from artificial intelligence to autonomous robotics. I firmly agree that universities should make comprehensive professional ethics education a mandatory requirement for all engineering and computer science undergraduates.

The primary argument for mandatory ethics instruction is that modern technological designs carry immense societal, environmental, and ethical consequences. Software engineers write algorithms that automate judicial sentencing, loan approvals, and facial surveillance, while civil engineers design structures that impact regional ecology. Without formal training in ethical deliberation, developers risk prioritizing technical efficiency or corporate profits over human safety and fairness. Teaching students how to identify algorithmic bias, data privacy violations, and environmental hazards prepares them to challenge irresponsible corporate decisions before harmful products are deployed.

Opponents often contend that university curricula are already densely packed with essential mathematical and scientific subjects. They argue that dedicating credit hours to humanities could dilute students'' technical competence. However, technical proficiency divorced from ethical responsibility produces dangerous outcomes, as demonstrated by recent algorithmic scandals and engineering failures. Ethics should not be viewed as an isolated academic distraction, but as an integral foundation of sound technical design that enhances professional credibility.

To conclude, technology is never morally neutral. Requiring future engineers and computer scientists to master ethical principles ensures that technological innovation remains aligned with human dignity and social progress.', 0, 1200, 15, 'medium', 'Defend mandatory ethics for engineering/tech students. Detail societal risks of unexamined technology in body 1, refute curriculum overcrowding in body 2, and conclude strongly.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-008', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Phasing Out Paper Receipts', 'Governments should prohibit retail stores from printing physical paper receipts by default and mandate digital receipts instead.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Every day, billions of paper receipts are printed globally, the vast majority of which are discarded within seconds of purchase. I strongly support the proposal to ban automatic paper receipts and require retailers to transition to digital transaction records by default.

The environmental benefit of eliminating paper receipts is substantial. Manufacturing thermal receipt paper consumes millions of trees and billions of liters of water annually. Crucially, most thermal paper is coated with chemical developers such as bisphenol A, which renders it non-recyclable and hazardous to landfill ecosystems. Phasing out automatic printing prevents unnecessary chemical waste and conserves natural forestry resources. From a consumer perspective, digital receipts sent via email or mobile banking applications are easier to organize, search, and preserve for warranty and tax purposes, reducing clutter and physical loss.

Nevertheless, skeptics raise valid concerns regarding consumer privacy and digital exclusion. They point out that collecting personal email addresses or phone numbers at checkout allows retailers to track shopping habits and send intrusive promotional advertisements. Furthermore, elderly or low-income shoppers who lack smartphones could be disadvantaged. However, these issues can be effectively resolved by offering paper receipts only upon explicit customer request and enacting strict privacy laws that prohibit commercial exploitation of transaction contact details.

In conclusion, mandating digital receipts by default is an overdue environmental reform. With sensible privacy safeguards, this policy substantially reduces deforestation and hazardous chemical waste without impeding consumer convenience.', 0, 1200, 15, 'medium', 'Argue for phasing out paper receipts. Discuss tree consumption and toxic chemical coatings in body 1, tackle privacy and digital access concerns in body 2, and provide a clear conclusion.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-009', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Technological Innovation Prizes', 'Public research funds should be awarded as cash prizes for achieving specific scientific breakthroughs rather than distributed through traditional institutional grants.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'The allocation of public scientific funding plays a decisive role in national technological progress. While traditional peer-reviewed grants have long dominated research policy, I believe that replacing them entirely with breakthrough cash prizes would be counterproductive, though innovation prizes serve as an excellent supplementary mechanism.

The primary merit of innovation prizes is their ability to stimulate creative competition and attract unconventional problem solvers. Traditional grant systems often favor established academic institutions and conservative, incremental projects that carry minimal risk of failure. By offering substantial financial awards for achieving concrete performance milestones, such as developing an affordable battery or rapid diagnostic test, governments encourage independent inventors, start-ups, and cross-disciplinary teams to pursue radical innovations. Prizes pay solely for verified success, ensuring that public funds are not expended on unfulfilled research promises.

However, an exclusive reliance on prize-based funding poses grave dangers for foundational scientific inquiry. Fundamental research in theoretical physics, molecular biology, and mathematics rarely has an immediate commercial or technical endpoint. Scientists working on fundamental discoveries require steady, predictable institutional funding to maintain laboratory equipment and employ staff over decades. If public support depended solely on winning contests, vital basic research that produces unexpected revolutionary technologies would be starved of necessary resources.

To conclude, while prize competitions inject vital dynamism and speed into solving specific technical challenges, they cannot replace institutional research grants. A balanced funding model combining steady foundational grants with targeted breakthrough prizes represents the most effective strategy for scientific advancement.', 0, 1200, 15, 'medium', 'Analyze breakthrough prizes versus traditional research grants. Praise competitive motivation in body 1, highlight the necessity of foundational science funding in body 2, and synthesize in conclusion.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-010', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Restricting Gambling Advertisements', 'Advertisements for sports betting and online gambling should be completely banned from television and digital media platforms.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'The rapid growth of online betting platforms has led to an explosion of gambling commercials during televised sporting events and on digital media. I firmly agree that all forms of gambling advertising should be completely banned to protect public health and vulnerable populations.

The foremost justification for a total advertising ban is the severe psychological and economic harm caused by compulsive gambling. Commercials deliberately portray betting as a glamorous, effortless pathway to excitement and wealth, normalizing addictive behavior among impressionable adolescents. Continuous exposure during family sporting events desensitizes young viewers, substantially increasing the likelihood of youth problem gambling. For individuals recovering from gambling addictions, pervasive digital advertisements serve as unavoidable relapse triggers, leading to severe debt, relationship breakdown, and mental distress. Just as governments banned tobacco marketing to curb smoking epidemics, similar restrictions are urgently warranted for gambling.

Conversely, the betting industry and sports broadcasting networks argue that commercial advertising is a lawful commercial enterprise that finances professional athletics. They maintain that individual adults should bear personal responsibility for their entertainment choices. While personal autonomy is important, advertising algorithms actively exploit cognitive vulnerabilities and impulsivity. Furthermore, athletic leagues can secure sustainable corporate sponsorship from ethical consumer brands without relying on industries that profit directly from social harm.

In conclusion, the devastating societal costs of problem gambling far outweigh the commercial profits of betting companies. A comprehensive ban on gambling advertising is essential to shield families and young people from predatory commercial practices.', 0, 1200, 15, 'medium', 'Take a decisive stand on banning gambling ads. Detail addiction, adolescent vulnerability, and parallels to tobacco in body 1, address personal responsibility and sports revenue in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-011', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Preserving Vernacular Architecture', 'Municipal governments should require new buildings in historic towns to follow traditional local architectural styles rather than modern designs.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'As globalization accelerates, uniform glass-and-steel architectural styles have proliferated across world cities, often eroding regional character. I agree that municipal authorities in historic towns should mandate that new constructions harmonize with traditional local architecture to safeguard cultural heritage.

The primary argument for enforcing traditional vernacular styles is the preservation of cultural identity and civic pride. Historic towns possess unique architectural traditions shaped by local materials, craftsmanship, and centuries of adaptation to regional climates. Erecting discordant modernist towers in historical town centers disrupts visual coherence, alienating local residents and destroying the historic ambiance that attracts cultural tourism. When municipal guidelines enforce traditional stonework, timber detailing, and proportional facades, new developments enrich the urban fabric rather than degrading it. For instance, several preserved European and Asian heritage towns have sustained thriving tourism economies specifically by maintaining strict architectural uniformity.

Critics, however, argue that mandating traditional styles stifles artistic freedom and increases construction costs. They contend that modern architectural designs are more energy-efficient and functional for contemporary residential needs. While modern thermal insulation and building mechanics are undeniably necessary, they can easily be concealed behind traditionally styled exterior facades. Integrating modern sustainable interiors with traditional vernacular exteriors allows communities to enjoy contemporary comfort without sacrificing their cultural legacy.

In conclusion, preserving architectural distinctiveness is essential for preventing the homogenization of historic towns. Municipal regulations requiring traditional styles ensure that urban development respects cultural history while remaining functionally modern.', 0, 1200, 15, 'medium', 'Discuss architectural preservation in historic towns. Address cultural heritage and tourism in body 1, tackle modern functionality and costs in body 2, and offer a synthesized conclusion.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-012', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Free Open-Access University Textbooks', 'Higher education institutions should replace commercial textbooks with peer-reviewed open-access digital learning materials that are free for all students.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'The escalating cost of commercial academic textbooks has imposed a severe financial burden on university students globally. I strongly agree that higher education institutions should transition entirely to peer-reviewed, open-access digital learning materials provided free of charge.

The most compelling reason for adopting open textbooks is improving educational equity and student academic performance. Commercial textbook publishers routinely charge hundreds of dollars for single volumes, forcing economically disadvantaged students to delay purchasing books or forgo required course readings altogether. This commercial barrier directly undermines academic success and perpetuates educational inequality. Open-access digital textbooks ensure that every enrolled student possesses immediate, permanent access to high-quality learning resources from the first day of class. Furthermore, digital open textbooks allow instructors to modify and update instructional content regularly, ensuring that students learn the most current scientific discoveries rather than outdated commercial editions.

Opponents often contend that commercial publishers provide rigorous peer review, professional graphics, and supplementary testing software that open-source authors cannot replicate. They fear that free materials might suffer from inferior editorial quality. However, academic consortiums and government grant programs can easily fund professional peer-review panels and graphic designers for open textbooks. Because academic scholars author commercial textbooks for prestige rather than corporate royalties, universities can redirect a fraction of their library budgets to support open scholarly publishing directly.

In summary, replacing expensive commercial textbooks with open-access digital alternatives dismantles financial barriers to knowledge. Democratizing access to academic resources enhances higher education quality and equity.', 0, 1200, 15, 'medium', 'Argue for open-access university textbooks. Detail financial equity and pedagogical flexibility in body 1, address quality control and peer-review funding in body 2, and conclude effectively.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-013', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Workplace Keystroke Monitoring', 'Employers should be legally prohibited from using automated software to monitor employees'' keystrokes, webcam feeds, and screen activity during working hours.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'The rapid expansion of telecommuting has led many corporations to deploy invasive surveillance software that tracks worker keystrokes, captures random webcam photos, and records active screen time. I firmly agree that governments should enact legislation prohibiting such intrusive automated surveillance in the workplace.

The central argument against automated worker monitoring is the erosion of fundamental human dignity and mutual trust. Constantly tracking an employee''s every movement treats professional adults like untrustworthy machinery, inducing chronic anxiety and psychological distress. Workers subjected to continuous digital surveillance report higher rates of exhaustion, depression, and diminished morale. Moreover, measuring keystrokes or mouse clicks fails to evaluate true productivity; reflective analysis, creative planning, and strategic thinking do not register as rapid typing, perversely incentivizing superficial busyness over substantive quality and innovation.

Conversely, employer organizations argue that automated monitoring is necessary to verify hours worked, prevent employee time theft, and safeguard confidential corporate data. While managing productivity and securing trade secrets are legitimate corporate goals, they are far more effectively achieved through objective performance milestones and output-based evaluations. Managers should evaluate whether agreed projects are completed accurately and punctually, rather than scrutinizing second-by-second keyboard inputs.

In conclusion, invasive digital surveillance degrades workplace culture and damages employee psychological well-being without providing accurate measures of professional value. Banning continuous automated tracking restores professional dignity and fosters productivity based on mutual respect and measurable results.', 0, 1200, 15, 'medium', 'Take a stance on workplace digital surveillance. Discuss psychological harm and flawed productivity metrics in body 1, evaluate management accountability and output-based management in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-014', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Subsidising Electric Bicycles', 'Governments seeking to reduce urban transport emissions should subsidise electric bicycles instead of electric passenger cars.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'To combat urban air pollution and greenhouse gas emissions, public authorities have spent billions subsidizing consumer purchases of battery-electric passenger automobiles. However, I believe that governments should reallocate these environmental subsidies toward electric bicycles, which provide far greater ecological and urban benefits.

The foremost advantage of electric bicycles is their superior resource and energy efficiency. Manufacturing a two-ton electric sport utility vehicle requires immense quantities of lithium, cobalt, steel, and aluminum, generating substantial embodied carbon emissions before the vehicle is ever driven. In contrast, an electric bicycle uses a tiny fraction of the battery capacity of an automobile and consumes minimal grid electricity. Furthermore, replacing car journeys with electric bicycles directly alleviates urban traffic congestion, reduces parking demand, and encourages daily physical cardiovascular activity. Electric bikes enable commuters of all fitness levels to traverse hilly terrain and commute comfortably without arriving exhausted, making sustainable transit accessible to a broad public.

Opponents often point out that electric cars remain indispensable for long-distance regional travel, inclement weather transit, and transporting large families or heavy cargo. While automobiles certainly serve specific intercity functions, the vast majority of daily urban trips are under ten kilometers, distances ideally suited for light personal electric mobility. Subsidizing expensive electric cars primarily benefits affluent suburban homeowners while doing nothing to resolve downtown gridlock or road safety hazards.

In conclusion, electric bicycles offer a far more sustainable, equitable, and cost-effective solution for decarbonizing metropolitan transport. Redirecting public subsidies toward light electric mobility creates healthier, more liveable cities.', 0, 1200, 15, 'medium', 'Weigh subsidies for e-bikes versus electric cars. Compare resource efficiency and traffic alleviation in body 1, address car utility for long trips/weather in body 2, and conclude with an urbanist perspective.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-015', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Phasing Out Peat Extraction for Commercial Horticulture', 'Environmental protection agencies should prohibit the commercial extraction and retail sale of peat moss for gardening to protect vital wetland carbon sinks.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Peatlands represent some of the most critical terrestrial ecosystems on the planet, functioning as immense natural carbon storehouses that regulate planetary climate stability. I strongly support the proposal to ban commercial peat harvesting and retail distribution for gardening, as preserving intact wetland ecosystems far outweighs the convenience of inexpensive horticultural soil conditioners.

The primary environmental justification for halting peat extraction is the urgent imperative of global climate mitigation. Peat bogs accumulate decayed vegetation over thousands of years beneath waterlogged, anaerobic conditions, trapping vast quantities of atmospheric carbon. When commercial operators drain and scrape these wetlands for horticultural packaging, the exposed organic matter oxidizes rapidly, releasing centuries of stored carbon directly into the atmosphere as greenhouse gases. Furthermore, industrial extraction irreversibly destroys unique wetland habitats, eliminating specialized flora and drying out surrounding hydrological basins that prevent regional wildfires and buffer against seasonal flooding.

Commercial nurseries and retail gardening enterprises frequently argue that peat moss provides unmatched moisture retention and aeration that cannot be readily matched by alternative growing media. They contend that a sudden prohibition would raise production costs and reduce plant nursery yields. However, modern sustainable horticulture offers viable, eco-friendly alternatives such as composted bark, coconut coir, and aged municipal green waste. Many progressive agricultural producers have already transitioned to peat-free compost blends without sacrificing crop vitality. Public environmental regulations are precisely what is needed to accelerate the adoption of these renewable, circular alternatives across the entire industry.

In conclusion, sacrificing irreplaceable wetland carbon sinks for recreational gardening soil is ecologically shortsighted. Prohibiting commercial peat extraction is an essential, sensible policy to protect planetary carbon reservoirs and restore fragile freshwater wetlands.', 0, 1200, 15, 'medium', 'Support the ban on commercial peat extraction for horticulture. Discuss peat bog carbon storage and ecological destruction in body 1, evaluate nursery moisture concerns and highlight sustainable alternatives like coconut coir in body 2, and summarize in conclusion.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-016', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Preserving Physical Paper Archives', 'National libraries and museums should continue preserving physical paper records and books rather than relying entirely on digital scans.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'The rapid digitisation of historical documents has transformed academic research by making cultural heritage accessible worldwide with a single click. However, I firmly agree that national libraries and archives must continue preserving original physical paper collections rather than relying exclusively on digital surrogates.

The primary justification for preserving physical documents is their long-term technological resilience. Digital storage media, including magnetic tapes, hard drives, and cloud servers, are vulnerable to catastrophic data corruption, hardware obsolescence, and malicious cyber attacks. File formats that were standard two decades ago are already unreadable by contemporary operating systems. In contrast, acid-free rag paper and historical vellum manuscripts have survived intact for over a millennium without needing software updates or electricity. Original paper artifacts ensure an unbroken historical record that cannot be wiped out by digital infrastructure failures.

Furthermore, original paper documents possess physical and forensic value that digital scans cannot capture. Historians analyze paper watermarks, chemical ink compositions, binding threads, and margin indentations to authenticate manuscripts and deduce historical trade routes. A digital scan displays text, but it completely strips away the physical material evidence essential for primary historical scholarship.

Admittedly, digital scanning is indispensable for widespread public access and daily researcher inquiries. Nevertheless, digital versions should serve as convenient access tools rather than permanent replacements for original artifacts. In conclusion, preserving physical paper archives safeguards human history against technological vulnerability and ensures the authenticity of our shared cultural memory.', 0, 1200, 15, 'medium', 'Argue for preserving physical paper archives alongside digitisation. Contrast digital format obsolescence and cyber risks with paper longevity in body 1, highlight forensic material value in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-017', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Philosophy in Primary Curricula', 'Primary schools should introduce philosophy and critical thinking discussions for young children starting from the age of seven.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Elementary education has traditionally centered on foundational literacy and arithmetic skills. However, I strongly support the proposal to introduce philosophical inquiry and critical reasoning discussions into primary school curricula for children aged seven and older.

The most significant advantage of early philosophy instruction is the development of independent, analytical reasoning. In an era saturated with sensationalist digital content and online misinformation, children need the cognitive tools to evaluate evidence, question unexamined assumptions, and construct coherent logical arguments. Engaging seven-year-olds in open-ended philosophical discussions, such as exploring fairness, truth, and moral responsibility through age-appropriate stories, trains them to express reasoned opinions rather than merely memorizing facts. Classroom observations demonstrate that children exposed to philosophy for children programs exhibit measurable gains in reading comprehension, mathematical problem-solving, and verbal articulation.

In addition to cognitive benefits, philosophical dialogue cultivates essential social and emotional competencies. During philosophical circles, pupils learn to listen respectfully to divergent perspectives, disagree constructively without hostility, and change their minds when presented with superior reasoning. These collaborative habits diminish playground bullying and foster classroom empathy. While critics may argue that young children lack the abstract cognitive maturity for philosophy, experienced educators know that children are naturally curious philosophers who eagerly ponder fundamental questions about existence and justice.

In summary, introducing philosophical inquiry in primary school equips young minds with critical discernment and civic tolerance. Far from being an elitist luxury, early philosophy lays the foundation for thoughtful, democratic citizenship.', 0, 1200, 15, 'medium', 'Defend introducing philosophy in primary education. Focus on analytical reasoning and media discernment in body 1, social-emotional empathy in body 2, and conclude on democratic citizenship.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-018', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Carbon Border Adjustment Taxes', 'Governments should impose carbon border adjustment tariffs on imported industrial goods manufactured in countries with weak environmental regulations.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'As developed economies enact ambitious domestic climate policies, domestic manufacturers often face higher operating expenses than foreign competitors unburdened by environmental rules. I strongly agree that governments should implement carbon border adjustment tariffs on carbon-intensive imports to prevent environmental outsourcing and ensure fair market competition.

The primary justification for carbon border tariffs is the prevention of carbon leakage. When a nation enforces stringent domestic carbon taxes or emission caps, local companies may simply relocate their manufacturing facilities to developing regions with lax regulations, or domestic consumers may buy cheaper, highly polluting foreign imports. This dynamic produces no net reduction in global greenhouse gas emissions; it merely exports industrial jobs while global pollution remains unchanged. Levying a border tariff equivalent to the domestic carbon price eliminates this perverse incentive, ensuring that imported steel, cement, and fertilizers compete on a level economic playing field with cleaner domestic production.

Critics contend that carbon border adjustments represent disguised protectionism that unfairly penalizes developing nations lacking the capital to invest in green technologies. While this equity concern is legitimate, importing governments can resolve it by dedicating tariff revenues to international climate finance and clean technology transfers for developing exporters. Importantly, border tariffs create a powerful economic incentive for exporting countries to establish their own domestic carbon pricing systems so that tax revenues remain within their own treasuries rather than being paid at foreign borders.

To conclude, carbon border adjustment taxes are an essential regulatory mechanism for global climate accountability. They shield progressive domestic industries while accelerating worldwide decarbonization through market incentives.', 0, 1200, 15, 'medium', 'Support carbon border adjustment tariffs. Discuss carbon leakage and fair economic competition in body 1, address protectionism and technological assistance in body 2, and conclude persuasively.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-019', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Public Quiet Zones in Cities', 'Metropolitan governments should designate acoustic quiet zones in urban parks and public squares where amplified music and loud phone conversations are prohibited.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Modern urban environments are increasingly characterized by pervasive sensory overload and chronic acoustic noise from traffic, construction, and commercial activities. I firmly agree that metropolitan authorities should establish designated acoustic quiet zones in public parks and squares to provide city residents with psychological respite.

The foremost justification for public quiet zones is the protection of mental health and cognitive restoration. Medical professionals consistently demonstrate that chronic exposure to noise pollution elevates cortisol levels, induces sleep disorders, and increases cardiovascular risks. Urban residents require accessible green spaces where they can escape auditory intrusion and decompress. Prohibiting amplified loudspeakers, motorized equipment, and loud mobile phone calls in designated municipal sanctuaries allows citizens to experience natural soundscapes, such as rustling foliage and birdsong. Research in environmental psychology confirms that spending time in quiet natural settings significantly lowers blood pressure and restores attentional capacity after stressful working hours.

Skeptics may argue that public parks are communal recreation spaces where citizens should enjoy the freedom to socialize, celebrate, and play music. While social vitality is an important urban attribute, quiet zones do not require silencing an entire city. Municipalities can allocate specific sections of parks for active sports and musical performances while reserving tranquil groves specifically for contemplative silence. Establishing clear spatial separation ensures that different community needs are accommodated without infringing on those seeking peaceful rejuvenation.

In summary, acoustic tranquility is a fundamental urban amenity that contributes directly to public wellbeing. Designating enforced quiet zones preserves pockets of peace within bustling metropolitan centers.', 0, 1200, 15, 'medium', 'Argue for designated quiet zones in urban parks. Focus on health benefits and psychological restoration in body 1, resolve conflicts with active recreation in body 2, and conclude with civic value.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-020', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Food Raw Ingredient Origin Labeling', 'Food processing companies should be legally required to disclose the specific country of origin of all raw ingredients on product packaging.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Globalized supply chains mean that processed foodstuffs sold in supermarkets often contain agricultural ingredients sourced from multiple continents. I strongly agree that food manufacturers should be legally obligated to clearly disclose the exact country of origin for all primary raw ingredients on packaging labels.

The primary argument for comprehensive ingredient labeling is consumer autonomy and health safety. Consumers have a fundamental democratic right to know where their food originates, whether driven by environmental concerns regarding food transportation miles, ethical objections to foreign labor standards, or personal health precautions. Different nations enforce vastly different agricultural regulations regarding pesticide residue thresholds, antibiotic usage in livestock, and heavy metal soil contamination. When product labels vaguely state that an item was packaged domestically using imported ingredients, consumers are deprived of the crucial information needed to make informed choices that protect their families'' dietary health.

Food manufacturing lobbies frequently resist mandatory origin labeling, arguing that tracking multiple shifting ingredient suppliers increases administrative complexity and retail grocery prices. They claim that seasonal harvests force companies to change suppliers frequently. However, contemporary digital supply-chain tracking systems and blockchain ledgers already allow commercial processors to trace inventory with precision. The minor cost of updating product packaging is negligible compared to the vital public health transparency it delivers.

To conclude, transparent ingredient sourcing empowers consumers and holds multinational food corporations accountable for agricultural safety standards. Mandating country-of-origin labeling on all raw ingredients is an indispensable measure for consumer rights and food security.', 0, 1200, 15, 'medium', 'Support mandatory origin labeling for raw food ingredients. Highlight consumer autonomy, pesticide standards, and health safety in body 1, rebut industry cost claims in body 2, and summarize in conclusion.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-021', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Banning Drive-Through Restaurants', 'Municipal councils should ban the construction of new drive-through fast-food restaurants in metropolitan urban centers.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Drive-through restaurant facilities have long been a hallmark of car-oriented suburban development. However, I firmly agree that municipal councils should prohibit new drive-through restaurants in metropolitan centers to promote public health, road safety, and environmental sustainability.

The most compelling reason to ban drive-throughs is the reduction of vehicular congestion and localized air pollution. Drive-through lanes inevitably cause long queues of idling passenger cars that spill onto municipal streets, blocking public transit lanes and creating severe pedestrian hazards at sidewalk crossings. Vehicle exhaust concentrated around drive-through windows exposes nearby pedestrians and residential neighbors to dangerous particulate matter and nitrogen oxides. Furthermore, urban design that caters exclusively to private vehicles directly contradicts modern municipal goals of encouraging walkable, pedestrian-oriented streetscapes. Eliminating drive-through lanes fosters dense, walkable retail districts where residents walk, cycle, and patronize local storefront businesses.

Opponents argue that drive-throughs provide essential convenience for busy working parents, delivery drivers, and individuals with physical mobility limitations who find exiting a car difficult. While convenience is desirable, automotive convenience should not compromise urban air quality and public safety. City centers possess abundant public transit, delivery services, and accessible ground-floor cafes that accommodate disabled patrons without requiring idling car queues. Drive-through models are better suited to rural highway interchanges than dense urban cores.

In conclusion, drive-through restaurants exacerbate traffic congestion, air pollution, and pedestrian danger in metropolitan areas. Prohibiting their construction in city centers is a necessary step toward building healthy, walkable communities.', 0, 1200, 15, 'medium', 'Take a stance on banning urban drive-through restaurants. Emphasize idling emissions, pedestrian safety, and walkability in body 1, address convenience and mobility needs in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-022', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Transitioning to Sovereign Cloud Infrastructure', 'National governments should store public health and administrative records on domestic public cloud infrastructure rather than contracting foreign commercial technology firms.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'As government agencies digitize confidential citizen records, the question of data sovereignty and infrastructure ownership has become a critical national security issue. I strongly agree that governments should store public health and administrative data exclusively on domestic sovereign infrastructure rather than relying on foreign commercial cloud providers.

The primary justification for sovereign data hosting is the protection of national security and citizen privacy. Entrusting electronic medical files, tax records, and census data to foreign technology conglomerates exposes sovereign data to extraterritorial surveillance and foreign legal subpoenas. For example, foreign intelligence laws often compel technology companies to disclose data hosted on their servers regardless of where the physical data center is located. Furthermore, in times of geopolitical conflict or trade disputes, foreign corporations could terminate cloud access or disrupt critical public services, paralyzing national hospital administration and social security payments. Developing domestic sovereign cloud capabilities guarantees uninterrupted operational continuity and insulates public records from foreign political coercion.

Skeptics often contend that domestic public sector infrastructure cannot match the cybersecurity sophistication, continuous innovation, and economies of scale offered by multinational technology giants. They fear that domestic government clouds would be costlier and more vulnerable to hacking. While building domestic infrastructure requires substantial initial capital investment, nations can partner with local technological consortiums under strict public governance. Investing in domestic digital sovereignty also stimulates local high-tech employment and software engineering expertise, generating long-term economic dividends.

In conclusion, citizen data is a vital national asset that must remain under domestic democratic control. Investing in sovereign cloud infrastructure is essential for safeguarding national security and digital privacy.', 0, 1200, 15, 'medium', 'Evaluate sovereign government data storage versus multinational commercial clouds. Emphasize national security and privacy in body 1, address costs and technical sophistication in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-023', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Regulating Maritime Cruise Ships', 'Coastal cities should restrict the size and frequency of commercial cruise ships entering their ports to mitigate environmental and social damage.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'The maritime cruise industry has expanded rapidly, with mega-vessels carrying thousands of tourists into historic coastal ports worldwide. I strongly agree that coastal municipalities should enforce strict limits on the size and frequency of cruise ship arrivals to protect marine environments and local communities.

The environmental toll of giant cruise ships is devastating to coastal ecosystems. Massive marine engines burn low-grade bunker fuel, releasing massive quantities of sulfur dioxide, particulate soot, and greenhouse gases directly into port atmospheres, creating acute respiratory risks for shoreline residents. In addition, cruise vessels discharge millions of liters of sewage and graywater, disrupting fragile coastal marine life and destroying coral reefs. On land, the sudden disembarkation of thousands of cruise passengers overwhelms historical town infrastructure, causing suffocating street congestion and displacing local cultural life while contributing very little to the local economy, as passengers eat and sleep aboard their prepaid ships.

Tourism industry representatives argue that restricting cruise arrivals damages local business revenues, particularly for souvenir vendors, tour guides, and transport operators. They assert that cruise tourism provides indispensable seasonal employment. However, economic assessments consistently demonstrate that overnight hotel guests contribute significantly more revenue to local restaurants and cultural venues with a fraction of the environmental damage. A sustainable tourism economy relies on high-value, low-impact visitors rather than mass passenger turnover that degrades the very heritage attracting tourists.

To conclude, the ecological and societal costs of unregulated mega-cruise tourism far outweigh its modest economic contributions. Implementing strict port quotas and vessel size limits is crucial for preserving coastal heritage.', 0, 1200, 15, 'medium', 'Argue for restrictions on cruise ships in coastal ports. Detail air/water pollution and overtourism in body 1, weigh economic claims against actual net benefits in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-024', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Mandatory Academic Data Archiving', 'Scientific researchers receiving public funding should be legally required to deposit all raw research data in open-access public repositories.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'The reproducibility crisis in modern science has raised serious questions about the reliability of published academic research. I firmly agree that all researchers receiving public financial support should be legally obligated to deposit their complete raw datasets into open-access repositories upon publication.

The foremost benefit of mandatory data sharing is ensuring scientific reproducibility and accelerating discovery. When independent scientists can inspect raw experimental data, code scripts, and statistical calculations, they can verify published claims, detect methodological errors, and eliminate fraudulent research. Transparent data archiving restores public trust in academic literature and prevents wasteful duplication of expensive experiments. Furthermore, open datasets can be re-analyzed by researchers worldwide using novel analytical techniques, unlocking cross-disciplinary discoveries that original investigators never envisioned. Because taxpayers fund public research grants, the resulting empirical data belongs in the public domain rather than remaining locked in private laboratory hard drives.

Some researchers object that mandatory data deposition exposes proprietary findings to intellectual theft and misinterpretation by unqualified individuals before the original authors can publish follow-up publications. They also cite the administrative burden of cleaning and documenting complex datasets for public use. While these concerns are understandable, repositories can easily implement temporary embargo periods to allow researchers to publish secondary analyses. Moreover, universities and granting agencies should allocate explicit funding and credit for data curation, treating well-maintained public datasets as major scholarly achievements.

In summary, open data archiving is essential for scientific integrity and collaborative innovation. Requiring public grant recipients to share raw research data ensures accountability and maximizes the societal return on scientific investments.', 0, 1200, 15, 'medium', 'Support mandatory open data sharing for publicly funded research. Focus on reproducibility and accelerated discovery in body 1, tackle intellectual property and workload concerns in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-025', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Rewilding Marginal Farmland', 'Governments should purchase uneconomic agricultural land from willing farmers and rewild it to restore native forests and wildlife habitats.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Global biodiversity is declining at an unprecedented rate due to habitat fragmentation and agricultural expansion. I strongly support the policy of governments purchasing marginal, unprofitable farmland from willing landowners to restore native ecosystems through comprehensive rewilding initiatives.

The primary justification for rewilding marginal land is the restoration of vital ecosystem services and biodiversity. Much agricultural land located on steep hillsides or depleted soils produces low crop yields while requiring heavy chemical inputs that contaminate waterways. Allowing these marginal landscapes to revert to natural native forests, wetlands, and peat bogs creates interconnected ecological corridors where endangered wildlife, insects, and plant species can recover. Furthermore, regenerating native woodlands and wetlands acts as a permanent terrestrial carbon sink, absorbing atmospheric carbon while reducing downstream flood risks by slowing rainwater runoff across river basins. Financially compensating struggling farmers who wish to sell provides them with economic security while converting unproductive land into permanent natural wealth.

Critics, however, raise concerns regarding national food security, arguing that retiring agricultural land diminishes domestic crop production and increases reliance on food imports. While food security is vital, contemporary agricultural technology allows modern farms to achieve record yields on prime fertile land through precision farming. Rewilding targets only unproductive, heavily subsidized land that contributes minimally to overall food supplies. Moreover, healthy ecosystems support agriculture by sustaining wild pollinator populations and regulating regional hydrology.

In conclusion, purchasing and rewilding marginal agricultural acreage represents a forward-thinking investment in planetary health. This policy restores biodiversity, captures carbon, and mitigates natural disasters while supporting rural economic transitions.', 0, 1200, 15, 'medium', 'Evaluate government purchase and rewilding of marginal farmland. Highlight biodiversity and climate resilience in body 1, address food security concerns in body 2, and summarize in conclusion.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-026', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Subsidising Residential Solar Storage', 'State renewable energy subsidies should prioritize household home battery storage systems over additional rooftop solar panel installations.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'As rooftop solar adoption expands globally, electrical distribution networks increasingly struggle to manage surplus midday solar generation. I agree that governments should reorient renewable subsidies toward domestic home battery storage systems rather than continuing to fund additional solar panels alone.

The critical argument for prioritizing battery storage is grid stability and energy utilization. Photovoltaic solar panels generate peak electrical output during midday hours when residential electricity demand is typically low. Without adequate decentralized storage, this excess clean energy is either curtailed or fed into local grids, causing severe voltage instability and power surges. Conversely, during evening peak hours when household consumption surges, grids must ramp up fossil-fuel peaker plants because solar generation has ceased. Subsidizing home batteries allows households to store surplus daytime solar electricity and consume it during evening peaks, smoothing demand curves and directly displacing carbon-intensive fossil fuel generation.

On the other hand, skeptics point out that home batteries remain expensive and rely on scarce minerals such as lithium and cobalt, whose mining causes environmental damage. They argue that expanding solar capacity generates more total kilowatt-hours of clean power per subsidy dollar invested. While generating green power is vital, uncoordinated solar expansion without storage yields diminishing returns once grids reach saturation. Directing public subsidies toward residential storage creates market scale, driving down battery manufacturing costs and incentivizing the development of alternative battery chemistries.

In conclusion, decentralized energy storage is the linchpin of a reliable, fully decarbonized electrical grid. Prioritizing home battery subsidies solves the solar intermittency challenge and builds a resilient, decentralized energy architecture.', 0, 1200, 15, 'medium', 'Take a stance on subsidizing home batteries over more solar panels. Discuss grid stability and evening displacement of fossil fuels in body 1, examine mineral and cost limitations in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-027', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Legal Personhood for Ecosystems', 'Vulnerable natural ecosystems such as rivers, forests, and mountain ranges should be granted legal personhood with enforceable rights in courts of law.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Traditional legal systems treat the natural world as property, permitting resource extraction and pollution until severe human harm can be proven. I strongly support the emerging legal doctrine granting vulnerable ecosystems legal personhood, enabling them to hold enforceable statutory rights in courts of law.

The foremost benefit of legal personhood for ecosystems is shifting the burden of environmental protection from human property damage to ecological integrity. Under conventional environmental law, citizens can only sue polluters if they demonstrate direct economic injury or personal health damage. When an ecosystem possesses legal personhood, appointed guardians, such as indigenous councils and environmental scientists, can initiate legal action directly on behalf of a polluted river or clear-cut forest. Courts can mandate restitution and environmental remediation based on the ecosystem''s intrinsic right to exist, regenerate, and maintain its natural evolutionary cycles. This framework has already proven effective in countries like New Zealand and Colombia, where rivers granted legal rights received unprecedented conservation funding and protection.

Critics often argue that granting legal rights to non-human entities creates legal absurdity and paralyzes economic development. They contend that infrastructure projects like hydroelectric dams or highways could be blocked by endless litigation. However, legal personhood does not forbid all human interaction with nature; rather, it establishes balanced legal standing akin to corporate personhood. Just as corporations hold legal rights without halting commerce, ecosystems can possess rights that ensure resource development respects ecological thresholds and community stewardship.

In conclusion, recognizing ecosystems as legal persons provides a revolutionary legal tool to halt environmental destruction. Elevating nature''s status in law reflects our profound ecological interdependence.', 0, 1200, 15, 'medium', 'Argue for or against legal personhood for ecosystems. Detail legal standing and proactive remediation in body 1, address economic disruption and parallels to corporate personhood in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-028', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Graduated Driver Licensing for Adults', 'Adults obtaining a driver''s license for the first time should be subjected to the same multi-stage restrictions as teenage novice drivers.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Traffic safety regulations historically impose graduated licensing systems—including night-driving curfews and passenger limits—exclusively on teenage novice drivers. I strongly agree that all first-time adult drivers, regardless of age, should undergo identical graduated licensing restrictions to enhance road safety.

The central argument for universal graduated licensing is that vehicular collision risk is primarily determined by inexperience behind the wheel rather than chronological maturity alone. Operating a motor vehicle requires complex spatial judgment, split-second hazard perception, and automated psychomotor coordination that only develop through hundreds of hours of real-world driving experience. An adult novice driver possesses the same perceptual blind spots and delayed emergency braking reflexes as an eighteen-year-old beginner. Statistical analyses confirm that first-year adult drivers experience crash rates significantly higher than experienced drivers of the same age group. Subjecting adult novices to supervised driving phases, night-driving limits, and zero-alcohol thresholds provides a protective environment while they develop defensive driving instincts.

Opponents argue that adult learners possess greater emotional maturity, impulse control, and practical life responsibilities, such as commuting to work and caring for children. They contend that imposing curfews on adult workers creates severe economic hardship and impedes employment mobility. While adult maturity certainly reduces reckless risk-taking, it cannot substitute for basic neuromuscular driving experience. To alleviate economic hardship, licensing authorities can grant work-specific travel exemptions while maintaining core safety restrictions, ensuring that public safety is not compromised.

In summary, inexperience is the primary driver of automotive accidents. Applying graduated licensing to all new drivers establishes a rigorous safety standard that protects drivers of all ages.', 0, 1200, 15, 'medium', 'Evaluate applying graduated licensing to adult novice drivers. Contrast experience vs age in body 1, address employment needs and work exemptions in body 2, and summarize in conclusion.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-029', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Regulating Behavioral Ad Tracking', 'Internet technology companies should be prohibited from collecting user browsing history to display personalized behavioural advertisements.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'The business model of the contemporary internet is overwhelmingly funded by targeted digital advertising powered by extensive surveillance of user online activity. I firmly agree that regulatory authorities should outlaw the tracking of personal browsing histories for behavioral advertising purposes.

The primary justification for banning behavioral tracking is the preservation of individual privacy and psychological autonomy. Commercial advertising networks deploy hidden trackers, cookies, and device fingerprinting to construct granular psychological profiles of millions of citizens, monitoring their political views, health searches, and financial vulnerabilities. This invasive surveillance treats personal data as a monetizable commodity without meaningful informed consent. Furthermore, behavioral targeting enables predatory advertising, such as targeting subprime loans to financially distressed consumers or gambling ads to recovering addicts. Eliminating behavioral tracking terminates these manipulative practices and restores privacy as a fundamental digital right.

On the other hand, the digital marketing industry argues that behavioral advertising provides consumers with relevant advertisements and finances free access to search engines, journalism, and social platforms. They warn that banning tracking would force online services to introduce subscription fees, creating digital inequality. However, digital media successfully flourished for decades using contextual advertising, where ads are matched to the content of the webpage being viewed rather than the personal history of the reader. Contextual marketing respects user privacy while generating substantial advertising revenue for publishers.

To conclude, intrusive behavioral ad tracking undermines privacy and exploits psychological vulnerabilities. Banning behavioral tracking while transitioning to contextual advertising creates a safer, more ethical digital ecosystem.', 0, 1200, 15, 'medium', 'Support banning behavioral advertising tracking. Detail privacy violations and predatory targeting in body 1, evaluate contextual advertising as a sustainable alternative in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-030', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'National Seed Bank Networks', 'Governments should allocate substantial public funding to establish decentralized national seed vaults to conserve indigenous crop varieties.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Modern industrial agriculture relies heavily on a narrow selection of genetically uniform, high-yielding crop hybrids, causing a dangerous loss of agricultural biodiversity. I strongly agree that national governments should invest significant public funds in establishing comprehensive, decentralized seed vault networks to preserve indigenous crop varieties.

The foremost argument for conserving native seeds is agricultural resilience against climate change, emerging plant diseases, and pest infestations. Traditional heirloom crop varieties possess genetic traits evolved over centuries, including drought tolerance, saline soil resistance, and natural defenses against localized pathogens. When environmental conditions change or novel crop blights emerge, plant geneticists must access wild and indigenous seed banks to breed resistant crop varieties. If these ancestral seeds become extinct, the raw genetic material required to safeguard global food security is lost forever. Furthermore, establishing decentralized regional vaults ensures that localized disasters, wars, or technical power failures cannot wipe out a nation''s entire botanical heritage in a single catastrophic event.

Critics may contend that preserving thousands of archaic seed varieties is an expensive, low-priority luxury when public budgets are constrained. They argue that commercial seed corporations already maintain genetic libraries tailored to market needs. However, private corporations prioritize profitable commercial seeds with intellectual property protections, neglecting subsistence crops essential for local biodiversity. Agricultural preservation is a public good that cannot be entrusted solely to commercial market incentives.

In summary, public seed banks represent indispensable insurance against global agricultural collapse. Investing in decentralized conservation vaults protects crop genetic diversity and guarantees long-term food sovereignty.', 0, 1200, 15, 'medium', 'Advocate for public funding of decentralized seed banks. Highlight genetic resilience and climate adaptation in body 1, contrast public security with private corporate interests in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-031', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Commercial Building Energy Audits', 'Governments should legally mandate annual energy-efficiency audits for all commercial office buildings and penalize owners of poorly performing properties.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'The commercial building sector is one of the largest consumers of electrical energy and producers of greenhouse gas emissions worldwide. I firmly agree that governments should mandate annual energy audits for all commercial office properties and enforce progressive financial penalties on owners who fail to meet efficiency benchmarks.

The primary justification for mandatory building audits is overcoming the split-incentive dilemma that impedes voluntary energy retrofits. In commercial real estate, building owners frequently pass utility expenses directly to commercial tenants through lease agreements. Consequently, landlords have minimal financial incentive to invest capital in modern heating, ventilation, air conditioning, and insulation systems, while tenants lack the authority to make structural improvements. Enforcing mandatory annual audits and imposing statutory fines for energy waste compels property owners to upgrade obsolete infrastructure. Experiences in cities with mandatory benchmarking laws show that public transparency and regulatory fines rapidly accelerate green building renovations, cutting metropolitan electricity consumption and carbon emissions significantly.

Opponents argue that mandatory audits and penalties impose an unfair regulatory cost on property owners, particularly during economic downturns when office vacancies are elevated. They contend that market forces and corporate sustainability goals are already encouraging landlords to seek green certifications voluntarily. However, voluntary green certifications capture only prestige properties, leaving thousands of aging, energy-inefficient buildings untouched. Governments can assist landlords by offering low-interest green renovation loans and tax credits, ensuring that the transition to energy efficiency is economically manageable while remaining strictly enforceable.

In conclusion, commercial building efficiency is vital for achieving national climate targets. Enforcing mandatory audits and penalties eliminates landlord complacency and transforms wasteful office towers into energy-efficient assets.', 0, 1200, 15, 'medium', 'Argue for mandatory commercial energy audits and penalties. Explain the split-incentive problem and retrofit urgency in body 1, address financial burdens with green loans in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-032', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Biometric Border Verification', 'International airports should replace traditional paper passports with mandatory automated facial recognition biometric gates for all travelers.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'International air travel volumes continue to surge, placing immense operational strain on traditional airport immigration checkpoints. While automated biometric facial recognition offers undeniable processing speed, I disagree with completely eliminating physical passports in favor of mandatory biometric border surveillance.

The foremost concern regarding mandatory biometric border screening is the grave risk to personal data security and human rights. Unlike a paper passport, which can be cancelled and reissued if stolen, a person''s facial biometric data is permanent and immutable. If national biometric immigration databases are breached by state-sponsored cybercriminals, citizens'' irreversible biometric identifiers are compromised forever. Furthermore, centralized biometric surveillance systems carry profound risks of government mission creep, enabling authoritarian surveillance, wrongful tracking of political dissidents, and systemic algorithmic bias. Extensive independent testing has revealed that facial recognition algorithms exhibit significantly higher error and false-match rates for ethnic minorities, leading to wrongful detentions and humiliation at international borders.

Proponents of biometric border control argue that automated gates dramatically shorten passenger queuing times and eliminate fraudulent or counterfeit physical travel documents. While operational efficiency is important, biometric technology can be deployed safely as an optional convenience alongside physical passports, rather than replacing them entirely. Retaining physical paper passports with embedded cryptographic chips ensures that travelers maintain possession of their personal credentials without requiring universal biometric tracking.

In summary, the convenience of biometric border gates does not justify the irreversible privacy risks and algorithmic discrimination inherent in mandatory facial surveillance. Preserving physical passports maintains essential safeguards for civil liberties and personal security.', 0, 1200, 15, 'medium', 'Evaluate replacing passports with mandatory facial biometric gates. Detail data security, permanent identifiers, and racial bias in body 1, discuss convenience and hybrid alternatives in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-033', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Domestic Medical Equipment Manufacturing', 'Nations should subsidise domestic manufacturing of essential medical diagnostic equipment rather than depending on global supply chains.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'The globalization of healthcare manufacturing has led many countries to rely almost entirely on foreign imports for critical medical diagnostic equipment, including ventilators, dialysis machines, and scanning instruments. I strongly agree that governments should subsidise and protect domestic manufacturing of essential medical technology to guarantee national healthcare sovereignty.

The primary justification for domestic production is healthcare resilience during global crises. Recent international emergencies graphically demonstrated that global supply chains fracture precisely when demand is most acute. When manufacturing nations enacted export restrictions to prioritize their own domestic hospitals, dependent countries faced catastrophic shortages of life-saving medical apparatuses. Relying on distant supply chains leaves national healthcare systems dangerously vulnerable to geopolitical tensions, shipping bottlenecks, and foreign export controls. Establishing domestic manufacturing capacity ensures that domestic hospitals maintain immediate access to diagnostic tools regardless of international disruptions.

Economists often argue that subsidizing domestic medical manufacturing defies the economic principle of comparative advantage, leading to higher equipment prices and inferior technological quality compared to specialized global leaders. They contend that open international trade delivers superior, cost-effective devices. However, essential healthcare security cannot be evaluated solely through narrow free-market efficiency. Just as nations subsidise domestic agriculture and defense industries to guarantee baseline survival, strategic medical independence is an indispensable pillar of national defense that warrants public subsidy.

To conclude, complete dependence on foreign healthcare supply chains exposes citizens to unacceptable medical vulnerabilities. Subsidising domestic diagnostic equipment manufacturing guarantees national resilience and protects public health.', 0, 1200, 15, 'medium', 'Defend domestic manufacturing subsidies for medical equipment. Discuss supply chain vulnerability and geopolitical risk in body 1, address comparative advantage and cost in body 2, and conclude strongly.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-034', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'National Highway Maximum Speed Limits', 'Governments should lower national highway speed limits to eighty kilometers per hour to reduce fuel consumption and road fatalities.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Automotive transport accounts for a substantial share of global petroleum consumption and fatal traffic accidents. I support the proposal to lower national highway maximum speed limits to eighty kilometers per hour, as the environmental and safety gains far outweigh the minor inconvenience of longer journey times.

The foremost benefit of reduced highway speeds is the dramatic reduction in vehicular greenhouse gas emissions and fuel consumption. The physical laws of aerodynamics dictate that atmospheric drag increases exponentially with speed. Vehicles traveling at very high motorway speeds consume considerably more fuel per kilometer than those traveling at moderate speeds. Lowering speed limits instantly cuts national petroleum demand and reduces exhaust emissions without requiring expensive infrastructure investments. Furthermore, lower travel speeds significantly reduce braking distances and collision severity, saving thousands of lives annually. Countries that implemented temporary speed reductions consistently recorded immediate, measurable declines in fatal highway crashes.

Critics, however, contend that lower speed limits impair economic productivity by lengthening transport times for freight logistics and business travelers. They argue that modern automotive engineering, featuring advanced automated braking and collision avoidance systems, makes higher speeds safe. While extended transit times do impose minor scheduling adjustments, the economic cost of slower travel is dwarfed by the billions of dollars saved in reduced fuel imports, emergency medical expenditures, and property damage from catastrophic high-speed collisions.

In summary, reducing highway speed limits to eighty kilometers per hour delivers immediate environmental, financial, and life-saving benefits. Slower speeds represent a sensible, practical policy for sustainable modern transportation.', 0, 1200, 15, 'medium', 'Argue for lower highway speed limits. Emphasize aerodynamic fuel savings and crash survival physics in body 1, address economic transit delays and vehicle technology in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-035', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Household Appliance Repair Education', 'Secondary schools should make practical repair workshops for domestic electrical appliances a compulsory subject for all students.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'In our contemporary consumer society, broken household appliances are routinely discarded and replaced with new products rather than repaired. I firmly agree that secondary schools should mandate practical repair workshops for domestic appliances as a compulsory part of education.

The primary educational value of teaching appliance repair is fostering self-reliance, practical problem-solving, and demystifying technology. Modern educational curricula are heavily skewed toward abstract academic theory, leaving many young adults unable to diagnose basic mechanical or electrical faults in their own homes. Learning how to safely test fuses, replace worn wiring, and troubleshoot consumer electronics teaches students the practical application of physics and circuitry. These hands-on diagnostic competencies build intellectual confidence, manual dexterity, and spatial reasoning that benefit students in everyday life and inspire interest in engineering and technical trades.

Equally important is the environmental imperative to combat electronic waste. Electronic waste is the fastest-growing waste stream on the planet, leaking hazardous heavy metals into soils and consuming finite natural resources. A consumer culture that views appliances as disposable consumables is ecologically unsustainable. When young people understand how to repair and maintain their own possessions, they develop a conservation mindset that rejects planned obsolescence. While critics may argue that school schedules are overcrowded and that repairing modern integrated circuits is too difficult for adolescents, basic electrical repairs remain accessible and deliver lifelong economic savings.

In conclusion, practical repair education empowers students with valuable life skills while fostering environmental stewardship. Making repair workshops compulsory equips future generations to build a resilient, circular economy.', 0, 1200, 15, 'medium', 'Support compulsory appliance repair in secondary schools. Detail self-reliance and STEM applications in body 1, highlight the circular economy and e-waste reduction in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-036', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Restricting Commercial Groundwater Extraction in Drought Regions', 'Municipal water authorities should strictly restrict commercial beverage corporations from extracting deep groundwater reserves in agricultural regions experiencing seasonal droughts.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Clean freshwater is an essential public resource and a fundamental human necessity, yet expanding commercial bottling operations increasingly compete with local communities for finite subterranean water supplies. I firmly agree that municipal water regulators should impose stringent limits on commercial beverage companies extracting groundwater in drought-prone farming regions.

The foremost reason to restrict commercial water extraction is the imperative to protect agricultural food production and household drinking reserves. In arid and semi-arid valleys, farming communities depend entirely on underground aquifers to irrigate staple food crops and sustain municipal residential taps during prolonged dry seasons. Deep industrial extraction wells operated by commercial beverage bottlers depress regional water tables, causing shallow domestic farm wells to run dry and forcing family farmers into financial insolvency. Allowing private corporations to siphon subterranean public waters for profit while local agricultural harvests wither is an unconscionable misallocation of natural resources.

Bottling corporations and beverage manufacturers frequently contend that their commercial facilities stimulate regional economic development, generate municipal tax revenues, and create valuable manufacturing employment in rural districts. They suggest that deep extraction draws from deep aquifers that do not immediately affect surface farming. However, modern hydrology demonstrates that all groundwater layers are interconnected within broader geological watersheds. The economic value of a few bottling plant jobs cannot compensate for the collapse of surrounding agricultural livelihoods and the destruction of communal water security. Industrial bottling can easily be relocated to water-abundant regions.

In summary, freshwater must be managed as a vital shared heritage rather than an exploitable industrial commodity. Restricting corporate groundwater extraction in drought-threatened farming valleys is an indispensable measure to safeguard agrarian communities and domestic food security.', 0, 1200, 15, 'medium', 'Argue for restricting commercial groundwater extraction in drought regions. Detail aquifer depletion and agricultural survival in body 1, address corporate economic contributions and hydrogeological reality in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-037', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Nocturnal Aviation Restrictions', 'Commercial passenger and cargo flights should be strictly prohibited from taking off or landing at urban airports between midnight and six in the morning.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'As global commerce operates continuously across time zones, nocturnal aviation traffic over populated metropolitan centers has increased markedly. I firmly agree that commercial passenger and freight flights should be banned at urban airports between midnight and six in the morning to protect public health and nocturnal tranquility.

The foremost argument for a nighttime flight curfew is the safeguarding of restorative sleep and neurological well-being for millions of urban residents. Aviation noise is uniquely disruptive; sudden, loud decibel spikes from jet engines directly penetrate residential bedrooms, triggering sleep fragmentation, elevated blood pressure, and adrenaline surges even when sleeping individuals do not consciously awaken. Medical research consistently links chronic nocturnal aircraft noise to elevated risks of hypertension, clinical depression, and impaired cognitive development in schoolchildren living beneath airport flight corridors. Establishing an inviolable nighttime curfew guarantees quiet hours that allow human biological circadian rhythms to recover naturally.

Cargo logistics carriers and discount passenger airlines argue that nocturnal flight bans would disrupt global express supply chains and inflate ticket prices by reducing airport operational capacity. They contend that overnight hours are essential for shipping perishable cargo and time-critical medical supplies. While freight logistics is important, non-emergency overnight cargo flights can easily be rerouted to dedicated cargo airfields located in rural, sparsely populated areas away from dense urban centers. Commercial airlines can adjust flight scheduling without sacrificing public health.

In summary, continuous sleep is an essential human biological necessity that takes precedence over commercial aviation scheduling. Implementing strict nocturnal flight curfews is an indispensable measure to protect urban public health.', 0, 1200, 15, 'medium', 'Argue for nocturnal flight bans at urban airports. Detail sleep disruption, hypertension, and cognitive harm in body 1, evaluate cargo supply chain logistics and rural airport alternatives in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-038', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Micro-Apartments in Urban Centers', 'City planning authorities should encourage the construction of micro-apartments under twenty-five square meters to address metropolitan housing affordability.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Metropolitan housing costs have reached historic highs, pricing young professionals and low-wage workers out of urban centers. While micro-apartments are sometimes criticized as substandard living quarters, I believe that municipal zoning authorities should encourage micro-housing under twenty-five square meters as a practical solution to urban affordability.

The primary merit of micro-apartments is that they provide dignified, independent, and affordable accommodation in prime central locations. For single young professionals, students, and starting workers, traditional one-bedroom apartments are financially out of reach, forcing many into long, soul-crushing suburban commutes or overcrowded, precarious shared flats. Micro-housing equipped with space-efficient multi-functional furniture and shared communal amenities—such as co-working lounges, industrial kitchens, and rooftop terraces—delivers high-quality urban living at manageable rental rates. Living centrally allows residents to walk or cycle to employment hubs, reducing private car reliance and activating urban street vitality.

Critics contend that promoting ultra-compact dwellings normalizes cramped conditions and risks psychological distress from confinement, arguing that developers will exploit micro-units to maximize profits. While poorly designed micro-units can indeed feel claustrophobic, municipal building regulations can prevent abuses by mandating high ceiling heights, expansive natural daylight, superior acoustic soundproofing, and generous communal living spaces. High-density micro-housing should not replace family dwellings, but rather expand the diversity of urban housing choices for the growing population of single-person households.

In conclusion, well-regulated micro-apartments represent an innovative and pragmatic tool to tackle metropolitan housing crises. Embracing compact living preserves urban affordability and inclusivity for a new generation.', 0, 1200, 15, 'medium', 'Support micro-apartments for housing affordability. Discuss central living, affordability, and walkability in body 1, address confinement concerns with design regulations in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-039', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Laboratory-Grown Construction Materials', 'Governments should heavily fund research into laboratory-grown biological construction materials to replace extractive concrete and steel in architecture.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'The traditional building sector is one of the most environmentally destructive industries on the planet, with concrete and steel manufacturing contributing a major share of global carbon emissions. I strongly agree that governments should provide substantial public research subsidies to accelerate the development of bio-manufactured, laboratory-grown construction materials.

The most compelling justification for biological construction materials is the complete decarbonization of the built environment. Innovative bio-materials, such as mycelium-based insulation blocks, microbially induced calcite masonry, and synthetic lab-grown structural proteins, grow organically by consuming agricultural waste products under mild ambient temperatures. Unlike Portland cement, which requires superheating limestone to over one thousand degrees Celsius in fossil-fueled kilns, biological materials act as net carbon sinks, sequestering atmospheric carbon directly within structural elements. Furthermore, bio-materials are completely biodegradable and non-toxic, resolving the mounting crisis of construction demolition debris that clogs metropolitan landfills.

Skeptics argue that biological materials lack the extreme compressive strength, fire resistance, and structural longevity of traditional reinforced concrete and structural steel, making them impractical for skyscrapers and bridges. While current bio-materials are primarily suited for non-structural insulation and low-rise dwellings, massive public funding is precisely what is needed to optimize their mechanical density and durability. Just as early synthetic polymers evolved through intensive scientific research into high-strength aerospace composites, sustained funding can transform bio-materials into mainstream construction elements.

In conclusion, relying perpetually on extractive concrete and steel is ecologically unsustainable. Investing public funds in lab-grown building materials paves the way for an architecture that heals rather than damages the global environment.', 0, 1200, 15, 'medium', 'Advocate for public funding of lab-grown biological building materials. Emphasize carbon sequestration and landfill waste reduction in body 1, address structural strength skepticism in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-040', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Mandatory Ten-Year Electronics Spare Parts', 'Consumer electronics manufacturers should be legally required to provide spare parts and repair manuals for a minimum of ten years after product release.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Modern consumer technology products, from smartphones to laptops, are frequently designed with glued casings and proprietary screws that make independent repair virtually impossible. I strongly agree that governments should mandate that electronics manufacturers make replacement parts, diagnostic software, and repair manuals accessible for at least ten years following release.

The foremost argument for mandatory spare parts availability is consumer economic protection and the defense of ownership rights. When a consumer spends hundreds or thousands of dollars on an electronic device, they should legitimately possess the right to repair it when a single component, such as a battery or charging port, deteriorates. Under current corporate practices, manufacturers refuse to sell replacement components, effectively forcing consumers to purchase expensive new models. Mandating ten-year access to original spare parts and repair guides empowers consumers and independent repair technicians, fostering a competitive local repair economy and drastically reducing consumer electronics expenditures.

Furthermore, extending device lifespans is an urgent ecological imperative. Electronic waste contains toxic chemicals, including lead and mercury, while the manufacturing of new electronics consumes vast quantities of rare earth elements and water. Manufacturers contend that storing replacement parts for a decade imposes excessive warehousing costs and slows technological innovation. However, modern digital manufacturing, such as on-demand three-dimensional printing, enables affordable localized part production without massive warehousing. Genuine innovation should be measured by durability and repairability, not planned obsolescence.

In conclusion, legally requiring a decade of spare parts access curtails planned obsolescence and curbs toxic electronic waste. Protecting the right to repair restores consumer fairness and fosters a sustainable electronics industry.', 0, 1200, 15, 'medium', 'Support mandatory 10-year electronics spare parts laws. Discuss consumer ownership and local repair economies in body 1, address e-waste and manufacturer cost objections in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-041', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Mandatory Energy Efficiency Standards for Rental Properties', 'Property owners should be legally prohibited from renting out residential properties that fail to meet strict thermal insulation and energy efficiency standards.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Residential housing accounts for an immense proportion of national energy consumption and carbon emissions, largely due to inefficient space heating and poor thermal insulation. I strongly agree that governments should mandate that landlords upgrade properties to strict energy efficiency benchmarks before offering them on the rental market.

The primary justification for mandatory standards is overcoming the split-incentive dilemma inherent to tenancy agreements. Landlords who do not reside in a property have little financial motivation to invest capital in high-performance insulation, double-glazed windows, or modern heat pumps, because tenants bear the monthly heating utility bills. Consequently, low-income tenants often endure drafty, damp accommodations that consume excessive fuel while failing to provide adequate thermal comfort. Enforcing minimum regulatory standards protects vulnerable renters from fuel poverty, prevents hazardous mold proliferation, and curbs domestic carbon emissions simultaneously.

Opponents often contend that stringent energy requirements place an unfair capital burden on small property owners, who may pass costs directly to tenants through higher monthly rents or withdraw properties from the market entirely. While retrofitting older homes does entail initial capital outlays, governments can mitigate this friction by offering low-interest green renovation loans and tax credits. In the long run, well-insulated homes preserve structural integrity, lower overall societal healthcare expenses, and increase property values.

To conclude, voluntary incentives have proven insufficient to decarbonize aging rental housing stock. Establishing legally binding thermal efficiency standards protects tenant welfare and represents an essential policy for achieving national climate objectives.', 0, 1200, 15, 'medium', 'Argue in favor of mandatory insulation standards for rental homes. Explain the split-incentive dilemma and tenant health in body 1, address landlord costs and rent increases in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-042', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Dark Sky Environmental Lighting Codes', 'Municipalities should enforce strict dark-sky lighting regulations that mandate fully shielded outdoor luminaires and extinguish non-essential commercial lighting after midnight.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'The relentless proliferation of artificial lighting has illuminated night skies across the globe, virtually erasing nocturnal darkness in metropolitan areas. I strongly support the enactment of strict municipal dark-sky regulations that mandate downward-shielded streetlights and require non-essential commercial illumination to be extinguished after midnight.

The primary justification for dark-sky ordinances is the preservation of ecological equilibrium and human circadian health. Artificial light at night severely disrupts wildlife behavior, disorienting migrating birds, interfering with nocturnal pollinators, and decimating insect populations drawn to unshielded lamps. In humans, excessive exposure to nocturnal light, particularly blue wavelengths, suppresses melatonin production, disrupting natural sleep patterns and increasing risks of metabolic and hormonal disorders. Furthermore, unshielded outdoor lighting wastes immense amounts of electrical power by projecting light uselessly into the sky, needlessly inflating municipal energy bills and carbon emissions. Mandating fully shielded fixtures directs light precisely where needed on sidewalks and roadways without atmospheric light spillover.

Opponents often claim that reducing night lighting will compromise public safety and invite criminal activity. However, criminological research demonstrates that bright, unshielded glare actually creates deep, harsh shadows that hide perpetrators and temporarily blind pedestrians and drivers. Well-designed, fully shielded lighting illuminates street surfaces evenly with lower intensity, improving pedestrian visibility while reducing glare. Commercial storefronts do not need glaring promotional neon signs after midnight when streets are empty.

In conclusion, darkness at night is a vital environmental and biological necessity. Enforcing dark-sky municipal lighting codes conserves electrical energy, protects biodiversity, and restores the natural nocturnal sky for humanity.', 0, 1200, 15, 'medium', 'Support municipal dark-sky lighting codes. Detail ecological disruption and human melatonin suppression in body 1, refute crime fears through uniform shielded lighting in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-043', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Craft Apprenticeship Tax Incentives', 'Governments should offer substantial tax reductions to companies that provide paid apprenticeships in traditional manual trades rather than subsidizing academic university degrees.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Higher education policy over recent decades has heavily prioritized academic university degrees, resulting in a severe societal shortage of skilled trade professionals, such as electricians, carpenters, and plumbers. I agree that governments should rebalance public investments by offering generous tax incentives to businesses that train paid apprentices in vocational trades.

The primary justification for incentivizing vocational apprenticeships is addressing critical labor market shortages while offering debt-free career pathways for youth. Modern economies urgently require skilled technicians to install renewable energy grids, maintain aging infrastructure, and construct energy-efficient buildings. However, decades of promoting university as the sole prestigious route have left millions of university graduates underemployed and burdened with crippling student debt, while trade contractors struggle to fill high-paying manual vacancies. Tax credits encourage businesses to take on apprentices, allowing young adults to earn a living wage while acquiring invaluable practical competencies on the job without accumulating academic debt.

Skeptics argue that prioritizing manual trades neglects the high-technology knowledge economy, which relies on university graduates in computing, biotechnology, and management. However, promoting trade apprenticeships does not mean defunding universities; rather, it corrects a deep societal imbalance. An advanced economy cannot function without both theoretical engineers and the practical craftsmen who build and maintain real-world systems. Elevating vocational training through fiscal incentives restores dignity and economic parity to manual professions.

In summary, subsidizing trade apprenticeships bridges the gap between educational training and real-world employment needs. Tax incentives for vocational training build a resilient workforce and support sustainable economic development.', 0, 1200, 15, 'medium', 'Support tax incentives for trade apprenticeships over university degree subsidies. Emphasize labor shortages and debt-free careers in body 1, address knowledge economy needs in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-044', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Mandatory Human Review in Welfare Administration', 'Governments should legally mandate human administrative review for all automated algorithmic decisions concerning social welfare benefits and public housing eligibility.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Public welfare assistance provides an essential safety net for vulnerable citizens facing economic hardship, disability, or housing instability. As government agencies increasingly adopt automated algorithms to process aid claims, I strongly support the proposal to mandate human administrative review before any automated decision to deny, reduce, or cancel social benefits takes effect.

The most compelling argument for compulsory human oversight is the prevention of catastrophic bureaucratic errors and algorithmic bias. Computerized welfare assessment models operate on rigid mathematical rules that cannot comprehend nuanced human circumstances, such as sudden medical emergencies, informal caregiving duties, or administrative paperwork discrepancies. In automated welfare systems around the world, software glitches and miscalculated fraud-detection models have wrongly stripped thousands of impoverished families of essential food allowances and housing subsidies, plunging innocent individuals into severe deprivation. A qualified human caseworker can recognize systemic errors, exercise contextual discretion, and correct false flags before irreversible harm occurs.

Proponents of automated welfare administration argue that computational algorithms streamline case processing, reduce administrative overhead, and eliminate human subjectivity in public expenditure. They suggest that requiring manual reviews would create massive operational backlogs and inflate government staffing costs. While automated screening is useful for initial data verification, human review should serve as an indispensable fail-safe mechanism rather than a barrier to efficiency. Preserving a mandatory human touchpoint ensures that public institutions maintain basic procedural fairness and democratic accountability toward the most vulnerable members of society.

In conclusion, automating decisions that affect human survival without human intervention carries unacceptably high social risks. Mandating casework oversight in social welfare administration guarantees that technology serves public compassion and justice rather than bureaucratic neglect.', 0, 1200, 15, 'medium', 'Support mandatory human review for automated welfare decisions. Highlight algorithmic errors and vulnerable claimant protection in body 1, address bureaucratic speed and administrative cost arguments in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-045', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Workplace Mindfulness Initiatives', 'Large corporations should provide daily paid meditation and stress-reduction sessions as a standard employee benefit.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Modern corporate environments are characterized by relentless digital notifications, tight deadlines, and chronic workplace stress, which take a severe toll on employee psychological well-being. I agree that large corporations should integrate daily paid meditation and mindfulness sessions into the standard working day.

The primary justification for employer-sponsored mindfulness practice is the substantial improvement in mental health, emotional regulation, and cognitive clarity. Clinical neuroscience proves that daily mindfulness meditation thickens prefrontal brain regions associated with emotional self-control while shrinking the amygdala, the brain''s fear and stress center. Providing employees with twenty minutes of paid daily mindfulness allows workers to decompress, regain attentional focus, and break cycles of cognitive exhaustion. In turn, lower workplace anxiety leads to fewer stress-related medical absences, improved interpersonal collaboration, and higher employee retention rates. Far from being lost time, daily mindfulness increases overall worker productivity and creativity.

Critics, however, contend that corporate mindfulness is an empty public relations gesture that places the responsibility for stress management onto individual workers rather than addressing systemic overwork and excessive workloads. They argue that employees would prefer shorter working hours or higher wages instead of mandatory relaxation. While mindfulness should never be used to mask toxic workplace practices or unreasonable quotas, when combined with healthy management structures, voluntary paid mindfulness provides genuine physiological support. It signals an organizational culture that values human well-being alongside commercial targets.

In summary, incorporating paid mindfulness sessions into the corporate workday fosters a healthier, more focused workforce. Investing in mental resilience benefits both employee wellbeing and long-term organizational success.', 0, 1200, 15, 'medium', 'Evaluate corporate mindfulness and stress-reduction programs. Discuss neuroscience and productivity in body 1, address concerns about masking overwork and superficial PR in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-046', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Banning Disposable Alkaline Batteries', 'Governments should ban the retail sale of single-use disposable alkaline batteries in favor of standardized rechargeable battery cells.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Billions of single-use disposable alkaline batteries are purchased and discarded annually worldwide, powering everything from toys to television remotes. I strongly agree that governments should phase out the retail sale of disposable alkaline batteries and mandate the universal adoption of standardized rechargeable battery cells.

The primary argument for prohibiting disposable batteries is the staggering environmental waste and energy inefficiency of single-use chemistry. Manufacturing a disposable alkaline battery consumes approximately fifty times more electrical energy than the battery ever delivers during its operational life. Furthermore, despite extensive recycling campaigns, the overwhelming majority of disposable batteries end up in municipal landfills, where corrosive electrolyte chemicals and heavy metals, such as zinc and manganese, leach into subterranean groundwater. Modern rechargeable nickel-metal hydride and lithium cells can be recharged hundreds of times, displacing hundreds of disposable units with a single rechargeable battery. Transitioning to rechargeables drastically cuts raw mineral extraction and toxic chemical pollution.

Retailers and consumers often resist bans because disposable alkaline batteries have a lower initial retail purchase price compared to rechargeable cells and charging units. They also point out that disposables hold their charge in low-drain devices, like smoke detectors, for years without self-discharging. While initial purchase costs are slightly higher, consumers save substantial money over time by reusing rechargeable cells. Moreover, low self-discharge rechargeable technology now retains the vast majority of its charge for several years, making rechargeables fully viable for all household applications.

In conclusion, disposable alkaline batteries represent an obsolete, wasteful consumer model. Banning single-use batteries and adopting standardized rechargeables is an essential, straightforward step toward environmental sustainability.', 0, 1200, 15, 'medium', 'Support banning single-use alkaline batteries. Detail energy waste and toxic landfill leaching in body 1, address upfront cost and low-drain device claims in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-047', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Open-Source Government Software Mandates', 'Public sector institutions should be legally required to use open-source software and publish all publicly funded custom code under open licenses.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Government agencies spend billions of dollars of taxpayer money annually licensing proprietary commercial software from multinational technology corporations. I strongly agree that public sector institutions should be legally mandated to prioritize open-source software and release all custom government software code into the public domain.

The foremost justification for an open-source mandate is the principle that public money should fund public code. When taxpayers finance the development of administrative portals, healthcare databases, or educational platforms, that software should belong to the public rather than being locked away behind commercial copyright. Publishing government code under open-source licenses allows local businesses, academic institutions, and independent software engineers to inspect, reuse, and improve the software, stimulating domestic technological innovation. Furthermore, open-source software enhances cybersecurity through public transparency; independent security researchers can identify and patch vulnerabilities before malicious hackers can exploit them, unlike opaque proprietary systems with hidden flaws.

Proprietary software vendors argue that commercial software provides professional technical support, comprehensive liability guarantees, and continuous user updates that volunteer open-source communities cannot guarantee. They fear that public agencies lack the in-house technical expertise to maintain open software. However, governments can easily contract local software engineering firms to provide professional maintenance for open-source systems. This approach keeps IT spending within the domestic economy rather than funneling taxpayer wealth into foreign corporate licensing fees.

In conclusion, mandating open-source software in the public sector guarantees fiscal efficiency, technological transparency, and public ownership. Public code strengthens democratic governance and fosters national digital innovation.', 0, 1200, 15, 'medium', 'Argue for open-source software mandates in government. Emphasize public money/public code and cybersecurity transparency in body 1, address support and vendor lock-in concerns in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-048', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Subsidising Regional Passenger Rail', 'Governments should heavily subsidise passenger rail tickets to make train travel significantly cheaper than short-distance domestic flights.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Domestic aviation is one of the most carbon-intensive modes of transport, producing massive greenhouse gas emissions for journeys that often cover only a few hundred kilometers. I strongly agree that governments should heavily subsidise regional passenger railway fares to ensure that train travel is substantially cheaper and more attractive than domestic short-haul flights.

The primary justification for rail subsidies is environmental decarbonization. High-speed and regional electric passenger trains produce vastly fewer carbon emissions per passenger-kilometer than commercial passenger aircraft. Aviation emissions released directly into the upper atmosphere have an amplified warming effect. However, under current market conditions, airlines often offer artificially cheap tickets because aviation kerosene is exempt from fuel taxes, while train operators pay heavy track access fees. Providing targeted public subsidies to lower train fares corrects this market distortion, encouraging millions of travelers to choose low-carbon rail. Furthermore, trains connect central city centers directly, eliminating time-consuming airport security lines and suburban travel.

Fiscal conservatives argue that rail subsidies place a heavy burden on national taxpayers and that travelers who choose to travel should pay the full economic cost of their journey. They contend that public funds should not prop up expensive railway operations. However, public subsidies for air travel are already enormous in the form of tax-free fuel and publicly funded airport infrastructure. Redirecting public financial support to railways is a direct investment in climate mitigation that reduces highway congestion, cuts air pollution, and enhances national connectivity.

In conclusion, subsidizing regional train fares is an urgent environmental and economic necessity. Making train travel affordable and accessible is vital for achieving a sustainable transportation future.', 0, 1200, 15, 'medium', 'Support subsidizing passenger rail fares to undercut domestic flights. Compare emissions and urban center connectivity in body 1, refute subsidy burden arguments by highlighting hidden aviation subsidies in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-049', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Microplastic Filtration on Storm Drains', 'Municipalities should install and maintain microplastic filtration systems on all urban stormwater drainage outfalls that discharge into rivers and oceans.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Microplastic contamination has emerged as one of the most pervasive ecological crises of our time, polluting aquatic food chains from alpine streams to the deep ocean. I strongly agree that municipal governments should be legally mandated to install and maintain specialized microplastic filtration systems on all urban stormwater drainage outfalls.

The primary argument for stormwater filtration is that urban surface runoff is the single largest land-based pathway delivering microplastics into aquatic environments. Whenever it rains, urban stormwater washes billions of microscopic particles—derived from synthetic vehicle tire wear, synthetic textiles, and degraded plastic debris—directly into street storm sewers, which discharge untreated wastewater directly into local rivers and coastal bays. These microscopic polymers absorb toxic chemical contaminants and are ingested by fish, shellfish, and plankton, ultimately bioaccumulating up the marine food web onto human dinner plates. Installing mechanical swirl separators and bio-retention filters at drainage outfalls captures these micro-particles at the point of discharge before they disperse uncontrollably across marine ecosystems.

Municipal authorities frequently object to mandatory filtration mandates, citing the significant capital installation costs and the recurring labor expenses required to clean and maintain thousands of filtration traps. While the fiscal costs of municipal retrofits are substantial, governments can finance these infrastructure investments by levying environmental fees on tire manufacturers and plastic producers under extended producer responsibility frameworks. The financial cost of installing filtration is negligible compared to the permanent ecological degradation and public health damage caused by unchecked plastic pollution.

In summary, urban stormwater runoff is a major highway for microplastic pollution. Enforcing mandatory filtration at drainage outfalls is an essential, proactive defense for aquatic biodiversity and human health.', 0, 1200, 15, 'medium', 'Advocate for mandatory microplastic filtration on municipal stormwater outfalls. Detail tire dust runoff and marine food chain bioaccumulation in body 1, address municipal costs via producer fees in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-we-050', 'pte-2026-01', 'PTE', 'writing', 'pte-write-essay', 'Write Essay', 'Regulating Algorithmic Rent Pricing', 'Governments should prohibit residential landlords from using centralized algorithmic pricing software to coordinate and set apartment rental rates.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'In many metropolitan rental markets, corporate landlords increasingly utilize centralized software platforms that collect proprietary leasing data and employ algorithms to dictate rental rates across entire neighborhoods. I firmly agree that governments should outlaw the use of centralized algorithmic pricing systems in residential housing to prevent artificial rent inflation and anticompetitive collusion.

The foremost argument against algorithmic rent setting is that it functions as a digital price-fixing cartel that destroys free-market competition. In a normal competitive market, landlords lower rents or offer concessions to fill vacant apartments when supply exceeds demand. However, algorithmic pricing platforms instruct participating landlords to keep prices artificially inflated and even leave units vacant to maintain high market pricing power across an entire district. Because the software aggregates confidential, non-public data from competing property managers, it coordinates tacit collusion that would be illegal if conducted by human executives in a smoke-filled room. This algorithmic cartelization directly fuels metropolitan housing crises, rendering shelter unaffordable for working families.

Property management corporations defend algorithmic pricing as mere operational software that optimizes revenue using market supply-and-demand indicators, arguing that landlords retain final pricing discretion. In reality, empirical antitrust investigations demonstrate that landlords adopt algorithmic price recommendations almost universally, effectively outsourcing pricing decisions to a centralized monopoly engine. Housing is a fundamental human necessity that cannot be subjected to manipulative automated price gouging.

In conclusion, centralized algorithmic rent pricing undermines fair market competition and drives unjustified rental hyperinflation. Banning automated pricing software restores competitive fairness and protects tenants from corporate exploitation.', 0, 1200, 15, 'medium', 'Argue against algorithmic rent pricing in residential housing. Explain digital price-fixing cartels and artificial vacancy in body 1, refute supply-and-demand defense by citing antitrust collusion findings in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Write Essay'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-001', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Public Funding for Nuclear Fusion Energy', 'Governments should allocate billions of dollars of public research funding to developing commercial nuclear fusion energy.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'As the world grapples with escalating energy demands and the catastrophic consequences of climate change, the search for abundant, zero-emission baseload power is paramount. I strongly agree that national governments should commit billions of dollars in public research funding to accelerate the development of commercial nuclear fusion power.

The primary justification for funding fusion research is its unparalleled potential as the ultimate clean energy source for human civilization. Unlike fossil fuels, nuclear fusion produces zero greenhouse gas emissions or toxic atmospheric pollutants. Unlike conventional nuclear fission, fusion does not produce high-level long-lived radioactive waste, relies on abundant isotopes such as deuterium extracted from seawater, and carries negligible risk of catastrophic runaway meltdowns. If successfully developed, commercial fusion could provide reliable baseload electricity to complement intermittent renewable systems and support power-intensive industries. Given the urgent need to decarbonize global energy systems, exploring fusion technology represents a valuable avenue for long-term energy security.

Critics often argue that nuclear fusion has absorbed massive public expenditures for decades without delivering commercial electricity, famously remaining far from commercialization. They contend that public funds should be spent deploying proven renewable technologies like solar panels and wind turbines today. While deploying current renewables is vital, solar and wind suffer from weather intermittency and storage limitations. Recent experimental milestones have demonstrated scientific net energy gain under laboratory conditions, suggesting that further progress is attainable with sustained commitment, even though formidable engineering hurdles remain.

In conclusion, while nuclear fusion is not an immediate substitute for existing clean technologies, allocating public funding to fusion research is a prudent long-term investment in diversifying future zero-carbon energy options. Allocating substantial public funding to fusion development is a visionary investment in a prosperous, carbon-free future.', 0, 1200, 15, 'medium', 'Support public funding for nuclear fusion. Detail limitless clean fuel and absence of long-lived nuclear waste in body 1, address historical delays and intermittency of current renewables in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-002', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Mandatory Water Efficiency in Buildings', 'Building codes should mandate rainwater harvesting systems and low-flow plumbing fixtures in all newly constructed residential properties.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Freshwater scarcity is becoming one of the most critical environmental challenges of the twenty-first century, exacerbated by population growth and climatic shifts. I strongly agree that municipal building regulations should legally mandate rainwater collection systems and low-flow sanitary fixtures in all new residential developments.

The primary argument for mandatory water efficiency in construction is the conservation of municipal water supplies and the reduction of urban stormwater runoff. Domestic households consume immense quantities of treated potable water for non-drinking purposes, such as toilet flushing, laundry, and garden irrigation. Installing rainwater harvesting tanks allows homes to capture precipitation for these domestic tasks, directly reducing pressure on reservoirs and subterranean aquifers during prolonged droughts. Simultaneously, low-flow aerated faucets and dual-flush toilets cut household water consumption substantially without compromising user comfort. Capturing rainwater on-site also reduces peak runoff volumes, mitigating urban flash flooding and easing strain on municipal storm sewer networks.

Property developers frequently object that mandatory water fixtures increase upfront construction expenses and raise home purchase prices. While installing storage tanks and specialized plumbing does entail modest initial capital outlays, these costs are rapidly recouped through lower monthly municipal water utility bills. Over the operational life of a home, water efficiency features deliver substantial financial savings for homeowners while safeguarding the regional environment.

To conclude, mandatory residential water conservation standards represent a practical and necessary policy. Incorporating rainwater harvesting and efficient plumbing into building codes protects vital water reserves and creates sustainable, flood-resilient communities.', 0, 1200, 15, 'medium', 'Support mandatory rainwater harvesting and low-flow fixtures. Emphasize aquifer preservation and stormwater reduction in body 1, address upfront construction costs in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-003', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Attending University Locally versus Moving Away', 'It is more advantageous for young adults to attend university in their hometown while living with parents than to move to an institution in another city.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Completing a tertiary degree is a major developmental milestone, and prospective students often face the choice between staying in their hometown or relocating to an institution elsewhere. Although staying home offers clear financial benefits, I believe that moving to a university in a different city provides far superior personal, academic, and professional advantages.

The foremost benefit of moving away from home is the rapid development of independence, self-reliance, and practical life competencies. When students live independently in dormitories or shared flats, they must manage their own personal finances, cook meals, organize household schedules, and resolve conflicts with housemates without parental intervention. This autonomy builds emotional maturity, resilience, and adaptability, which are essential attributes for navigating adult life and professional careers. Furthermore, studying in a major metropolitan educational hub exposes young adults to diverse cultures, broadening their worldview and establishing expansive professional networks that extend far beyond their childhood community.

Admittedly, attending a local university while living with family significantly reduces accommodation and living expenditures, shielding students from crippling debt. For economically disadvantaged families, this cost-saving can make the difference between pursuing higher education or entering the low-wage labor market. However, students who relocate can offset expenses through university scholarships, part-time campus employment, and student loan programs, investments that are rewarded by the accelerated personal growth that independent living cultivates.

In conclusion, while local study offers short-term economic comfort, moving to another city to pursue a degree fosters lifelong independence and self-confidence. The personal growth gained from independent living far outweighs the financial convenience of staying home.', 0, 1200, 15, 'medium', 'Evaluate studying in one''s hometown versus moving to another city. Emphasize personal independence and networking in body 1, acknowledge financial savings while presenting remedies in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-004', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Autonomous Cargo Drone Delivery in Rural Regions', 'Governments should permit and subsidize autonomous aerial drones to deliver medical supplies and consumer goods to remote rural communities.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Access to essential goods and emergency medical supplies in remote, mountainous, and rural communities is frequently obstructed by rugged terrain and deteriorating road infrastructure. I strongly support the proposal for governments to authorize and subsidize autonomous cargo drones to service isolated rural populations.

The most compelling justification for autonomous drone transport is life-saving speed and operational reliability in healthcare logistics. In remote rural valleys, transporting blood supplies, antivenoms, vaccines, and emergency pharmaceuticals by ground vehicle can take hours or even days over treacherous unpaved roads, particularly during seasonal floods or landslides. Autonomous cargo drones bypass terrestrial obstacles entirely, traveling in direct aerial flight paths to deliver critical medical cargo in minutes. Pilot programs in rugged regions globally have already demonstrated that drone delivery drastically cuts infant mortality and improves emergency trauma outcomes. Furthermore, for regular consumer packages, electric drones eliminate diesel delivery truck emissions, providing an eco-friendly freight solution.

Critics, however, raise valid concerns regarding mid-air collisions, acoustic noise pollution, and visual intrusion in tranquil rural landscapes. They fear that swarms of commercial drones will endanger low-flying light aircraft and disturb wildlife. These risks can be managed effectively through strict aviation corridor regulations, mandatory automated collision-avoidance transponders, and altitude limits. Drones should be designated specific flight paths and noise thresholds to protect rural tranquility.

In conclusion, autonomous aerial delivery bridges the geographic divide between urban centers and isolated communities. Authorizing and subsidizing cargo drones saves rural lives, promotes regional equity, and modernizes logistics for remote populations.', 0, 1200, 15, 'medium', 'Defend autonomous delivery drones for remote areas. Focus on emergency medical speed and zero emissions in body 1, address airspace safety and noise concerns in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-005', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Maritime Freight Route Electrification', 'International maritime authorities should mandate that all coastal cargo vessels switch to battery-electric or hydrogen propulsion by 2035.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Commercial shipping transports the vast majority of global trade, but the maritime industry remains one of the world''s most heavily polluting sectors. I strongly agree that international maritime regulators should mandate that coastal cargo vessels transition entirely to battery-electric or green hydrogen propulsion systems within the coming decade.

The primary argument for mandatory zero-emission shipping is the urgent need to eliminate toxic port air pollution and greenhouse gas emissions. Traditional maritime vessels burn unrefined heavy fuel oil, which releases massive quantities of sulfur oxides, nitrogen oxides, and carcinogenic particulate matter directly into coastal shipping lanes and densely populated port cities. These maritime emissions cause thousands of premature respiratory deaths annually and contribute significantly to ocean acidification and global warming. Mandating zero-emission battery and hydrogen powertrains on coastal shipping routes—where vessels travel predictable distances between domestic ports—is technically feasible with current technology and will immediately transform port air quality and marine ecology.

Shipowners and maritime logistics operators protest that retrofitting existing fleets and building hydrogen bunkering infrastructure will require colossal capital investments, warning that freight shipping rates will surge. While initial transition costs are significant, coastal electric vessels exhibit drastically lower operating and maintenance expenses than diesel engines, saving money over vessel lifespans. Furthermore, international regulatory deadlines are precisely what is needed to mobilize private investment and drive technological economies of scale in marine battery manufacturing.

In conclusion, burning toxic fossil fuels along our coastlines is an obsolete, hazardous practice. Enforcing a strict zero-emission deadline for coastal cargo ships protects coastal public health and spearheads maritime decarbonization.', 0, 1200, 15, 'medium', 'Support mandatory zero-emission propulsion for coastal cargo ships by 2035. Discuss heavy fuel oil pollution and public health in body 1, evaluate fleet retrofit costs and long-term operating savings in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-006', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Subsidising Electric Agricultural Machinery', 'Governments should subsidize agricultural farmers to replace diesel-powered tractors and harvesters with battery-electric machinery.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'The agricultural sector is heavily reliant on internal combustion diesel engines to operate heavy machinery, including tractors, combine harvesters, and irrigation pumps. I strongly support the implementation of government subsidies to assist farmers in transitioning from fossil-fuel machinery to battery-electric agricultural equipment.

The foremost justification for subsidizing electric farm machinery is the substantial reduction in greenhouse gas emissions and toxic particulate air pollution. Heavy diesel engines emit massive volumes of carbon dioxide, nitrogen oxides, and black carbon soot directly over food crops and rural communities. Electric agricultural tractors produce zero point-of-use emissions, improving local air quality for farmworkers and shielding crops from soot deposition. When charged using on-farm solar panels or rural wind turbines, electric machinery enables farms to become self-sufficient, carbon-neutral operations. Furthermore, electric motors possess significantly fewer moving parts than diesel engines, drastically reducing recurring maintenance expenses and oil replacement costs for farmers over the lifespan of the equipment.

Agricultural trade associations contend that electric machinery is currently prohibitively expensive and that battery technology lacks the energy density required for continuous, heavy plowing during tight harvest windows. They fear that frequent recharging downtime would disrupt seasonal planting. While high battery weight and charging infrastructure remain challenges, modern electric farm tractors feature swappable battery packs and fast-charging systems that eliminate operational downtime. Public subsidies are precisely what is needed to lower initial capital costs and stimulate domestic charging infrastructure in rural agricultural basins.

In conclusion, decarbonizing agriculture is vital for meeting global climate targets. Subsidizing electric agricultural machinery lowers farm operating costs, protects rural health, and accelerates the transition to sustainable farming.', 0, 1200, 15, 'medium', 'Support subsidies for electric farm equipment. Detail emissions reduction, energy independence, and low maintenance in body 1, address battery density and charging downtime in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-007', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Instantaneous Communication and Societal Patience', 'The widespread availability of instantaneous digital messaging and high-speed internet has fundamentally reduced human patience and emotional resilience.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'In today''s hyper-connected society, communication, entertainment, and commercial services are accessible in fractions of a second via smartphones. I firmly agree with the proposition that continuous reliance on instantaneous digital services has eroded human patience and weakened emotional resilience across contemporary society.

The central argument supporting this view is the neurobiological conditioning toward immediate gratification fostered by digital platforms. When individuals grow accustomed to receiving instant message replies, one-click deliveries, and on-demand streaming entertainment, their tolerance for delay, ambiguity, and natural friction declines dramatically. People become visibly agitated when website loading speeds drop by seconds or when replies are delayed by minutes. This diminished patience directly impairs deep cognitive focus and sustained intellectual effort; individuals increasingly abandon demanding tasks, such as reading complex literature or mastering musical instruments, because these pursuits require prolonged, unrewarded persistence. Over time, the inability to endure delays undermines attentional stamina.

Furthermore, instantaneous gratification damages emotional resilience in personal relationships and professional careers. Real life cannot be streamlined with a digital tap; building lasting marriages, raising children, and advancing in a career require enduring conflict, disappointment, and slow, incremental progress. When people conditioned for immediate results encounter unavoidable setbacks or interpersonal friction, they experience intense frustration, anxiety, and premature despair, lacking the emotional stamina to persevere through difficulty.

While optimists argue that rapid communication enhances organizational efficiency, speed must not be confused with emotional health. In conclusion, ubiquitous instant gratification has undeniably diminished societal patience, making the deliberate cultivation of endurance and contemplative slowness an urgent personal necessity.', 0, 1200, 15, 'medium', 'Agree or disagree that instant digital communication reduces human patience and resilience. Discuss immediate gratification and shortened attention spans in body 1, emotional fragility in relationships in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-008', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Employee Choice in Flexible Working Hours', 'Companies should allow full-time employees to determine their own working hours rather than enforcing fixed core business schedules.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'The conventional nine-to-five office schedule was conceived during the industrial manufacturing era to coordinate assembly-line production. In today''s digital knowledge economy, I strongly agree that companies should permit full-time employees to determine their own working hours rather than enforcing rigid fixed schedules.

The primary justification for autonomous scheduling is the significant enhancement of employee productivity and cognitive performance. Human biological chronotypes vary substantially; some individuals reach peak intellectual focus in the early morning hours, while others perform best late at night. Forcing all workers into identical operating schedules forces many to work during biological downtime, producing chronic mental fatigue and mediocre output. Granting workers temporal autonomy enables them to align demanding tasks with their natural peak energy periods, yielding higher quality work in shorter timeframes. Furthermore, flexible hours allow employees to balance parental duties, medical appointments, and commuting around peak traffic congestion, substantially reducing stress and elevating job satisfaction and company retention.

Skeptics, however, contend that unregulated working hours hinder inter-departmental collaboration, delay emergency client responses, and make project management chaotic. They fear that teams cannot coordinate when members are online at disparate times. However, modern asynchronous collaboration tools, shared digital project boards, and brief designated weekly synchronization windows allow teams to collaborate seamlessly without requiring synchronous presence during every working hour. Mature organizations evaluate tangible outcomes and project milestones rather than hours spent at a desk.

In conclusion, rigid corporate schedules are an outdated relic of the industrial past. Granting employees the freedom to choose their working hours unleashes individual productivity, fosters trust, and creates an adaptable corporate culture.', 0, 1200, 15, 'medium', 'Argue for autonomous employee working schedules. Detail biological chronotypes, reduced stress, and peak productivity in body 1, resolve team coordination concerns with asynchronous tools in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-009', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Natural Artistic Genius versus Deliberate Practice', 'Exceptional achievement in creative arts such as painting and music is primarily the result of disciplined deliberate practice rather than innate talent.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'The origins of extraordinary artistic mastery have long fascinated educators, psychologists, and the general public. While natural aptitude often provides an initial spark, I firmly agree that world-class achievement in painting, music, and sculpture is overwhelmingly the product of thousands of hours of disciplined, deliberate practice.

The foremost evidence supporting the primacy of deliberate practice is the neurological and technical complexity inherent in artistic mastery. Virtuoso musicians and master painters are not born with pre-programmed motor dexterity or color perception; these capabilities develop through years of rigorous, repetitive training. Deliberate practice involves setting specific technical objectives, receiving continuous expert feedback, and methodically correcting errors. Even prodigies such as Wolfgang Amadeus Mozart underwent intensive, daily musical instruction from early childhood under his father''s strict supervision before composing masterworks in adulthood. Cognitive neuroscience demonstrates that sustained practice physically reorganizes neural pathways and increases myelin insulation along nerve fibers, enabling the lightning-fast finger coordination and expressive nuance that spectators mistake for effortless innate genius.

Proponents of innate talent argue that thousands of individuals practice instruments for decades without ever achieving greatness, suggesting that an inborn genetic gift is indispensable. However, mere mindless repetition is not equivalent to deliberate practice. Most amateurs practice passively without seeking rigorous critique or expanding their comfort zones. What separates masters from average practitioners is not mysterious genetics, but an exceptional capacity for sustained, focused, and self-critical labor over many years.

In conclusion, while innate interest may initiate the artistic journey, extraordinary achievement is forged through relentless, disciplined practice. Believing in innate genius diminishes the immense dedication required to attain true artistic mastery.', 0, 1200, 15, 'medium', 'Evaluate whether artistic mastery stems from deliberate practice or innate talent. Highlight neurobiology, error correction, and Mozart''s training in body 1, distinguish passive repetition from deliberate practice in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-010', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Weighting Teaching Quality in Universities', 'Universities should evaluate and promote academic faculty members primarily on the quality of their classroom teaching rather than on their published research.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'In contemporary higher education, academic career advancement and tenure decisions are overwhelmingly governed by the quantity and prestige of published research papers. I strongly agree that universities should reform this model and evaluate faculty primarily on the quality of their classroom teaching and pedagogical mentorship.

The primary justification for prioritizing teaching quality is fulfilling the fundamental institutional obligation to undergraduate and graduate students. Students invest substantial tuition fees and years of their lives in university education, expecting inspiring, rigorous, and personalized instruction that prepares them for professional careers and civic life. Under the current publish-or-perish regime, professors frequently treat teaching as an unwelcome distraction from laboratory research and grant writing, delegating lectures to inexperienced graduate assistants or delivering uninspired, outdated monologues. Reorienting tenure evaluations toward teaching excellence incentivizes professors to adopt interactive pedagogies, design engaging curricula, and provide meaningful individual mentorship, dramatically enhancing student intellectual development and academic retention.

University administrators often argue that research publications generate institutional prestige, attract high-value commercial patents, and secure external government research grants that finance university operations. While cutting-edge scientific research is undeniably vital, universities can easily maintain specialized research tracks alongside dedicated teaching professorships. Teaching quality should not be relegated to second-class status. After all, excellent teaching directly inspires the next generation of researchers who will conduct future discoveries.

In conclusion, a university''s greatest legacy lies in the intellect, character, and capability of its graduates. Evaluating faculty primarily on teaching excellence restores educational integrity and ensures that students receive the transformative education they deserve.', 0, 1200, 15, 'medium', 'Support evaluating university faculty on teaching over research. Emphasize student tuition, mentorship, and pedagogical neglect in body 1, address research revenue and separate academic tracks in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-011', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Print Journalism versus Digital News Portals', 'Traditional print newspapers provide a more reliable and balanced understanding of current events than digital news websites and social media portals.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'The rise of the digital internet has precipitated a dramatic decline in the readership of traditional printed newspapers, with most citizens consuming news via digital portals and social feeds. Despite the convenience of digital media, I firmly agree that print newspapers offer a substantially more reliable, balanced, and thoughtful understanding of current affairs.

The foremost advantage of print journalism is the editorial discipline and thorough fact-checking enforced by publication deadlines. Printed newspapers operate on a deliberate twenty-four-hour editorial cycle. Journalists and professional copy editors possess the time to verify sources, cross-examine evidence, and provide historical context before ink hits paper. In stark contrast, digital news platforms operate under relentless twenty-four-seven competition for immediate clicks, incentivizing the publication of unverified rumors, sensationalist headlines, and emotionally polarizing commentary designed to attract digital advertising revenue. Print media filters out chaotic breaking noise, delivering coherent, verified analysis that respects readers'' intelligence.

Furthermore, the physical format of a newspaper prevents the algorithmic echo chambers that plague digital consumers. When readers open a broadsheet newspaper, they encounter diverse articles on foreign diplomacy, domestic economics, science, and the arts that they would never have deliberately searched for online. Digital platforms, by contrast, use opaque algorithms to serve content that reinforces users'' preexisting prejudices, narrowing their worldview. Print newspapers provide an editorially curated, shared civic reality essential for democratic consensus.

In conclusion, while digital media offers immediate speed, print journalism provides depth, accountability, and comprehensive perspective. Engaging with printed newspapers cultivates a more mature and well-rounded understanding of global events.', 0, 1200, 15, 'medium', 'Defend printed newspapers over digital news. Contrast the 24-hour editorial verification cycle with digital clickbait in body 1, discuss serendipitous discovery vs digital filter bubbles in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-012', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Hiring Generalists versus Technical Specialists', 'Large organizations should prioritize hiring generalists with broad problem-solving capabilities rather than narrow technical specialists.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Modern corporations and public agencies operate in an era characterized by volatile market shifts, rapid technological disruption, and cross-disciplinary challenges. In this dynamic environment, I strongly agree that organizations should prioritize hiring versatile generalists who possess broad problem-solving skills rather than narrow technical specialists.

The primary merit of hiring generalists is their intellectual agility, cognitive adaptability, and ability to connect disparate ideas. Technical specialists often view corporate challenges through the rigid lens of their specific discipline, developing intellectual blind spots that prevent creative breakthroughs. In contrast, generalists possess diverse knowledge across multiple domains, enabling them to synthesize information from marketing, engineering, and psychology to solve multifaceted organizational problems. Furthermore, in an economy where specific software languages and technical tools become obsolete every few years, generalists excel at learning new skills rapidly, making them far more resilient and valuable during corporate pivots and restructuring.

Proponents of specialization argue that complex modern fields, such as advanced artificial intelligence, corporate tax law, and biomedical engineering, require deep, specialized technical expertise that generalists cannot provide. While deep technical knowledge is undeniably necessary for executing specific complex tasks, organizations can easily contract external technical experts or employ specialized teams supervised by generalist leaders. Without broad thinkers who understand overall strategic context, ethical implications, and human dynamics, specialized technical solutions often fail to integrate into real-world business operations.

In conclusion, while specialists perform vital technical execution, generalists provide the strategic vision, adaptability, and cross-functional leadership essential for long-term organizational success. Prioritizing generalist talent builds adaptable, future-proof organizations.', 0, 1200, 15, 'medium', 'Argue for prioritizing generalists over technical specialists. Detail cognitive agility, cross-disciplinary problem-solving, and rapid learning in body 1, address specialist technical necessity in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-013', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Relocating Government Agencies to Regional Towns', 'National governments should relocate major administrative ministries and civil service departments out of capital cities into regional towns.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'In most nations, political power, administrative civil service jobs, and public expenditure are overwhelmingly concentrated in a single crowded capital metropolis. I strongly agree that national governments should decentralize governance by relocating major ministries and administrative agencies into regional provincial towns.

The primary justification for decentralizing government ministries is stimulating regional economic growth and reducing geographic inequality. Capital cities often suffer from extreme housing hyperinflation, paralyzing traffic gridlock, and overloaded public infrastructure, while regional towns experience economic stagnation, youth depopulation, and decaying services. Dispersing large government departments—such as agriculture, transportation, and environmental agencies—into provincial centers infuses regional economies with thousands of stable, high-paying public sector jobs. These civil servants spend money on local housing, hospitality, and retail, creating a powerful economic multiplier effect that revitalizes regional communities and stems the brain drain of educated youth to the capital.

Critics contend that dispersing government ministries undermines administrative coordination, increases travel expenses for inter-agency meetings, and faces resistance from civil servants who refuse to relocate away from capital cultural amenities. While physical relocation requires logistical adjustments, contemporary high-speed teleconferencing, collaborative cloud platforms, and modern rail networks make daily face-to-face meetings in the capital completely unnecessary. Furthermore, policy makers who live and work among regional citizens develop a far more grounded understanding of national challenges than bureaucrats insulated inside an elite capital bubble.

In conclusion, decentralizing government departments revitalizes neglected regional economies while easing capital congestion. Relocating public administration promotes geographic fairness and connects government directly to the people it serves.', 0, 1200, 15, 'medium', 'Support relocating government ministries to regional towns. Discuss regional economic stimulation and capital decongestion in body 1, address coordination and relocation reluctance in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-014', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Mandatory Microchip Identification for Pets', 'Governments should legally mandate subcutaneous microchip identification for all domestic dogs and cats and impose fines on unregistered pet owners.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Domestic companion animals bring immense joy to millions of households, but stray, abandoned, and lost pets pose significant animal welfare and public safety challenges in urban communities. I firmly agree that governments should mandate permanent subcutaneous microchip registration for all domestic dogs and cats and enforce strict fines on non-compliant pet owners.

The foremost benefit of mandatory microchipping is the rapid reunification of lost animals with their families and the reduction of euthanasia rates in animal shelters. Traditional collar tags frequently fall off, break, or become illegible when animals become lost or escape during storms. An inert, rice-sized subcutaneous microchip contains a unique identification code scannable by any veterinary clinic or municipal animal control officer. Immediately identifying the registered owner allows lost pets to be returned within hours, sparing families emotional distress and preventing overcrowding in public shelters. This system saves municipalities millions of dollars in animal sheltering expenditures and prevents the heartbreaking euthanasia of healthy, loved companion animals.

Equally important, mandatory microchip registration establishes legal accountability for pet abandonment and animal cruelty. Unscrupulous owners often abandon pets on roadsides when medical expenses rise or when they relocate, leaving animals to starve or reproduce uncontrollably. A universal microchip registry legally links every pet to a responsible owner, enabling authorities to prosecute abandonment and neglect. While opponents may argue that microchipping imposes costs on low-income pet owners, governments can easily sponsor free microchipping clinics in municipal parks, eliminating financial barriers.

In summary, mandatory pet microchipping protects animal welfare, promotes responsible pet guardianship, and eases burdens on municipal animal shelters. It represents an essential, humane standard for civilized societies.', 0, 1200, 15, 'medium', 'Support mandatory pet microchipping. Highlight rapid lost pet recovery and shelter euthanasia reduction in body 1, legal accountability for abandonment in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-015', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Cross-Border Scientific Collaboration and Peace', 'International scientific collaboration on global challenges such as climate change and disease does more to promote global peace than formal diplomatic treaties.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Maintaining international peace and security has historically been the domain of professional diplomats negotiating formal bilateral treaties and security pacts. However, I strongly agree with the statement that cross-border scientific collaboration plays a far more powerful and enduring role in fostering international peace and mutual understanding.

The primary reason scientific cooperation fosters deep peace is that science provides a shared, universal language rooted in empirical truth, rationality, and common human survival. When multinational teams of astronomers, climatologists, and virologists work together on collaborative endeavors—such as the International Space Station, global climate modeling, or vaccine development—they build profound relationships based on mutual respect and shared objectives that transcend geopolitical rivalries. During the height of the Cold War, joint biomedical research between American and Soviet scientists successfully eradicated smallpox, demonstrating that common scientific missions build bridges of trust even when political diplomacy is completely deadlocked. Science humanizes adversaries and establishes durable communication channels that resist political tensions.

In contrast, formal diplomatic treaties and political accords are often fragile, transactional, and vulnerable to unilateral abandonment whenever domestic political regimes change or nationalistic tensions flare. Treaties often manage symptoms of hostility through compromises, whereas scientific partnerships foster genuine cross-cultural friendship and collaborative problem-solving among intellectuals who influence public policy. Solving borderless planetary threats like pandemics and ecological collapse reminds nations of their shared vulnerability, rendering militaristic conflict increasingly irrational.

In conclusion, while diplomatic treaties are necessary legal frameworks, scientific collaboration builds the genuine human trust that underpins lasting peace. Empowering the global scientific community is one of humanity''s greatest investments in international stability.', 0, 1200, 15, 'medium', 'Argue that international scientific collaboration promotes peace better than diplomatic treaties. Discuss shared universal goals and Cold War smallpox cooperation in body 1, contrast with fragile political treaties in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-016', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Mandatory Soundproofing in Multi-Story Apartments', 'Building codes should legally require high-performance acoustic soundproofing between floors and walls in all multi-story residential apartment buildings.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'As global urbanization concentrates growing populations in high-density multi-story apartment complexes, acoustic noise transmission between adjacent units has become a widespread urban grievance. I firmly agree that municipal building regulations should legally mandate high-performance acoustic insulation standards between floors and adjoining walls in all new residential apartments.

The foremost justification for strict acoustic building standards is the protection of mental health, sleep quality, and domestic privacy. In poorly insulated apartment buildings, residents are continuously subjected to intrusive impact noise—such as footsteps, loud conversations, dropped objects, and television audio—from neighboring dwellings. Epidemiological research proves that persistent domestic noise intrusion triggers chronic stress, elevated blood pressure, sleep fragmentation, and severe psychological distress. Furthermore, unwanted acoustic invasion is the leading source of bitter interpersonal conflicts and litigation between apartment neighbors. Mandating floating floor assemblies, sound-dampening acoustic membranes, and resilient dry-wall channels effectively absorbs impact and airborne sound, transforming apartments into genuine sanctuaries of privacy and rest.

Real estate developers frequently lobby against acoustic mandates, contending that specialized soundproofing materials increase construction costs and reduce housing affordability during severe housing shortages. While incorporating acoustic insulation does add a minor fraction to initial building expenses, retrofitting soundproofing into an already constructed building is practically impossible and infinitely more expensive. Acoustic comfort is not an extravagant luxury; it is a fundamental health necessity for dignified urban living in dense cities.

In conclusion, acoustic privacy is vital for psychological well-being in dense urban communities. Enforcing mandatory soundproofing standards in building codes protects public health and fosters harmonious residential living.', 0, 1200, 15, 'medium', 'Support mandatory acoustic soundproofing in residential apartments. Detail sleep quality, stress reduction, and neighbor harmony in body 1, address developer construction cost claims in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-017', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Public Waterfront Walking Corridors', 'Urban planning authorities should mandate continuous, publicly accessible pedestrian corridors along all urban riverfronts and coastal shorelines.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Natural watercourses and coastal shorelines represent some of the most valuable natural assets within metropolitan regions. I strongly agree that municipal planning authorities should legally mandate continuous, unobstructed public pedestrian promenades along all urban rivers and waterfronts, preventing private developments from enclosing these shared spaces.

The primary justification for public waterfront access is public health and civic equity. Waterfront promenades provide uninterrupted, safe corridors where citizens of all ages and backgrounds can walk, jog, cycle, and relax away from dangerous vehicular traffic and exhaust fumes. Exposure to open water and natural light significantly reduces urban psychological stress and encourages physical activity, delivering substantial preventative healthcare benefits. When urban shorelines are privatized by exclusive luxury residential towers or corporate office complexes, the public is deprived of access to their natural geographical heritage, exacerbating spatial inequality within cities.

Property developers and private landowners often object that mandatory public corridors infringe upon private property rights and increase security liabilities for waterfront properties. They contend that private investment is essential to revitalize neglected post-industrial docks. However, integrating public promenades does not prevent private development; rather, cities that require open boardwalks and public plazas typically observe increased overall commercial foot traffic and elevated property valuations for adjacent businesses, demonstrating that civic openness and commercial vitality can flourish together.

In conclusion, urban shorelines are common civic assets that should serve the collective well-being of all inhabitants. Enforcing mandatory public waterfront pedestrian corridors creates healthier, more inclusive, and livable cities for future generations.', 0, 1200, 15, 'medium', 'Argue in favor of continuous public waterfront promenades. Discuss physical health and civic equity in body 1, address private property rights and commercial synergy in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-018', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Public Parks versus Indoor Sports Centers', 'Municipal councils with limited budgets should prioritize creating outdoor public parks rather than building specialized indoor sports facilities.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Municipal governments must make difficult fiscal choices when allocating recreational budgets for community health and well-being. When financial resources are constrained, I strongly agree that local councils should prioritize the creation and expansion of outdoor public parks over specialized indoor sports complexes.

The primary merit of outdoor public parks is their universal accessibility, demographic inclusivity, and low barrier to entry. Indoor sports centers typically require entrance fees, specialized athletic gear, and scheduled reservations, which effectively excludes economically disadvantaged families, the elderly, and casual visitors. In contrast, public parks are open free of charge to everyone, providing walking trails, tranquil green lawns, and outdoor fitness equipment that encourage daily cardiovascular exercise for all age groups. Furthermore, urban parks deliver vital ecological and psychological benefits that indoor gyms cannot provide. Abundant trees cool urban heat, filter air pollutants, and provide peaceful natural green spaces that significantly reduce stress and improve mental health across the community.

Supporters of indoor sports complexes point out that indoor facilities protect athletes from harsh weather conditions, such as winter cold or torrential monsoon rains, enabling year-round competitive sports training. While indoor athletics is valuable for dedicated athletes, municipal funds should prioritize the broad health of the entire population over specialized facilities that serve a narrow athletic demographic. Community parks can incorporate covered pavilions and weather-resistant paths to allow outdoor recreation even during inclement weather.

In summary, outdoor public parks provide democratic access to nature, physical exercise, and psychological restoration at minimal operational cost. Investing in green open spaces yields the highest return for community health and happiness.', 0, 1200, 15, 'medium', 'Support municipal investment in public parks over indoor sports centers. Detail universal access and ecological/mental health benefits in body 1, address inclement weather arguments in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-019', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Aesthetic Ornamentation versus Utilitarian Minimalism', 'Architectural design should prioritize aesthetic beauty and decorative ornamentation over purely functional, utilitarian minimalism.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'For over a century, modernist architecture has championed the doctrine that form must strictly follow function, resulting in landscapes dominated by austere concrete and glass boxes. I agree that architectural design should re-embrace aesthetic beauty, visual texture, and decorative craftsmanship rather than prioritizing sterile utilitarian minimalism.

The foremost justification for prioritizing aesthetic ornamentation is the profound psychological and emotional impact that beautiful surroundings exert on human well-being. Cognitive neuroscience and neuroaesthetics prove that visually rich environments featuring organic curves, varied textures, natural materials, and proportional symmetry stimulate feelings of pleasure, safety, and inspiration. Conversely, monotonous, unadorned concrete surfaces and repetitive steel facades induce feelings of alienation, visual fatigue, and civic indifference. Beautiful public buildings, such as ornate historic libraries, train terminals, and civic halls, instill profound civic pride and a sense of shared belonging that unadorned utilitarian structures can never inspire.

Proponents of utilitarian minimalism argue that functional design is more economical to construct, easier to maintain, and eliminates wasteful decorative excess. They maintain that the primary objective of a building is efficient utility and energy performance. However, human happiness and psychological flourishing are essential functional needs, not frivolous luxuries. Furthermore, buildings that are aesthetically cherished by communities are carefully maintained and preserved for centuries, whereas cheap, utilitarian minimalist structures are routinely demolished after a few decades, generating enormous environmental waste.

In conclusion, architecture is a public art form that shapes the human spirit. Prioritizing aesthetic beauty and thoughtful ornamentation enriches urban life, elevates human dignity, and creates timeless monuments that endure for generations.', 0, 1200, 15, 'medium', 'Argue for aesthetic ornamentation over utilitarian minimalism in architecture. Discuss neuroaesthetics, visual richness, and civic pride in body 1, refute cost claims with building longevity in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-020', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Subterranean Utility Tunnels in Metropolitan Infrastructure', 'Municipal governments should mandate and finance multi-utility subterranean tunnels for water, electricity, and telecommunications rather than burying cables directly in soil.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Modern urban streetscapes are plagued by perpetual road excavations, traffic detours, and utility pipe bursts caused by the traditional practice of burying utility lines directly underground. I strongly agree that metropolitan authorities should mandate and finance comprehensive subterranean multi-utility tunnels to house water, electrical, and fiber-optic networks.

The primary merit of consolidated utility tunnels is the dramatic reduction in urban road disruption, traffic congestion, and infrastructure maintenance costs. When electrical cables or water mains are buried directly beneath street asphalt, every minor repair or line upgrade requires tearing up roadways with jackhammers, causing suffocating traffic gridlock, commercial disruptions, and noise pollution for weeks. In contrast, walk-through subterranean utility tunnels allow technicians to inspect, repair, and upgrade utility conduits in a safe, dry, and climate-controlled environment without excavating a single square meter of roadway. Furthermore, housing utilities inside fortified concrete tunnels protects critical infrastructure from seismic ground displacement, water table corrosion, and accidental contractor digging damage, extending service life for generations.

Critics contend that constructing multi-utility tunnels requires enormous upfront capital expenditure that strains municipal budgets, especially compared to cheap direct burial in soil. While the initial capital investment is undeniably significant, lifecycle financial analyses demonstrate that utility tunnels pay for themselves within two decades by eliminating perpetual road repaving, reducing utility downtime, and preventing catastrophic water pipe blowouts that flood municipal streets.

In conclusion, repeatedly digging up city streets to access buried pipes is an inefficient, antiquated practice. Investing in subterranean utility tunnels modernizes urban infrastructure and ensures long-term civic efficiency.', 0, 1200, 15, 'medium', 'Support multi-utility subterranean tunnels. Discuss elimination of street excavation and infrastructure protection in body 1, address initial capital costs through lifecycle savings in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-021', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Integrating Agriculture into School Grounds', 'Primary schools should dedicate a portion of their school grounds to vegetable gardens and require students to cultivate crops as part of the curriculum.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'In an increasingly urbanized society, many children grow up completely alienated from the natural origins of the food they consume, believing it originates in plastic supermarket packaging. I strongly agree that primary schools should convert a portion of their grounds into functional vegetable gardens and require all pupils to participate in cultivating crops.

The foremost educational benefit of school agriculture is fostering an experiential understanding of biology, ecology, and nutritional science. Planting seeds, monitoring soil moisture, and observing plant photosynthesis transforms abstract textbook concepts into vivid real-world discoveries. Children learn first-hand about seasonal cycles, pollinator insects, and the vital role of soil microbiomes. Furthermore, research in pediatric nutrition consistently shows that children who grow their own vegetables develop a natural eagerness to eat fresh produce, helping dismantle unhealthy preferences for ultra-processed foods. Tending a garden cultivates patience, responsibility, and delayed gratification as pupils nurture plants through weeks of growth before enjoying the harvest.

Critics may contend that school schedules are already overcrowded with essential academic subjects like literacy and mathematics, and that managing gardens places an unreasonable burden on teachers. However, school gardening does not compete with academic learning; it enriches it. Mathematical fractions can be taught through seed spacing, and chemistry through soil pH testing. Moreover, local parent-teacher associations and community gardening clubs frequently volunteer to assist with garden maintenance, strengthening bonds between schools and local neighborhoods.

In conclusion, school gardens are dynamic outdoor classrooms that teach science, health, and environmental stewardship. Cultivating food grounds children in ecological reality and nurtures lifelong healthy living habits.', 0, 1200, 15, 'medium', 'Support integrating vegetable gardens into primary school curricula. Discuss hands-on biology and positive nutritional habits in body 1, address teacher workload and cross-disciplinary learning in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-022', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Prohibiting Non-Compete Clauses in Employment Contracts', 'Governments should legally prohibit commercial employers from enforcing non-compete clauses that restrict former employees from joining competing companies or starting rival businesses.

Do you agree or disagree with this statement? Support your point of view with reasons and examples from your own experience or observation. Write 200-300 words.', NULL, NULL, NULL, NULL, 'In modern corporate employment, companies routinely require new hires to sign restrictive covenants that prevent them from working for competitors or launching independent ventures after leaving their positions. I strongly agree that governments should ban the enforcement of non-compete agreements, as they unfairly suppress worker mobility and stifle economic innovation.

The primary justification for prohibiting non-compete clauses is the fundamental principle of employee freedom and career self-determination. Workers invest considerable personal effort into acquiring specialized skills and professional knowledge. Restricting an individual from applying their expertise within their chosen industry forces departed employees into prolonged career stagnation or compels them to relocate their households to earn a livelihood. Furthermore, extensive economic observations demonstrate that regions with strict bans on non-compete agreements exhibit significantly higher rates of entrepreneurial startups, robust patenting activity, and rapid technological advancement, because skilled talent flows freely to the most innovative enterprises.

Corporate employers argue that non-compete covenants are necessary to safeguard confidential trade secrets, specialized manufacturing techniques, and expensive investments in employee training. They assert that without legal protections, rival firms could poach senior personnel to steal proprietary formulas. While protecting intellectual property is a legitimate business concern, existing nondisclosure agreements and trade secret laws already provide comprehensive legal remedies against corporate espionage. Relying on blanket non-compete clauses merely allows established corporations to suppress fair competition and depress wage growth across their entire sector.

In summary, non-compete clauses serve primarily to restrict labor competition and hinder economic dynamism. Prohibiting these restrictive agreements protects the natural rights of workers and fosters a more competitive, innovative marketplace.', 0, 1200, 15, 'medium', 'Argue against non-compete clauses in employment contracts. Emphasize worker mobility and dynamic innovation ecosystems in body 1, evaluate employer trade secret protections and existing non-disclosure laws in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-023', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Compulsory Data Literacy for Undergraduates', 'All tertiary university students, regardless of their academic discipline, should be required to complete introductory coursework in data literacy and statistical interpretation.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'In modern information societies, quantitative data, machine algorithms, and statistical assertions permeate nearly every facet of civic and professional life. I strongly agree that all undergraduate university students should complete mandatory foundational coursework in data literacy and statistical interpretation, regardless of whether they major in humanities, arts, or natural sciences.

The primary justification for universal data education is fostering informed citizenship and critical analytical thinking. Everyday public discourse is saturated with political polls, economic claims, and medical news stories supported by quantitative charts and figures. Without a solid grasp of basic statistical concepts such as sample bias, statistical significance, and the fundamental distinction between correlation and causation, citizens are vulnerable to mathematical manipulation and misleading headlines. Teaching students how to evaluate quantitative claims critically empowers them to distinguish genuine empirical evidence from selective propaganda, which is indispensable for a healthy democratic society.

Critics often argue that mandating quantitative coursework places an unfair burden on humanities and arts students who chose non-mathematical fields. They suggest that introductory statistics can be intimidating and distracts students from specialized departmental curricula. However, modern data literacy does not require advanced calculus or dense theoretical mathematics; instead, it focuses on practical conceptual understanding, data visualization, and ethical interpretation. In an increasingly automated employment market, possessing data fluency enhances graduate employability across all professional sectors, from journalism to public administration.

In conclusion, data literacy is no longer a niche skill reserved for scientists and economists. Making data interpretation a universal university requirement prepares graduates to navigate a complex, quantitative world thoughtfully and competently.', 0, 1200, 15, 'medium', 'Argue in favor of mandatory data literacy for all undergraduates. Focus on informed citizenship and statistical skepticism in body 1, address math anxiety and career versatility in body 2, and summarize.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-024', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Expatriate Residence and Cultural Identity', 'Living and working in a foreign country for many years inevitably weakens an individual''s connection to their native culture and heritage.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'The globalization of the modern economy has enabled millions of professionals and emigrants to reside outside their countries of origin for extended decades. While long-term expatriate life certainly introduces cross-cultural influences, I disagree with the view that prolonged foreign residence inevitably weakens an individual''s bond with their native culture.

On the contrary, living abroad often deepens and crystallizes an individual''s appreciation for their cultural heritage. When people reside in their home country, their cultural traditions, language, and rituals are often taken for granted as ordinary background realities. However, when immersed in a foreign society with contrasting social norms and values, expatriates become acutely conscious of their unique cultural identity. This heightened self-awareness frequently inspires individuals to actively practice their native customs, cook traditional cuisines, celebrate ethnic festivals, and teach their mother tongue to their children with deliberate devotion. Distance provides perspective, transforming passive inheritance into active, proud cultural preservation.

Furthermore, contemporary digital telecommunications and global transportation networks make cultural isolation a thing of the past. Expatriates today can read native news portals daily, converse with family overseas via video calls, and participate in vibrant expatriate community organizations that maintain authentic cultural ties. While expatriates certainly acquire host-country linguistic habits and international perspectives, incorporating new habits does not erase original roots; rather, it produces a rich bicultural identity where individuals cherish their heritage while navigating global environments.

In conclusion, living abroad does not inevitably erode native cultural connection. For many, foreign residence strengthens cultural pride and fosters an enduring, reflective commitment to their heritage.', 0, 1200, 15, 'medium', 'Disagree with the claim that living abroad weakens cultural identity. Argue that distance fosters conscious cultural appreciation in body 1, highlight digital connectivity and bicultural identity in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-025', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Algorithmic Screening in Corporate Recruitment', 'Companies should be legally prohibited from using automated artificial intelligence software to screen and reject job applicants'' resumes.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Large corporations increasingly deploy automated artificial intelligence algorithms to scan thousands of incoming job applications, automatically filtering out the vast majority of resumes before any human recruiter reviews them. I firmly agree that governments should strictly regulate or prohibit the use of automated algorithms to reject job applicants without human oversight.

The foremost argument against algorithmic applicant screening is the perpetuation of systemic bias and algorithmic unfairness. Machine learning recruitment models are trained on historical employment datasets. Because past hiring in prestigious corporate and technological sectors historically favored specific demographic groups, algorithms inherit and amplify these biases. Resume screening tools have been demonstrated to penalize female applicants, downgrade candidates from non-elite universities, and reject applicants with non-traditional career paths, even when they possess exceptional competence. Furthermore, automated keyword-matching algorithms reward applicants who game the system with buzzwords while filtering out genuine creative thinkers whose resumes use original phrasing.

Corporate human resources departments defend algorithmic screening as an indispensable tool for managing overwhelming volumes of applications for single job postings. They argue that human recruiters cannot manually evaluate thousands of resumes efficiently. While automation can assist with logistical sorting, allowing software to execute autonomous rejection decisions denies candidates human dignity and fair consideration. If companies lack the capacity to review applicants fairly, they should refine job qualifications rather than deploying opaque automated filters.

In conclusion, automated algorithmic screening encodes historic discrimination and undermines meritocracy in the labor market. Prohibiting fully automated rejection ensures that employment opportunities are evaluated with human fairness and empathy.', 0, 1200, 15, 'medium', 'Argue against automated algorithmic resume screening. Detail historical bias replication and keyword gaming in body 1, address corporate volume efficiency arguments in body 2, and conclude with human dignity.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-026', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Small Independent Colleges versus Massive Universities', 'Attending a small college with small class sizes provides a superior undergraduate education compared to attending a large research university.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Prospective undergraduate students frequently weigh the intimate learning environment of small liberal arts colleges against the vast resources of massive research universities. I firmly agree that small colleges offer a significantly superior undergraduate educational experience.

The foremost advantage of small colleges is intimate class sizes that foster direct pedagogical mentorship between professors and students. In massive research universities, introductory lectures often pack hundreds of students into impersonal auditoriums, with coursework graded by overworked graduate teaching assistants while tenure-track professors focus primarily on laboratory research. In small collegiate institutions, all courses are taught directly by faculty members who know students by name. This close interaction fosters lively seminar debates, encourages intellectual curiosity, and enables professors to provide tailored academic feedback. Furthermore, undergraduates at small colleges enjoy direct access to laboratory research equipment and faculty-guided independent study projects that are monopolized by postgraduate doctoral candidates at larger institutions.

Proponents of large research universities argue that mega-institutions offer broader course selections, state-of-the-art specialized research facilities, and sprawling alumni networks. While mega-universities certainly possess extensive facilities, undergraduate students rarely access elite multi-million-dollar laboratories during their foundational study. What truly shapes undergraduate intellectual development is not the size of a university''s endowment, but the quality of everyday classroom engagement and intellectual mentorship.

In conclusion, while large universities excel in postgraduate research, small colleges provide the ideal environment for undergraduate flourishing. Personalized mentorship and active seminar learning make small colleges the premier choice for undergraduate education.', 0, 1200, 15, 'medium', 'Argue that small colleges provide a better undergraduate education than large universities. Focus on professor mentorship and seminar interaction in body 1, evaluate mega-university facility claims in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-027', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Regulating Video Game Microtransactions and Loot Boxes', 'Governments should classify in-game loot boxes and microtransactions in video games as forms of gambling and ban them in games accessible to minors.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'The commercial monetization of video games has increasingly transitioned from single upfront purchases to microtransactions featuring randomized virtual reward containers known as loot boxes. I strongly agree that regulatory authorities should legally classify randomized loot boxes as gambling and ban them from games played by children.

The central argument for prohibiting loot boxes is that their core mechanics are functionally identical to casino slot machines. Players wager real money to purchase randomized containers with variable payout probabilities, hoping to unlock rare digital items. Game developers deliberately employ psychological operant conditioning techniques—such as flashing audiovisual celebrations, artificial scarcity, and variable reward schedules—to trigger intense dopamine spikes and exploit immature adolescent impulse control. Behavioral addiction researchers have consistently found that excessive loot box spending in adolescence is strongly correlated with problem gambling in adulthood. Exposing children to predatory gambling mechanics under the guise of interactive entertainment is socially irresponsible and psychologically harmful.

The video game industry argues that loot boxes are merely optional virtual surprises akin to physical collectible trading card packs, claiming that microtransactions finance ongoing game updates without raising base game prices. However, digital loot boxes are far more addictive than physical card packs due to instantaneous repetition, frictionless in-app purchasing, and persuasive algorithmic design that tracks player spending patterns. Game studios can easily adopt transparent commercial models, such as direct item purchases or subscription passes, without exploiting vulnerable youth.

In summary, randomized loot boxes exploit children''s neurological vulnerability for corporate profit. Classifying loot boxes as gambling and banning them in youth video games is an urgent public child-protection measure.', 0, 1200, 15, 'medium', 'Support banning in-game loot boxes for minors as gambling. Explain operant conditioning and addiction parallels in body 1, address trading card comparisons and industry revenue models in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-028', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Standardized Testing in University Admissions', 'Universities should abolish standardized entrance examinations and evaluate applicants based entirely on continuous high school transcripts and portfolios.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Standardized entrance examinations have long served as the primary filter for university admissions across many countries. However, I firmly agree that higher education institutions should eliminate standardized tests in favor of holistic evaluations based on multi-year high school academic transcripts and personal portfolios.

The primary justification for abolishing standardized exams is that a single multi-hour test cannot accurately measure intellectual potential, creativity, or long-term academic stamina. Standardized tests primarily reward rote memorization, rapid multiple-choice test-taking tricks, and financial privilege. Wealthy families spend thousands of dollars on private test-preparation tutors and coaching academies, artificially inflating scores and transforming admissions into a competition of family wealth rather than merit. In contrast, multi-year high school transcripts reflect consistent diligence, daily work ethic, classroom participation, and resilience across diverse subjects over several years. Assessing personal project portfolios, research essays, and extracurricular contributions reveals authentic intellectual curiosity that standardized scores conceal.

Defenders of standardized testing argue that tests provide an objective, uniform metric that allows admissions officers to compare students from thousands of secondary schools with vastly divergent grading standards. They fear that eliminating tests will lead to grade inflation and subjective bias. While high school grading standards do vary, admissions committees can normalize transcripts by evaluating an applicant''s performance relative to their specific school environment. Universities that transitioned to test-optional policies recorded increased student diversity without any decline in subsequent undergraduate academic success.

In conclusion, standardized tests reinforce socioeconomic inequality while failing to capture true scholarly potential. Adopting holistic transcript and portfolio evaluations creates a fairer, more accurate university admissions system.', 0, 1200, 15, 'medium', 'Argue for abolishing standardized university entrance exams. Highlight socioeconomic coaching bias and the superiority of multi-year transcripts in body 1, tackle objective comparison arguments in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-029', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Mandated Paid Educational Leave for Workers', 'Governments should legally require employers to grant mid-career employees several months of paid leave to pursue continuing educational credentials.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'In an era where technological innovation and artificial intelligence rapidly render professional skill sets obsolete, lifelong learning has become an economic imperative. I strongly agree that governments should mandate paid educational sabbaticals, requiring employers to grant mid-career workers protected leave to upgrade their skills and qualifications.

The primary justification for statutory educational leave is preventing structural unemployment and accelerating technological adaptation across the workforce. Mid-career professionals often find their existing competencies overtaken by new digital tools, renewable energy technologies, or automated systems. However, working adults with mortgages and childcare obligations cannot afford to quit their jobs to retrain full-time. Providing several months of subsidized educational leave enables experienced workers to master advanced data analytics, engineering techniques, or management disciplines without sacrificing financial survival. Companies directly benefit from returning employees who bring refreshed technical competencies, innovative perspectives, and updated industry knowledge that boost corporate productivity.

Business employer confederations often resist mandatory educational sabbaticals, claiming that covering paid leave and finding temporary replacement staff imposes prohibitive costs, especially on small enterprises. While workforce planning is required, governments can establish national training co-funding schemes financed by modest joint contributions from employers and the state. Countries that implemented statutory educational leave, such as several northern European nations, demonstrate that a continuously retrained workforce drives high-value innovation, low long-term unemployment, and elevated national economic competitiveness.

In conclusion, paid educational leave is a vital strategic investment in human capital. Mandating continuous learning opportunities ensures that workers and national economies remain resilient in the face of ongoing technological disruption.', 0, 1200, 15, 'medium', 'Support mandatory paid educational sabbaticals for mid-career workers. Detail prevention of technological obsolescence and company benefits in body 1, address employer costs with national co-funding in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-030', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Traffic Free Zones Around Primary Schools', 'Local authorities should prohibit all private motor vehicles within the immediate perimeter of primary schools during morning arrival and afternoon dismissal hours.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'The daily school run outside primary schools is frequently characterized by traffic congestion, double parking, and chaotic vehicle maneuvers, endangering young pedestrians and polluting neighborhood air. I strongly agree that local municipal authorities should establish mandatory car-free zones around primary school gates during peak drop-off and collection times.

The foremost justification for temporary vehicular closures is child road safety and clean air. Children possess limited spatial awareness and lower peripheral vision, making them exceptionally vulnerable to reversing vehicles and impatient drivers navigating congested school streets. Eliminating private cars during school arrival hours virtually eliminates the risk of catastrophic pedestrian collisions. Furthermore, idling internal combustion engines emit concentrated plumes of toxic nitrogen dioxide and particulate matter directly at children''s breathing height. Removing traffic outside schools significantly improves localized air quality, protecting young lungs from developing asthma and respiratory ailments.

Some parents and local businesses object that car-free perimeters cause inconvenience for working families commuting on tight schedules or displace parking problems to neighboring streets. While logistical adjustments are required, schools and municipalities can designate park-and-stride locations a short walking distance away, allowing parents to drop children off safely while encouraging daily physical exercise. Exemptions can easily be granted for students with physical disabilities or emergency medical vehicles, ensuring accessibility for all children.

In conclusion, convenience for motorists must never outweigh the physical safety and respiratory health of young children. Implementing temporary car-free school streets creates safe, tranquil environments that promote walking, community interaction, and child well-being.', 0, 1200, 15, 'medium', 'Support car-free zones around primary schools during drop-off and pick-up hours. Highlight road safety and clean air in body 1, address parental commuting inconvenience and accessibility in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-031', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Academic Ability Streaming in Secondary Schools', 'Secondary schools should group students into separate classrooms based on their academic ability rather than teaching mixed-ability classes.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'How schools organize secondary classrooms has a profound impact on educational outcomes and student engagement. While mixed-ability teaching is often promoted on egalitarian grounds, I strongly agree that streaming secondary school students into separate classes based on academic ability produces far superior learning environments.

The primary pedagogical benefit of ability-based streaming is that it allows teachers to customize instructional pace, curriculum depth, and teaching methods to match students'' precise cognitive levels. In a mixed-ability classroom, educators face an impossible dilemma: teaching to the middle leaves high-achieving students bored and under-stimulated, while struggling students fall hopelessly behind and experience anxiety. In streamed classrooms, advanced learners can tackle complex, accelerated coursework that challenges their intellect, while students requiring foundational reinforcement receive patient, targeted instruction without feeling embarrassed in front of faster peers. Tailoring educational pacing prevents classroom disengagement and maximizes individual academic potential across all achievement tiers.

Opponents of streaming argue that separating students stigmatizes lower-tier classrooms, diminishes self-esteem, and widens socioeconomic achievement gaps. They fear that students placed in lower streams develop self-fulfilling negative expectations. However, schools can mitigate stigma by making streaming flexible and subject-specific; a student who struggles in advanced mathematics may excel in advanced literature. Regular evaluations should allow students to move between streams as their skills develop, ensuring that streaming functions as a supportive ladder rather than a permanent label.

In summary, ability streaming respects the reality of diverse learning speeds. Providing customized instruction allows all students—both advanced and struggling—to achieve their fullest educational potential.', 0, 1200, 15, 'medium', 'Support academic ability streaming in secondary schools. Explain customized instructional pacing for both advanced and struggling learners in body 1, address stigmatization with flexible subject-specific streaming in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-032', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Restricting Mass Tourism in Historical Enclaves', 'Historic ancient cities should impose strict daily visitor quotas and tourist taxes to prevent overtourism from destroying local cultural heritage.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'The rapid growth of global budget tourism and digital travel platforms has brought millions of visitors into fragile historical towns, from Venice to ancient Kyoto. I strongly agree that historic enclaves should implement enforceable daily visitor quotas and tourist taxes to prevent overtourism from destroying irreplaceable cultural heritage.

The foremost argument for visitor restrictions is the physical preservation of fragile ancient architecture and infrastructure. Medieval stone bridges, ancient cobblestones, and delicate historic monuments were never designed to withstand the foot traffic of tens of thousands of daily tourists. Overcrowding accelerates physical erosion, degrades historic fabric, and generates overwhelming volumes of litter and waste that strain municipal services. Furthermore, unchecked tourism hollows out authentic community life; traditional bakeries and artisan workshops are converted into tacky souvenir shops, while residential housing is converted into short-term tourist rentals, driving local families out and turning living communities into lifeless theme parks.

Commercial tourism operators frequently object to visitor caps, arguing that restrictions harm local economic revenue, limit freedom of movement, and reduce hospitality employment. However, unregulated overtourism is economically self-destructive; when a historic city becomes hopelessly congested and loses its authentic charm, affluent cultural tourists stop visiting. Implementing pre-booked entry reservations and dedicated tourist taxes ensures that tourism remains sustainable, with tax proceeds directly funding the expensive restoration of historic monuments and public infrastructure.

In conclusion, preserving the physical and cultural authenticity of historic cities is a sacred responsibility. Enforcing strict visitor caps protects cultural heritage and ensures that ancient treasures endure for future generations.', 0, 1200, 15, 'medium', 'Support visitor quotas and tourist taxes in historic towns. Discuss physical erosion and community displacement in body 1, refute economic objections by highlighting sustainable tourism economics in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-033', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Healthcare Allocations for Disease Prevention', 'National healthcare systems should allocate the majority of their budgets to preventative wellness programs rather than expensive hospital-based curative treatments.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Contemporary healthcare expenditures worldwide are overwhelmingly absorbed by advanced hospital treatments, emergency surgical procedures, and lifelong pharmaceutical management for chronic illnesses. I strongly agree that national health systems should reorient their fiscal priorities and allocate the majority of public health funding to preventative wellness initiatives.

The foremost justification for prioritizing preventative healthcare is that the overwhelming majority of modern disease burdens—including cardiovascular disease, type-two diabetes, hypertension, and certain cancers—are largely preventable through lifestyle and environmental interventions. Funding early health screenings, comprehensive public nutritional education, subsidized access to fresh produce, and municipal exercise infrastructure prevents chronic pathologies before irreversible organ damage occurs. Treating end-stage heart disease or kidney failure requires hundreds of thousands of dollars in hospital surgery and continuous dialysis per patient, whereas promoting active living and healthy diets costs a fraction of that expenditure while preserving decades of healthy, productive human life.

Critics often argue that diverting healthcare funds from acute hospital care could endanger current patients suffering from catastrophic trauma, infectious diseases, and genetic conditions that prevention cannot resolve. They contend that hospitals require state-of-the-art diagnostic machinery and intensive care capacity. While acute emergency services must remain fully functional, preventative investment dramatically reduces the inflow of preventable chronic patients into hospitals. Over time, prevention empties hospital beds and shortens emergency wait times, allowing curative institutions to care for acute emergency cases far more effectively.

In conclusion, an ounce of prevention is truly worth a pound of cure. Prioritizing preventative wellness transforms sick-care systems into genuine healthcare systems that maximize societal vitality.', 0, 1200, 15, 'medium', 'Argue for allocating majority healthcare budgets to prevention over acute hospital care. Detail chronic disease prevention and long-term cost savings in body 1, address acute care requirements in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-034', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Phasing Out Heavy Bunker Fuel in Commercial Maritime Transport', 'Governments should prohibit commercial shipping vessels from using unrefined heavy bunker fuel and mandate cleaner marine distillate fuels worldwide.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'The international merchant shipping fleet powers global commerce, but it operates predominantly on heavy bunker fuel—the tar-like, bottom-of-the-barrel residue left over after crude oil refining. I strongly support the global prohibition of heavy bunker fuel and the mandatory adoption of cleaner refined marine distillate fuels across all commercial shipping.

The foremost justification for banning heavy bunker fuel is the catastrophic environmental and human health toll caused by its toxic combustion emissions. Heavy bunker oil contains high concentrations of sulfur, heavy metals, and polycyclic aromatic hydrocarbons. When burned in giant marine engines, it emits millions of tons of sulfur dioxide, nitrogen oxides, and toxic black carbon soot into the atmosphere. In polar and arctic shipping routes, black carbon deposits onto sea ice and glaciers, accelerating ice melt by reducing solar reflectivity. Furthermore, marine air pollution drifting over coastal populations causes tens of thousands of respiratory and cardiovascular deaths annually. Mandating low-sulfur distillate fuels or liquefied gas instantly slashes toxic sulfur and particulate soot emissions dramatically, delivering immediate public health and environmental benefits.

Shipping conglomerates resist fuel bans, warning that refined distillate fuels are substantially more expensive than bunker residue, which will increase global maritime freight transport rates and commodity prices. While refined fuels are costlier, the global shipping industry should not base its profitability on poisoning the global atmosphere. The modest increase in consumer shipping rates—amounting to pennies on consumer electronics or footwear—is a negligible price to pay for clean air and climate protection.

In summary, heavy bunker fuel is the dirtiest fossil fuel in commercial use today. Banning heavy bunker fuel is an urgent, necessary measure to protect marine ecology and human health.', 0, 1200, 15, 'medium', 'Support banning heavy bunker fuel in commercial shipping. Highlight toxic sulfur/soot emissions, Arctic ice melt, and respiratory disease in body 1, refute freight cost objections in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-035', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Consumer Boycotts of Low-Wage Manufacturers', 'Consumers in developed nations should actively boycott multinational brands that manufacture clothing and goods in developing countries with low wages.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'The globalization of consumer manufacturing has enabled multinational corporations to produce affordable apparel and electronics by establishing factories in developing nations with minimal wage standards. While consumers are often urged to boycott these brands, I disagree with widespread consumer boycotts, as blanket boycotts often cause severe economic harm to the very workers they intend to help.

The primary argument against blanket boycotts is that manufacturing employment in developing nations, despite low compensation by Western standards, often represents the best available livelihood for local workers. In many impoverished agricultural regions, alternative livelihoods consist of grueling subsistence farming, informal domestic servitude, or dangerous informal labor with no legal protections. Factory employment provides steady, formal income that allows families to educate their children, secure nutrition, and climb out of rural poverty. When foreign boycotts force Western brands to cancel factory contracts, factories abruptly shut down, leaving millions of vulnerable workers—disproportionately young women—without income and pushing them into destitution or exploitation.

Instead of blunt boycotts that destroy local livelihoods, conscientious consumers and governments should advocate for constructive ethical engagement and binding international labor standards. Western consumers should pressure brands to pay a living wage, enforce workplace safety regulations, and permit independent worker unions. Trade policies should tie market access to verifiable labor improvements. Constructive engagement improves factory conditions while preserving the vital industrial employment that developing economies require to modernize.

In conclusion, while exploitative working conditions must be eradicated, blanket consumer boycotts harm vulnerable workers. Supporting fair labor standards and targeted accountability delivers humane progress without destroying essential employment.', 0, 1200, 15, 'medium', 'Argue against blanket consumer boycotts of low-wage manufacturing. Explain that factory jobs are vital lifelines out of poverty in body 1, advocate constructive engagement and labor standards over boycotts in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-036', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'High-Interest Credit Cards and Youth Vulnerability', 'Financial institutions should be legally prohibited from issuing high-interest revolving credit cards to young adults under twenty-five.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'The aggressive marketing of high-interest revolving credit cards to college students and young adults has led to soaring levels of youth consumer debt. I firmly agree that financial regulators should prohibit banks from issuing high-interest credit cards to individuals under the age of twenty-five to protect youth financial stability.

The foremost justification for restricting credit card access is the severe vulnerability of young adults to predatory debt accumulation. The human prefrontal cortex, which governs long-term risk assessment and impulse regulation, continues developing into the mid-twenties. Young adults navigating early independence often lack financial experience and realistic income forecasts, making them vulnerable to deceptive marketing and compound interest traps. Accumulating thousands of dollars in high-interest debt early in life severely damages credit scores, impairs mental health, and prevents young people from saving for homeownership or continuing education. Restricting revolving credit protects young citizens during their most financially vulnerable formative years.

Financial institutions argue that credit cards provide essential financial liquidity for emergencies and allow young adults to build credit histories necessary for future mortgage applications. While learning credit management is useful, building credit does not require high-interest revolving debt with exorbitant, predatory interest rates. Young adults can safely build credit through low-limit secured cards, debit cards with overdraft protection, or subsidized student loans that feature fixed low rates and clear repayment timelines.

In conclusion, allowing financial corporations to profit from inexperienced young borrowers is predatory and economically damaging. Restricting high-interest credit cards for young adults under twenty-five shields youth from unmanageable debt and fosters responsible financial independence.', 0, 1200, 15, 'medium', 'Support restricting high-interest credit cards for young adults under 25. Discuss neurobiology, impulse control, and debt traps in body 1, evaluate credit-building arguments and secured card alternatives in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-037', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Funding University Degrees with Low Market Demand', 'State governments should cease providing public tuition subsidies for university degree programs that exhibit low employment demand in the national economy.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'With public budgets constrained and national economies demanding specialized technical skills, higher education funding faces intense political scrutiny. While aligning education with workforce needs is important, I disagree with the proposal that state governments should eliminate tuition subsidies for degree programs with low labor market demand.

The primary argument for sustaining public funding across all academic disciplines is that the value of higher education extends far beyond narrow vocational training. Degrees in philosophy, history, theoretical mathematics, literature, and art cultivate critical inquiry, ethical discernment, cultural preservation, and civic wisdom. These intellectual pursuits are essential for the cultural flourishing and democratic vitality of a civilized nation. If universities fund solely commercially lucrative fields like computer science and business finance, human society loses the thinkers, historians, and ethicists who interpret human culture and hold institutions accountable. Furthermore, labor market demands are notoriously volatile; skills in high demand today may be automated tomorrow, whereas foundational analytical and communicative competencies never become obsolete.

Fiscal conservatives contend that taxpayers should not subsidize degrees that lead to underemployment and graduate debt defaults, arguing that students should bear the financial risk of pursuing low-demand subjects. However, if subsidies are eliminated, humanities and arts education will become the exclusive luxury of wealthy elites, shutting out talented students from lower-income backgrounds. Public subsidies democratize access to knowledge, ensuring that cultural leadership reflects all socioeconomic strata.

In conclusion, higher education is not merely a job training center; it is a repository of human civilization. Continuing to subsidize low-market-demand disciplines preserves cultural depth and democratic intellectual diversity.', 0, 1200, 15, 'medium', 'Disagree with defunding low-market-demand university degrees. Highlight intrinsic cultural value and democratic discernment in body 1, address taxpayer burden and educational elitism in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-038', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Artificial Intelligence in Creative Literary Writing', 'Generative artificial intelligence tools can never replace human authors in creating deeply meaningful literature and poetry.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'The rapid advancement of large language models has demonstrated remarkable capability in generating coherent essays, stories, and rhyming verse in seconds. Despite these impressive technical feats, I firmly agree with the proposition that artificial intelligence can never truly replace human authors in producing genuinely profound literature and poetry.

The fundamental reason artificial intelligence cannot replace human writers is that profound literature is an expression of lived human consciousness, mortality, and emotional vulnerability. Great literature does not merely arrange words in syntactically pleasing sequences; it arises from raw human experiences: the agony of grief, the ecstasy of love, the struggle with moral guilt, and the acute awareness of finite mortality. An artificial intelligence has no body, experiences no sorrow or joy, and possesses no genuine consciousness; it merely predicts the most statistically probable next word based on patterns in historical text. Consequently, machine-generated prose is inherently derivative, devoid of authentic subjective intent, genuine suffering, or moral soul. Readers connect with literature because they recognize a fellow human consciousness speaking across time.

Enthusiasts of machine learning argue that as algorithms grow more sophisticated, readers will be unable to distinguish AI-generated novels from human works, pointing to blind reading tests. While algorithms can certainly mimic literary styles and produce entertaining commercial genre fiction, mimicry is not authentic creation. Literature is an act of authentic existential testimony, not a statistical parlor trick.

In conclusion, while artificial intelligence can serve as a useful editing tool, the soul of literature belongs irrevocably to human experience. Human authorship will always remain irreplaceable in genuine creative art.', 0, 1200, 15, 'medium', 'Argue that AI cannot replace human authors in profound literature. Detail human mortality, consciousness, and emotional vulnerability in body 1, distinguish statistical mimicry from authentic testimony in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-039', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Restricting Heavy Freight Vehicles on Residential Streets', 'Municipal authorities should prohibit heavy commercial freight vehicles from using residential streets, requiring them to use designated orbital bypass roads instead.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'The growth of commercial logistics and freight transport has led many heavy articulated trucks to use narrow residential streets as convenient shortcuts to bypass highway congestion. I firmly agree that municipal authorities should prohibit heavy commercial freight vehicles from traversing residential neighborhoods, mandating that logistics traffic remain strictly on designated arterial corridors and orbital bypasses.

The primary argument for restricting heavy freight is safeguarding residential safety and public infrastructure. Multi-ton commercial trucks pose immense physical hazards to neighborhood pedestrians, cyclists, and playing children, with blind spots making turns on tight residential corners particularly dangerous. Furthermore, the massive axle loads of commercial trucks cause severe structural vibrations that crack residential foundations and rapidly deteriorate asphalt pavements designed only for light domestic traffic. Banning heavy freight eliminates ground-shaking acoustic disruption, preserves municipal road maintenance budgets, and drastically improves quality of life for local residents.

Freight transport operators often contend that restricting residential cut-throughs increases travel distances, extends delivery schedules, and raises transportation fuel costs. They argue that commercial freight delivers essential consumer goods that sustain local economies. While arterial detours may add minor travel time, heavy logistics fleets are better suited for wide multi-lane ring roads engineered for high tonnage and steady speeds. For essential local deliveries within neighborhoods, regulations can permit smaller electric delivery vans, ensuring commercial access without subjecting neighborhoods to heavy industrial vehicles.

In conclusion, residential streets are community spaces meant for homes, schools, and families, not heavy logistics thoroughfares. Restricting heavy commercial freight to designated bypasses protects community safety, infrastructure, and peace.', 0, 1200, 15, 'medium', 'Argue in favor of prohibiting heavy commercial freight on residential streets. Emphasize pedestrian safety, road damage, and noise in body 1, address logistics efficiency and local deliveries in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-040', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Formal Instruction in Emotional Resilience', 'Primary and secondary schools should include structured classroom instruction in emotional resilience and coping mechanisms as a formal part of the curriculum.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Adolescent mental health crises, characterized by rising rates of clinical anxiety, depression, and social alienation, have escalated dramatically worldwide. I firmly agree that schools should incorporate formal, structured classroom instruction in emotional resilience, stress management, and psychological coping mechanisms into the standard curriculum.

The primary justification for formal resilience education is equipping young people with psychological self-regulation tools before acute crises occur. Traditional schooling trains students academically in mathematics and science, but leaves them emotionally illiterate, with no formal training on how to process failure, manage social rejection, or navigate intense grief and academic stress. Teaching evidence-based cognitive behavioral strategies, emotional mindfulness, and constructive conflict resolution empowers students to recognize irrational thought patterns and de-escalate anxiety. Schools that implemented structured social-emotional learning programs observed significant reductions in classroom behavioral disruptions, diminished bullying rates, and measurable improvements in academic test scores.

Traditionalists often argue that emotional development should remain the private responsibility of parents and that schools should focus exclusively on academic rigor. However, many parents lack the psychological knowledge or emotional bandwidth to teach structured coping techniques, especially in families facing socioeconomic adversity. Schools teach physical health and hygiene to prevent physical illness; teaching emotional hygiene to prevent psychological breakdown is an equally vital public duty.

In conclusion, emotional resilience is a foundational life skill that underpins all academic and personal achievement. Integrating resilience instruction into school curricula creates mentally healthy, adaptable citizens capable of thriving in a demanding world.', 0, 1200, 15, 'medium', 'Support mandatory emotional resilience instruction in schools. Highlight proactive mental health tools and cognitive-behavioral strategies in body 1, refute parental exclusivity arguments in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-041', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Employee Access to Workplace Evaluation Records', 'Workers should have an absolute legal right to inspect all internal performance evaluations and managerial notes collected about them by their employers.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'In many modern corporate workplaces, employee career trajectories, promotions, and terminations are determined through opaque annual evaluations and confidential managerial notes. I strongly agree that legislation should grant workers an unconditional legal right to inspect all internal performance evaluations, ratings, and documentation compiled about them.

The foremost argument for transparent performance records is ensuring procedural fairness, accountability, and preventing unlawful discrimination. When performance reviews remain confidential, unscrupulous managers can weaponize evaluations to penalize whistleblowers, discriminate against minority employees, or justify wrongful terminations under the guise of poor performance. Granting employees full access to review their files ensures transparency, allowing workers to identify inaccurate factual claims, contest unfair assessments, and present counter-evidence. Furthermore, open feedback is essential for genuine professional development; employees cannot correct weaknesses or improve productivity if they are kept ignorant of managerial criticisms.

Employer organizations often resist transparency, arguing that managerial candor will be suppressed if supervisors know employees can read their notes, leading to bland, unhelpful reviews. They also fear an explosion of workplace conflict and litigation. However, professional managers should be fully prepared to substantiate their evaluations with objective evidence and professional reasoning. Opaque secrecy breeds paranoia and toxic workplace culture; transparent documentation fosters mutual accountability, professional trust, and constructive collaboration.

In conclusion, workplace transparency is a fundamental pillar of worker rights. Granting employees full access to their evaluation records eliminates arbitrary managerial bias and creates fair, merit-based working environments.', 0, 1200, 15, 'medium', 'Support legal rights for workers to view internal performance evaluations. Emphasize fairness, non-discrimination, and productive feedback in body 1, address managerial candor fears in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-042', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Public Funding for Planetary Asteroid Defense and Monitoring', 'National governments should allocate dedicated annual defense budgets to planetary asteroid detection, deflection, and monitoring systems.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'While national defense budgets worldwide consume trillions of dollars preparing for geopolitical conflict between nations, humanity faces an existential cosmic threat from near-Earth asteroids. I strongly agree that governments should allocate a dedicated share of national defense expenditure to fund planetary asteroid detection, tracking, and kinetic deflection systems.

The primary justification for planetary defense investment is the catastrophic, civilizational scale of asteroid impact hazards. Earth''s geological history demonstrates that asteroid collisions have repeatedly caused mass extinction events, wiping out entire ecosystems in minutes. Today, thousands of massive near-Earth asteroids remain undetected by ground telescopes. Even an asteroid a few hundred meters wide could completely incinerate an entire metropolitan region or trigger mega-tsunamis that devastate continental coastlines, killing millions and collapsing the global economy. Crucially, unlike earthquakes or volcanic eruptions, asteroid impacts are the only natural disaster that modern humanity has the technological capacity to predict decades in advance and actively prevent through kinetic impactor spacecraft or gravitational tractors.

Skeptics argue that the statistical probability of a catastrophic asteroid impact in any single century is exceptionally low, making multi-billion-dollar defense expenditures an inefficient use of public funds compared to addressing immediate terrestrial challenges like disease or poverty. However, while the probability is low, the consequences are absolute and irreversible: human extinction. Allocating a modest fraction of existing military spending—which is often squandered on redundant weaponry—to planetary defense represents prudent, rational cosmic insurance for all human civilization.

In conclusion, protecting our planet from cosmic extinction is the ultimate defense mission. Dedicated funding for asteroid detection and deflection systems ensures the permanent survival of the human species.', 0, 1200, 15, 'medium', 'Support dedicated public defense funding for asteroid detection and deflection. Detail existential impact risks and preventative deflection technology in body 1, address low statistical probability vs infinite consequence in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-043', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Banning Billboards Along Scenic Corridors', 'Governments should completely ban commercial billboards and digital advertising screens along all national highways and scenic corridors.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Modern highways and rural corridors are increasingly cluttered with towering commercial billboards and blinding digital light-emitting diode advertising displays. I strongly agree that governments should completely outlaw commercial advertising billboards along all national highway systems and scenic rural landscapes.

The primary justification for a billboard ban is public road safety and the prevention of catastrophic traffic collisions. Billboards are explicitly engineered by advertising psychologists to seize motorists'' visual attention away from the road using provocative imagery, glowing animations, and bright flashing text. At highway speeds of one hundred kilometers per hour, a driver glancing at an electronic billboard for just two seconds travels fifty-five meters completely blind to sudden braking vehicles, road debris, or merging traffic. Empirical transportation research demonstrates that digital roadside billboards significantly increase driver distraction and collision rates, especially during hazardous nocturnal driving.

Equally important is the preservation of natural landscape beauty and the defense of public space against visual pollution. Scenic countryside vistas, mountain valleys, and coastal horizons belong to all citizens as a shared natural heritage. Allowing private corporations to commodify these landscapes with garish commercial advertisements degrades the environment and inflicts continuous sensory commercial bombardment on the public. Jurisdictions that banned billboards, such as several progressive states and nations, preserved pristine natural beauty and enhanced scenic tourism without any negative impact on overall commerce.

In summary, commercial billboards compromise highway safety and deface natural landscapes for private corporate gain. Banning roadside advertising protects human lives and preserves the dignity of our natural environment.', 0, 1200, 15, 'medium', 'Support banning billboards along national highways. Emphasize driver distraction and collision physics in body 1, highlight visual pollution and scenic heritage in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-044', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Compulsory Culinary Education in Secondary Schools', 'Secondary schools should make practical culinary instruction and nutritional science a compulsory graduation requirement for all students.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Modern industrial food production has flooded society with ultra-processed convenience foods, contributing to unprecedented global rates of lifestyle diseases among young adults. I firmly agree that secondary schools should make practical cooking classes and nutritional science a mandatory graduation requirement for all students.

The primary benefit of mandatory culinary education is equipping adolescents with fundamental survival skills for health and economic self-sufficiency. Millions of young adults leave home for university or employment completely incapable of preparing a simple nutritious meal from scratch. Consequently, they become entirely dependent on expensive fast-food delivery apps and sodium-laden processed meals, directly driving obesity, cardiovascular pathology, and financial distress. Teaching students how to select fresh seasonal ingredients, prepare balanced home-cooked meals, and understand macronutrient biology empowers them to take control of their long-term physical health and household budgets.

Furthermore, culinary instruction provides a wonderful cross-disciplinary laboratory for applied science, chemistry, and cultural appreciation. Cooking involves precise temperature chemistry, microbial fermentation, and mathematical recipe scaling. Preparing traditional dishes from diverse cultures also fosters cross-cultural empathy and communal cooperation. While critics may argue that school budgets cannot afford kitchen laboratories, the societal return in reduced chronic disease healthcare expenditures far exceeds the cost of installing basic instructional stoves.

In conclusion, cooking is an indispensable biological life skill that modern education has dangerously neglected. Making culinary education compulsory ensures that future generations possess the skills to nourish themselves sustainably and affordably.', 0, 1200, 15, 'medium', 'Support compulsory culinary and nutrition education in secondary schools. Detail self-sufficiency and prevention of ultra-processed food health crises in body 1, explore STEM/cultural benefits in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-045', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Taxpayer Funding for Historical Monument Conservation', 'Governments should allocate substantial public taxpayer funds to restore and conserve ancient historical monuments rather than leaving preservation to private charities.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Historical monuments, ancient temples, and archaeological landmarks constitute the physical memory and cultural soul of human civilization. I strongly agree that national governments should allocate dedicated taxpayer funds to restore and preserve historical monuments rather than relying on unpredictable private philanthropic donations.

The foremost justification for public funding of monument conservation is that cultural heritage is a vital public good and the collective property of the entire nation. Ancient architectural treasures embody national history, artistic genius, and shared cultural identity. Relying on private charities or wealthy benefactors leaves conservation vulnerable to shifting philanthropic whims; obscure but historically crucial monuments are neglected, while only glamorous, high-profile sites receive donations. A dedicated public preservation agency ensures systematic, long-term scientific conservation conducted by certified architectural experts, safeguarding national history against structural collapse, climate weathering, and natural disasters.

Furthermore, investing public funds in historic conservation yields massive economic dividends through cultural tourism and regional revitalization. Conserving ancient monuments attracts millions of domestic and international visitors, generating billions in revenue for local transportation, hospitality, and handicraft sectors, which creates thousands of regional jobs. Far from being a wasteful expense, public monument conservation is a self-sustaining investment that enriches national pride and stimulates local economies.

In conclusion, preserving historical heritage is an essential national duty that cannot be outsourced to private charity. Taxpayer funding guarantees that ancient monuments endure as enduring beacons of cultural heritage for future generations.', 0, 1200, 15, 'medium', 'Support taxpayer funding for restoring historical monuments. Discuss monuments as public goods requiring systematic expert care in body 1, highlight tourism economic multipliers in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-046', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Free-Market Competition and Innovation', 'Unrestricted free-market competition is the single most effective mechanism for driving technological innovation and improving human living standards.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'The driving forces behind technological innovation and societal prosperity have long been at the center of economic debate. While free-market competition plays a vital role in consumer product iteration, I disagree that unrestricted market competition is the primary driver of profound technological innovation.

The primary flaw in the unrestricted free-market model is that private commercial corporations are structurally incapable of funding long-term, high-risk foundational scientific research. Private enterprises are accountable to shareholders who demand quarterly profits and immediate returns on investment. Consequently, commercial firms focus almost exclusively on minor incremental product improvements. History unequivocally demonstrates that the foundational technological breakthroughs that transformed modern human living standards—including the internet, global positioning satellites, touchscreen displays, and lithium battery chemistry—originated not from private corporate competition, but from massive, publicly funded government research programs. The state absorbs the massive financial risks of foundational science, upon which private companies subsequently build commercial applications.

Furthermore, unrestricted market competition inevitably degenerates into monopolistic concentration and predatory price collusion, as dominant corporate giants acquire promising rivals and stifle disruptive innovations that threaten their existing profit streams. True economic dynamism requires strong government antitrust regulation, environmental protections, and public research investments to guide competition toward genuine societal progress.

In conclusion, while market competition excels at consumer distribution, it depends entirely on public investment and regulatory oversight. Unrestricted market competition is an incomplete, flawed engine that requires democratic governance to achieve true human progress.', 0, 1200, 15, 'medium', 'Disagree with the claim that unrestricted free-market competition drives innovation best. Emphasize public funding behind foundational breakthroughs (internet, GPS) in body 1, address monopolistic stagnation in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-047', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Standardization of Electronic Charging Ports', 'Governments should legally mandate a single universal charging port standard for all mobile phones, tablets, and portable electronic devices.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'For decades, consumer electronics manufacturers have marketed devices equipped with proprietary charging ports and non-interchangeable power cables. I strongly agree that governments should mandate a single universal standard charging port across all portable electronic devices to eliminate consumer inconvenience and environmental waste.

The foremost benefit of mandatory port standardization is the massive reduction in consumer electronic waste and resource depletion. Every year, millions of redundant proprietary charging cables and power adapters are discarded into municipal landfills as consumers upgrade devices or switch brands. Manufacturing these disposable cables consumes vast amounts of copper, petroleum-based plastics, and rare-earth metals. Standardizing on a universal port, such as modern reversible high-speed USB-C, allows consumers to power smartphones, laptops, headphones, and cameras using a single interoperable cable, enabling manufacturers to sell devices without bundled chargers and drastically curtailing global electronic waste.

Furthermore, universal standardization delivers immense consumer convenience and substantial economic savings. Consumers are freed from purchasing expensive proprietary replacement cables from monopolistic manufacturers, saving money and eliminating clutter. While technology manufacturers frequently argue that regulatory mandates stifle engineering innovation, international standards can easily be updated through periodic regulatory reviews when substantially faster or superior open charging technologies emerge. Standardizing basic power delivery does not restrict device functionality or computational innovation.

In summary, proprietary charging ports represent an exploitative commercial tactic that generates mountain ranges of electronic waste. Mandating a single universal charging port is a triumph of consumer rights and environmental stewardship.', 0, 1200, 15, 'medium', 'Support mandatory universal charging ports for electronic devices. Detail e-waste reduction and mineral conservation in body 1, address consumer savings and industry innovation claims in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-048', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Satellite Navigation Reliance and Spatial Cognition', 'Continuous reliance on automated satellite navigation systems has significantly degraded the natural spatial orientation and wayfinding abilities of modern humans.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'The ubiquitous integration of satellite navigation applications into smartphones has fundamentally transformed how humans navigate unfamiliar and familiar geographical environments. I firmly agree with the proposition that perpetual reliance on automated navigation algorithms has severely degraded natural human spatial cognition and wayfinding competence.

The primary neurological justification for this view is the atrophy of spatial memory mapping in the brain caused by passive cognitive offloading. For millennia, human navigation required active cognitive engagement: observing environmental landmarks, reading terrain topographies, calculating sun positions, and synthesizing mental cognitive maps within the brain''s hippocampus. Cognitive neuroscience research demonstrates that regular active wayfinding physically enlarges the hippocampus and strengthens spatial memory networks. In stark contrast, following turn-by-turn automated voice prompts requires zero environmental observation; users passively follow directions while remaining oblivious to their surroundings. Over time, this passive disuse causes neural atrophy, leaving individuals disoriented and helpless when their digital devices lose battery power or satellite signal.

While automated navigation undeniably saves travel time, reduces driving stress, and prevents missed appointments, convenience should not be mistaken for cognitive health. Passive reliance robs humans of deep geographical awareness and connection to their landscape, detaching people from the physical world. While satellite navigation is an indispensable tool, periodic unassisted navigation is essential to maintain biological cognitive fitness.

In conclusion, outsourcing spatial navigation to automated algorithms has weakened human wayfinding abilities. Consciously exercising natural navigation skills is vital to preserve our evolutionary spatial faculties.', 0, 1200, 15, 'medium', 'Agree that satellite navigation weakens human spatial cognition. Detail hippocampal cognitive mapping and neural atrophy in body 1, address convenience while stressing evolutionary spatial competence in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-049', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Extended Producer Responsibility for Packaging', 'Consumer goods companies should be held legally and financially responsible for collecting and recycling all plastic packaging they produce.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'The global plastic pollution crisis has overwhelmed municipal waste systems and contaminated terrestrial and marine ecosystems with non-biodegradable polymers. I strongly agree that governments should enact extended producer responsibility laws holding consumer goods corporations legally and financially liable for recovering and recycling all plastic packaging they introduce into the market.

The primary economic argument for extended producer responsibility is internalizing the environmental costs of plastic production into the corporate balance sheet. Under current market arrangements, multinational food and beverage corporations generate billions in profits by packaging goods in cheap, single-use plastic, while shifting the costly burdens of collection, landfill management, and environmental cleanup entirely onto municipal taxpayers. Because manufacturers bear zero financial penalty for creating unrecyclable multi-layer plastics, they have no incentive to change. Forcing companies to finance the full lifecycle of their packaging immediately creates a powerful financial motive to eliminate unnecessary packaging, switch to biodegradable materials, and design standardized containers that are easily recycled.

Packaging manufacturers often protest that mandatory take-back laws will inflate retail grocery prices and impose complex logistics on businesses. While corporate packaging costs may increase slightly, these expenses incentivize rapid innovation in refillable container networks and bulk dispensing systems that lower costs over time. Moreover, the financial cost of packaging redesign is dwarfed by the catastrophic environmental cleanup costs and public health damage caused by unchecked plastic waste.

In summary, polluting corporations must pay for the waste they create. Holding manufacturers financially responsible for packaging collection is the single most effective policy to eradicate single-use plastic pollution.', 0, 1200, 15, 'medium', 'Support extended producer responsibility for plastic packaging. Explain internalizing environmental costs and eliminating taxpayer burdens in body 1, address consumer price claims with refillable innovation in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-req-050', 'pte-2026-01', 'PTE', 'writing', 'pte-repeated-essay-questions', 'Repeated Essay Questions', 'Bird Friendly Architectural Glass Mandates', 'Municipal building regulations should require commercial high rise towers to incorporate patterned or treated glass designed to prevent bird collisions.

Do you agree or disagree? Support your point of view with reasons and examples. Write 200-300 words.', NULL, NULL, NULL, NULL, 'Modern architectural design relies heavily on expansive glass facades to maximize interior natural light and create striking urban skylines. However, highly reflective and completely transparent glass represents a lethal hazard for migratory wildlife, causing millions of fatal bird collisions annually. I strongly support the proposal to mandate bird-safe architectural glass on all new commercial high-rise towers.

The primary justification for this mandate is the preservation of avian biodiversity along global migratory flyways. Birds do not perceive clear glass as a solid physical barrier; instead, they see reflections of clouds, sky, and nearby trees, leading them to collide with buildings at full flight velocity. Incorporating bird-friendly architectural glass—which features subtle ceramic frit patterns, acid-etched motifs, or ultraviolet reflective coatings visible to avian eyes but nearly imperceptible to humans—breaks up fatal reflections. Implementing these features along lower building floors and reflective skybridges drastically curtails migratory bird mortality in metropolitan centers.

Real estate developers and architects sometimes object that patterned glass increases manufacturing costs and compromises the clean, transparent aesthetic of modern glass architecture. While specially treated glass does carry a modest initial price premium, incorporating these materials during initial design and construction adds only a minor fraction to total building development budgets. Furthermore, contemporary etched patterns can enhance architectural beauty, provide subtle interior solar shading, and demonstrate corporate environmental responsibility without obstructing panoramic outdoor views for building occupants.

To conclude, urban development should not come at the expense of ecological destruction. Requiring bird-friendly glass in municipal building codes is an ethical, practical measure that protects vulnerable wildlife while maintaining architectural elegance.', 0, 1200, 15, 'medium', 'Support mandatory bird-friendly architectural glass on high-rise buildings. Explain why birds collide with reflective glass and how fritted/etched patterns prevent collisions in body 1, address developer costs and aesthetic concerns in body 2, and conclude.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Repeated Essay Questions'], ARRAY['PTE'], TRUE)
